{
  "name": "VibeStream - Music Microsite Studio",
  "description": "A high-end platform for creating, managing, and sharing sleek music album microsites. Features a pro-grade visualizer, automated liner notes powered by Gemini, and a seamless album management dashboard.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Track {
  id: string;
  title: string;
  artist: string;
  file: File;
  url: string;
  duration?: number;
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  coverImage: string;
  description: string;
  tracks: Track[];
  createdAt: number;
  themeColor: string;
}

export type AppView = 'DASHBOARD' | 'CREATOR' | 'PLAYER';

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAlbumMetadata = async (albumTitle: string, trackNames: string[]) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a compelling, artistic album description and a recommended primary theme color (hex code) for a music album titled "${albumTitle}" with the following tracks: ${trackNames.join(', ')}. The description should sound like it was written by a professional music critic.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: {
              type: Type.STRING,
              description: "An evocative 2-3 paragraph description of the album's vibe.",
            },
            themeColor: {
              type: Type.STRING,
              description: "A sleek hex color code (e.g., #4f46e5) that matches the vibe.",
            },
          },
          required: ["description", "themeColor"],
        },
      },
    });

    const result = JSON.parse(response.text);
    return result;
  } catch (error) {
    console.error("Error generating metadata:", error);
    return {
      description: "A mysterious sonic journey through diverse soundscapes.",
      themeColor: "#6366f1",
    };
  }
};

import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  themeColor: string;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, themeColor }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>();

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;
      const radius = Math.min(width, height) / 4;

      // Draw outer glow/pulse
      let sum = 0;
      for (let i = 0; i < 32; i++) sum += dataArray[i];
      const avgLow = sum / 32;
      const pulse = radius + (avgLow / 255) * 50;

      ctx.beginPath();
      ctx.arc(centerX, centerY, pulse, 0, 2 * Math.PI);
      ctx.strokeStyle = `${themeColor}22`;
      ctx.lineWidth = 15;
      ctx.stroke();

      // Draw visualizer bars
      const barCount = 128;
      const barWidth = 2;

      for (let i = 0; i < barCount; i++) {
        const value = dataArray[i];
        const barHeight = (value / 255) * 120;
        const angle = (i / barCount) * Math.PI * 2;

        const x1 = centerX + Math.cos(angle) * radius;
        const y1 = centerY + Math.sin(angle) * radius;
        const x2 = centerX + Math.cos(angle) * (radius + barHeight);
        const y2 = centerY + Math.sin(angle) * (radius + barHeight);

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.strokeStyle = themeColor;
        ctx.lineWidth = barWidth;
        ctx.lineCap = 'round';
        ctx.stroke();
      }

      // Center disc
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius - 5, 0, 2 * Math.PI);
      ctx.fillStyle = '#0a0a0a';
      ctx.fill();
    };

    render();

    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [analyser, themeColor]);

  return (
    <canvas 
      ref={canvasRef} 
      width={800} 
      height={800} 
      className="w-full max-w-[500px] aspect-square pointer-events-none opacity-80"
    />
  );
};

export default Visualizer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track } from '../types';
import Visualizer from './Visualizer';
import { Play, Pause, SkipBack, SkipForward, Volume2, Share2, ArrowLeft } from 'lucide-react';

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const analyserNode = audioContextRef.current.createAnalyser();
      analyserNode.fftSize = 256;
      setAnalyser(analyserNode);
    }

    if (audioRef.current && !sourceRef.current) {
      sourceRef.current = audioContextRef.current.createMediaElementSource(audioRef.current);
      sourceRef.current.connect(analyser!);
      analyser!.connect(audioContextRef.current.destination);
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') {
      audioContextRef.current.resume();
    }

    if (isPlaying) {
      audioRef.current?.pause();
    } else {
      audioRef.current?.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const onTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration);
    }
  };

  const formatTime = (time: number) => {
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleShare = () => {
    const shareText = `Check out "${album.title}" by ${album.artist} on VibeStream!`;
    if (navigator.share) {
      navigator.share({
        title: album.title,
        text: shareText,
        url: window.location.href,
      });
    } else {
      navigator.clipboard.writeText(`${shareText} ${window.location.href}`);
      alert('Link copied to clipboard!');
    }
  };

  return (
    <div className="min-h-screen relative overflow-hidden bg-black flex flex-col items-center justify-center p-4">
      {/* Background Glow */}
      <div 
        className="absolute inset-0 opacity-20 blur-[120px] transition-colors duration-1000"
        style={{ background: `radial-gradient(circle at center, ${album.themeColor}, transparent 70%)` }}
      />

      <button 
        onClick={onBack}
        className="absolute top-8 left-8 flex items-center gap-2 text-white/50 hover:text-white transition-colors z-10"
      >
        <ArrowLeft size={20} />
        <span className="text-sm font-medium">Studio</span>
      </button>

      <button 
        onClick={handleShare}
        className="absolute top-8 right-8 flex items-center gap-2 text-white/50 hover:text-white transition-colors z-10"
      >
        <Share2 size={20} />
      </button>

      <audio
        ref={audioRef}
        src={currentTrack.url}
        onTimeUpdate={onTimeUpdate}
        onEnded={handleNext}
        autoPlay={isPlaying}
      />

      <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-2 gap-12 items-center z-10">
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left">
          <div className="mb-6">
            <h1 className="text-5xl lg:text-7xl font-display font-bold mb-2 tracking-tighter">{album.title}</h1>
            <p className="text-xl text-white/60 font-medium">{album.artist}</p>
          </div>

          <div className="w-full max-w-md bg-white/5 backdrop-blur-xl border border-white/10 p-8 rounded-3xl mb-8">
            <div className="flex items-center justify-between mb-4">
              <span className="text-xs font-bold uppercase tracking-widest text-white/40">Now Playing</span>
              <span className="text-xs font-mono text-white/40">{currentTrackIndex + 1} / {album.tracks.length}</span>
            </div>
            <h2 className="text-2xl font-bold mb-8 truncate">{currentTrack.title}</h2>

            {/* Progress Bar */}
            <div className="mb-8">
              <div className="relative h-1 w-full bg-white/10 rounded-full overflow-hidden">
                <div 
                  className="absolute h-full transition-all duration-100"
                  style={{ width: `${(currentTime / duration) * 100}%`, backgroundColor: album.themeColor }}
                />
              </div>
              <div className="flex justify-between mt-2 text-[10px] font-mono text-white/40 uppercase tracking-tighter">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(duration)}</span>
              </div>
            </div>

            {/* Controls */}
            <div className="flex items-center justify-center gap-8 mb-8">
              <button onClick={handlePrev} className="text-white/60 hover:text-white transition-colors"><SkipBack fill="currentColor" size={24} /></button>
              <button 
                onClick={togglePlay}
                className="w-16 h-16 rounded-full flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-2xl"
                style={{ backgroundColor: album.themeColor }}
              >
                {isPlaying ? <Pause size={32} /> : <Play fill="white" size={32} className="ml-1" />}
              </button>
              <button onClick={handleNext} className="text-white/60 hover:text-white transition-colors"><SkipForward fill="currentColor" size={24} /></button>
            </div>

            {/* Volume */}
            <div className="flex items-center gap-4 text-white/40">
              <Volume2 size={16} />
              <input 
                type="range" 
                min="0" 
                max="1" 
                step="0.01" 
                value={volume}
                onChange={(e) => {
                  const val = parseFloat(e.target.value);
                  setVolume(val);
                  if (audioRef.current) audioRef.current.volume = val;
                }}
                className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white"
              />
            </div>
          </div>

          <div className="max-w-md">
            <p className="text-white/40 text-sm leading-relaxed italic line-clamp-4">
              {album.description}
            </p>
          </div>
        </div>

        <div className="flex flex-col items-center">
          <Visualizer analyser={analyser} themeColor={album.themeColor} />

          <div className="mt-8 w-full max-w-sm">
             <div className="flex flex-col gap-2">
                {album.tracks.map((track, idx) => (
                  <button 
                    key={track.id}
                    onClick={() => {
                      setCurrentTrackIndex(idx);
                      setIsPlaying(true);
                    }}
                    className={`flex items-center justify-between p-3 rounded-xl transition-all ${
                      currentTrackIndex === idx ? 'bg-white/10 text-white' : 'hover:bg-white/5 text-white/40'
                    }`}
                  >
                    <div className="flex items-center gap-3 overflow-hidden">
                      <span className="text-[10px] font-mono opacity-50">{idx + 1}</span>
                      <span className="text-sm font-medium truncate">{track.title}</span>
                    </div>
                    {currentTrackIndex === idx && isPlaying && (
                      <div className="flex gap-0.5 items-end h-3">
                         <div className="w-0.5 h-full bg-white animate-bounce" style={{ animationDelay: '0ms' }} />
                         <div className="w-0.5 h-2/3 bg-white animate-bounce" style={{ animationDelay: '100ms' }} />
                         <div className="w-0.5 h-full bg-white animate-bounce" style={{ animationDelay: '200ms' }} />
                      </div>
                    )}
                  </button>
                ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PlayerView;

import React, { useState } from 'react';
import { Album, Track } from '../types';
import { generateAlbumMetadata } from '../services/geminiService';
import { Music, Upload, Loader2, X, Plus } from 'lucide-react';

interface AlbumCreatorProps {
  onCreated: (album: Album) => void;
  onCancel: () => void;
}

const AlbumCreator: React.FC<AlbumCreatorProps> = ({ onCreated, onCancel }) => {
  const [title, setTitle] = useState('');
  const [artist, setArtist] = useState('');
  const [tracks, setTracks] = useState<Track[]>([]);
  const [coverImage, setCoverImage] = useState('https://picsum.photos/800/800');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newTracks: Track[] = [];
    const fileArray = Array.from(files);

    for (const file of fileArray) {
      if (file.type.startsWith('audio/')) {
        newTracks.push({
          id: Math.random().toString(36).substr(2, 9),
          title: file.name.replace(/\.[^/.]+$/, "").replace(/^\d+\s*[-_]*\s*/, ""),
          artist: artist || "Unknown Artist",
          file: file,
          url: URL.createObjectURL(file),
        });
      }
    }

    setTracks(prev => [...prev, ...newTracks]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || tracks.length === 0) return;

    setIsGenerating(true);
    const trackNames = tracks.map(t => t.title);
    const metadata = await generateAlbumMetadata(title, trackNames);

    const newAlbum: Album = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      artist: artist || "Unknown Artist",
      coverImage,
      description: metadata.description,
      themeColor: metadata.themeColor,
      tracks,
      createdAt: Date.now(),
    };

    onCreated(newAlbum);
    setIsGenerating(false);
  };

  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center z-50 p-4">
      <div className="max-w-4xl w-full bg-[#111] border border-white/10 rounded-[2rem] overflow-hidden flex flex-col lg:flex-row shadow-2xl">
        {/* Preview Side */}
        <div className="lg:w-2/5 p-8 bg-[#161616] flex flex-col items-center justify-center text-center border-b lg:border-b-0 lg:border-r border-white/5">
          <div className="relative group mb-6">
            <img 
              src={coverImage} 
              alt="Album Cover" 
              className="w-48 h-48 lg:w-64 lg:h-64 rounded-2xl object-cover shadow-2xl mb-6 ring-1 ring-white/10"
            />
            <label className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer rounded-2xl">
              <Plus className="text-white" size={32} />
              <input 
                type="file" 
                className="hidden" 
                accept="image/*"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) setCoverImage(URL.createObjectURL(file));
                }}
              />
            </label>
          </div>
          <h3 className="text-2xl font-bold mb-1 tracking-tight">{title || "Album Title"}</h3>
          <p className="text-white/40">{artist || "Artist Name"}</p>
        </div>

        {/* Form Side */}
        <form onSubmit={handleSubmit} className="flex-1 p-8 lg:p-12 overflow-y-auto max-h-[80vh]">
          <div className="flex items-center justify-between mb-8">
            <h2 className="text-2xl font-display font-bold">New Microsite</h2>
            <button type="button" onClick={onCancel} className="text-white/40 hover:text-white transition-colors">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest text-white/30 mb-2">Title</label>
                <input 
                  type="text" 
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="Midnight Melodies"
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-white/20 transition-all"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest text-white/30 mb-2">Artist</label>
                <input 
                  type="text" 
                  value={artist}
                  onChange={(e) => setArtist(e.target.value)}
                  placeholder="Neon Noir"
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-white/20 transition-all"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold uppercase tracking-widest text-white/30 mb-2">Upload Folder / Tracks</label>
              <div className="relative group">
                <input 
                  type="file" 
                  multiple 
                  accept="audio/*"
                  onChange={handleFolderSelect}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                />
                <div className="w-full h-32 border-2 border-dashed border-white/10 rounded-2xl flex flex-col items-center justify-center gap-2 group-hover:bg-white/5 transition-all">
                  <Upload size={24} className="text-white/40" />
                  <span className="text-sm text-white/40">Select files or drop folder here</span>
                </div>
              </div>
            </div>

            {tracks.length > 0 && (
              <div className="space-y-2">
                <label className="block text-xs font-bold uppercase tracking-widest text-white/30">Tracklist ({tracks.length})</label>
                <div className="max-h-40 overflow-y-auto space-y-1 pr-2">
                  {tracks.map((track, i) => (
                    <div key={track.id} className="flex items-center justify-between p-2 rounded-lg bg-white/5 text-sm">
                      <div className="flex items-center gap-3">
                        <span className="text-white/20 font-mono text-xs">{i + 1}</span>
                        <span className="truncate max-w-[200px]">{track.title}</span>
                      </div>
                      <button 
                        type="button" 
                        onClick={() => setTracks(tracks.filter(t => t.id !== track.id))}
                        className="text-white/20 hover:text-red-400"
                      >
                        <X size={14} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <button 
              type="submit"
              disabled={isGenerating || !title || tracks.length === 0}
              className="w-full py-4 bg-white text-black font-bold rounded-2xl transition-all hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {isGenerating ? (
                <>
                  <Loader2 className="animate-spin" />
                  Generating Liner Notes...
                </>
              ) : (
                'Launch Album Microsite'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AlbumCreator;

import React, { useState, useEffect } from 'react';
import { Album, AppView } from './types';
import AlbumCreator from './components/AlbumCreator';
import PlayerView from './components/PlayerView';
import { Plus, Music2, Layers, Search, MoreVertical, Play } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [albums, setAlbums] = useState<Album[]>([]);
  const [selectedAlbum, setSelectedAlbum] = useState<Album | null>(null);
  const [showCreator, setShowCreator] = useState(false);

  // Initial demo album if no albums exist
  useEffect(() => {
    const savedAlbums = localStorage.getItem('vibestream_albums');
    if (savedAlbums) {
      // Note: Blobs can't be saved to localStorage, so real uploads are session-based in this demo
      // but we could use IndexedDB for persistent audio storage.
    }
  }, []);

  const handleCreateAlbum = (newAlbum: Album) => {
    setAlbums([newAlbum, ...albums]);
    setShowCreator(false);
  };

  const openAlbum = (album: Album) => {
    setSelectedAlbum(album);
    setView('PLAYER');
  };

  return (
    <div className="min-h-screen flex bg-[#0a0a0a]">
      {/* Sidebar - Desktop Only */}
      <aside className="w-64 border-r border-white/5 flex flex-col p-6 hidden lg:flex">
        <div className="flex items-center gap-2 mb-12">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center">
            <Music2 size={18} className="text-white" />
          </div>
          <span className="font-display font-bold text-xl tracking-tighter">VibeStream</span>
        </div>

        <nav className="space-y-2 flex-1">
          <button 
            onClick={() => setView('DASHBOARD')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${view === 'DASHBOARD' ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
          >
            <Layers size={20} />
            <span className="text-sm font-semibold">Studio</span>
          </button>
        </nav>

        <div className="pt-6 border-t border-white/5">
          <p className="text-[10px] font-bold uppercase tracking-widest text-white/20 mb-4 px-4">Beta Feature</p>
          <button 
            onClick={() => setShowCreator(true)}
            className="w-full flex items-center justify-center gap-2 py-3 bg-white text-black rounded-xl font-bold text-sm transition-transform active:scale-95"
          >
            <Plus size={18} />
            Create New
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col">
        {view === 'DASHBOARD' && (
          <div className="p-6 lg:p-12 max-w-7xl mx-auto w-full">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12">
              <div>
                <h1 className="text-4xl lg:text-6xl font-display font-bold mb-3 tracking-tighter">Your Studio</h1>
                <p className="text-white/40 max-w-xl">Manage your music microsites. Each album below is a dedicated webpage with its own visualizer and player.</p>
              </div>

              <div className="flex items-center gap-3">
                 <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-white/20" size={18} />
                    <input 
                      type="text" 
                      placeholder="Search albums..." 
                      className="bg-white/5 border border-white/10 rounded-xl pl-10 pr-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-white/10"
                    />
                 </div>
                 <button 
                  onClick={() => setShowCreator(true)}
                  className="lg:hidden p-2.5 bg-white text-black rounded-xl"
                 >
                   <Plus size={20} />
                 </button>
              </div>
            </header>

            {albums.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-32 border-2 border-dashed border-white/5 rounded-[3rem] bg-white/[0.02]">
                <div className="w-20 h-20 rounded-3xl bg-white/5 flex items-center justify-center mb-6">
                  <Music2 size={32} className="text-white/20" />
                </div>
                <h3 className="text-xl font-bold mb-2">No albums created yet</h3>
