                         </div>
                      </div>
                      <div 
                        className="absolute bottom-4 left-4 right-4 h-1 rounded-full overflow-hidden bg-black/20 backdrop-blur-md"
                      >
                         <div className="h-full w-1/3 opacity-80" style={{ backgroundColor: album.themeColor }} />
                      </div>
                    </div>
                    <div className="flex justify-between items-start">
                      <div>
                        <h3 className="font-bold text-lg mb-0.5 tracking-tight group-hover:text-white transition-colors">{album.title}</h3>
                        <p className="text-sm text-white/40">{album.artist} • {album.tracks.length} Tracks</p>
                      </div>
                      <button className="text-white/20 hover:text-white transition-colors p-1">
                        <MoreVertical size={20} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {view === 'PLAYER' && selectedAlbum && (
          <PlayerView 
            album={selectedAlbum} 
            onBack={() => setView('DASHBOARD')} 
          />
        )}
      </main>

      {showCreator && (
        <AlbumCreator 
          onCreated={handleCreateAlbum} 
          onCancel={() => setShowCreator(false)} 
        />
      )}
    </div>
  );
};

