import React, { useState } from 'react';
import { Album, Track } from '../types';
import { generateAlbumMetadata } from '../services/geminiService';
import { Music, Upload, Loader2, X, Plus } from 'lucide-react';

interface AlbumCreatorProps {
  onCreated: (album: Album) => void;
  onCancel: () => void;
}

const AlbumCreator: React.FC<AlbumCreatorProps> = ({ onCreated, onCancel }) => {
  const [title, setTitle] = useState('');
  const [artist, setArtist] = useState('');
  const [tracks, setTracks] = useState<Track[]>([]);
  const [coverImage, setCoverImage] = useState('https://picsum.photos/800/800');
  const [isGenerating, setIsGenerating] = useState(false);

  // Added explicit type casting (as File[]) to resolve TypeScript 'unknown' errors
  // This ensures properties like 'type' and 'name' are accessible on the iterated file objects
  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newTracks: Track[] = [];
    const fileArray = Array.from(files) as File[];

    for (const file of fileArray) {
      if (file.type.startsWith('audio/')) {
        newTracks.push({
          id: Math.random().toString(36).substr(2, 9),
          title: file.name.replace(/\.[^/.]+$/, "").replace(/^\d+\s*[-_]*\s*/, ""),
          artist: artist || "Unknown Artist",
          file: file,
          url: URL.createObjectURL(file),
        });
      }
    }

    setTracks(prev => [...prev, ...newTracks]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || tracks.length === 0) return;

    setIsGenerating(true);
    const trackNames = tracks.map(t => t.title);
    const metadata = await generateAlbumMetadata(title, trackNames);

    const newAlbum: Album = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      artist: artist || "Unknown Artist",
      coverImage,
      description: metadata.description,
      themeColor: metadata.themeColor,
      tracks,
      createdAt: Date.now(),
    };

    onCreated(newAlbum);
    setIsGenerating(false);
  };

  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center z-50 p-4">
      <div className="max-w-4xl w-full bg-[#111] border border-white/10 rounded-[2rem] overflow-hidden flex flex-col lg:flex-row shadow-2xl">
        {/* Preview Side */}
        <div className="lg:w-2/5 p-8 bg-[#161616] flex flex-col items-center justify-center text-center border-b lg:border-b-0 lg:border-r border-white/5">
          <div className="relative group mb-6">
            <img 
              src={coverImage} 
              alt="Album Cover" 
              className="w-48 h-48 lg:w-64 lg:h-64 rounded-2xl object-cover shadow-2xl mb-6 ring-1 ring-white/10"
            />
            <label className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer rounded-2xl">
              <Plus className="text-white" size={32} />
              <input 
                type="file" 
                className="hidden" 
                accept="image/*"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) setCoverImage(URL.createObjectURL(file));
                }}
              />
            </label>
          </div>
          <h3 className="text-2xl font-bold mb-1 tracking-tight">{title || "Album Title"}</h3>
          <p className="text-white/40">{artist || "Artist Name"}</p>
        </div>

        {/* Form Side */}
        <form onSubmit={handleSubmit} className="flex-1 p-8 lg:p-12 overflow-y-auto max-h-[80vh]">
          <div className="flex items-center justify-between mb-8">
            <h2 className="text-2xl font-display font-bold">New Microsite</h2>
            <button type="button" onClick={onCancel} className="text-white/40 hover:text-white transition-colors">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest text-white/30 mb-2">Title</label>
                <input 
                  type="text" 
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="Midnight Melodies"
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-white/20 transition-all"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest text-white/30 mb-2">Artist</label>
                <input 
                  type="text" 
                  value={artist}
                  onChange={(e) => setArtist(e.target.value)}
                  placeholder="Neon Noir"
                  className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-white/20 transition-all"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold uppercase tracking-widest text-white/30 mb-2">Upload Folder / Tracks</label>
              <div className="relative group">
                <input 
                  type="file" 
                  multiple 
                  accept="audio/*"
                  onChange={handleFolderSelect}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                />
                <div className="w-full h-32 border-2 border-dashed border-white/10 rounded-2xl flex flex-col items-center justify-center gap-2 group-hover:bg-white/5 transition-all">
                  <Upload size={24} className="text-white/40" />
                  <span className="text-sm text-white/40">Select files or drop folder here</span>
                </div>
              </div>
            </div>

            {tracks.length > 0 && (
              <div className="space-y-2">
                <label className="block text-xs font-bold uppercase tracking-widest text-white/30">Tracklist ({tracks.length})</label>
                <div className="max-h-40 overflow-y-auto space-y-1 pr-2">
                  {tracks.map((track, i) => (
                    <div key={track.id} className="flex items-center justify-between p-2 rounded-lg bg-white/5 text-sm">
                      <div className="flex items-center gap-3">
                        <span className="text-white/20 font-mono text-xs">{i + 1}</span>
                        <span className="truncate max-w-[200px]">{track.title}</span>
                      </div>
                      <button 
                        type="button" 
                        onClick={() => setTracks(tracks.filter(t => t.id !== track.id))}
                        className="text-white/20 hover:text-red-400"
                      >
                        <X size={14} />
                      </button>
                    </div>
                  ))}
                </div>
