            )}

            <button 
              type="submit"
              disabled={isGenerating || !title || tracks.length === 0}
              className="w-full py-4 bg-white text-black font-bold rounded-2xl transition-all hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {isGenerating ? (
                <>
                  <Loader2 className="animate-spin" />
                  Generating Liner Notes...
                </>
              ) : (
                'Launch Album Microsite'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

