import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track } from '../types';
import Visualizer from './Visualizer';
import { Play, Pause, SkipBack, SkipForward, Volume2, Share2, ArrowLeft } from 'lucide-react';

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    // 1. Initialize audio context and analyser if they don't exist
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;

      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 256;
      setAnalyser(analyserNode);
    }

    // 2. Connect the audio element to the visualizer only when both are ready
    // We check for 'analyser' explicitly to avoid 'Overload resolution failed' 
    // when 'analyser' state is still null during the first effect run on mount.
    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {
        // Log connection error - sometimes happens if multiple sources are created
        console.warn("Audio connection attempt deferred:", err);
      }
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') {
      audioContextRef.current.resume();
    }

    if (isPlaying) {
      audioRef.current?.pause();
    } else {
      audioRef.current?.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const onTimeUpdate = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration);
    }
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleShare = () => {
    const shareText = `Check out "${album.title}" by ${album.artist} on VibeStream!`;
    if (navigator.share) {
      navigator.share({
        title: album.title,
        text: shareText,
        url: window.location.href,
      }).catch(() => {
        // Fallback if share fails or is cancelled
      });
    } else {
      navigator.clipboard.writeText(`${shareText} ${window.location.href}`);
      alert('Link copied to clipboard!');
    }
  };

  return (
    <div className="min-h-screen relative overflow-hidden bg-black flex flex-col items-center justify-center p-4">
      {/* Background Glow */}
      <div 
        className="absolute inset-0 opacity-20 blur-[120px] transition-colors duration-1000"
        style={{ background: `radial-gradient(circle at center, ${album.themeColor}, transparent 70%)` }}
      />

      <button 
        onClick={onBack}
        className="absolute top-8 left-8 flex items-center gap-2 text-white/50 hover:text-white transition-colors z-10"
      >
        <ArrowLeft size={20} />
        <span className="text-sm font-medium">Studio</span>
      </button>

      <button 
        onClick={handleShare}
        className="absolute top-8 right-8 flex items-center gap-2 text-white/50 hover:text-white transition-colors z-10"
      >
        <Share2 size={20} />
      </button>

      <audio
        ref={audioRef}
        src={currentTrack.url}
        onTimeUpdate={onTimeUpdate}
        onEnded={handleNext}
        autoPlay={isPlaying}
      />

      <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-2 gap-12 items-center z-10">
        <div className="flex flex-col items-center lg:items-start text-center lg:text-left">
          <div className="mb-6">
            <h1 className="text-5xl lg:text-7xl font-display font-bold mb-2 tracking-tighter">{album.title}</h1>
            <p className="text-xl text-white/60 font-medium">{album.artist}</p>
          </div>

          <div className="w-full max-w-md bg-white/5 backdrop-blur-xl border border-white/10 p-8 rounded-3xl mb-8">
            <div className="flex items-center justify-between mb-4">
              <span className="text-xs font-bold uppercase tracking-widest text-white/40">Now Playing</span>
              <span className="text-xs font-mono text-white/40">{currentTrackIndex + 1} / {album.tracks.length}</span>
            </div>
            <h2 className="text-2xl font-bold mb-8 truncate">{currentTrack.title}</h2>

            {/* Progress Bar */}
            <div className="mb-8">
              <div className="relative h-1 w-full bg-white/10 rounded-full overflow-hidden">
                <div 
                  className="absolute h-full transition-all duration-100"
                  style={{ width: `${duration > 0 ? (currentTime / duration) * 100 : 0}%`, backgroundColor: album.themeColor }}
                />
              </div>
              <div className="flex justify-between mt-2 text-[10px] font-mono text-white/40 uppercase tracking-tighter">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(duration)}</span>
              </div>
            </div>

            {/* Controls */}
            <div className="flex items-center justify-center gap-8 mb-8">
              <button onClick={handlePrev} className="text-white/60 hover:text-white transition-colors"><SkipBack fill="currentColor" size={24} /></button>
              <button 
                onClick={togglePlay}
                className="w-16 h-16 rounded-full flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-2xl"
                style={{ backgroundColor: album.themeColor }}
              >
                {isPlaying ? <Pause size={32} /> : <Play fill="white" size={32} className="ml-1" />}
              </button>
              <button onClick={handleNext} className="text-white/60 hover:text-white transition-colors"><SkipForward fill="currentColor" size={24} /></button>
            </div>

            {/* Volume */}
            <div className="flex items-center gap-4 text-white/40">
              <Volume2 size={16} />
              <input 
                type="range" 
                min="0" 
                max="1" 
                step="0.01" 
                value={volume}
                onChange={(e) => {
                  const val = parseFloat(e.target.value);
                  setVolume(val);
                  if (audioRef.current) audioRef.current.volume = val;
                }}
                className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white"
              />
            </div>
          </div>

          <div className="max-w-md">
            <p className="text-white/40 text-sm leading-relaxed italic line-clamp-4">
              {album.description}
            </p>
          </div>
        </div>

        <div className="flex flex-col items-center">
          <Visualizer analyser={analyser} themeColor={album.themeColor} />

          <div className="mt-8 w-full max-w-sm">
             <div className="flex flex-col gap-2">
                {album.tracks.map((track, idx) => (
                  <button 
                    key={track.id}
                    onClick={() => {
                      setCurrentTrackIndex(idx);
                      setIsPlaying(true);
                    }}
                    className={`flex items-center justify-between p-3 rounded-xl transition-all ${
                      currentTrackIndex === idx ? 'bg-white/10 text-white' : 'hover:bg-white/5 text-white/40'
                    }`}
                  >
                    <div className="flex items-center gap-3 overflow-hidden">
                      <span className="text-[10px] font-mono opacity-50">{idx + 1}</span>
                      <span className="text-sm font-medium truncate">{track.title}</span>
                    </div>
                    {currentTrackIndex === idx && isPlaying && (
                      <div className="flex gap-0.5 items-end h-3">
                         <div className="w-0.5 h-full bg-white animate-bounce" style={{ animationDelay: '0ms' }} />
                         <div className="w-0.5 h-2/3 bg-white animate-bounce" style={{ animationDelay: '100ms' }} />
                         <div className="w-0.5 h-full bg-white animate-bounce" style={{ animationDelay: '200ms' }} />
                      </div>
                    )}
                  </button>
                ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

