import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  themeColor: string;
  coverImage: string;
  isPlaying: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, themeColor, coverImage, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>();
  const rotationRef = useRef(0);
  const imgRef = useRef<HTMLImageElement | null>(null);

  useEffect(() => {
    const img = new Image();
    img.src = coverImage;
    img.onload = () => {
      imgRef.current = img;
    };
  }, [coverImage]);

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;
      const radius = Math.min(width, height) / 4.5;

      // Update rotation if playing
      if (isPlaying) {
        rotationRef.current += 0.01;
      }

      // Draw outer glow/pulse based on bass
      let sum = 0;
      for (let i = 0; i < 16; i++) sum += dataArray[i];
      const avgLow = sum / 16;
      const pulse = radius + (avgLow / 255) * 40;

      ctx.beginPath();
      ctx.arc(centerX, centerY, pulse + 10, 0, 2 * Math.PI);
      ctx.strokeStyle = `${themeColor}15`;
      ctx.lineWidth = 20;
      ctx.stroke();

      // Draw visualizer bars
      const barCount = 100;
      for (let i = 0; i < barCount; i++) {
        const value = dataArray[i];
        const barHeight = (value / 255) * 100;
        const angle = (i / barCount) * Math.PI * 2 + rotationRef.current;

        const x1 = centerX + Math.cos(angle) * (radius + 5);
        const y1 = centerY + Math.sin(angle) * (radius + 5);
        const x2 = centerX + Math.cos(angle) * (radius + 5 + barHeight);
        const y2 = centerY + Math.sin(angle) * (radius + 5 + barHeight);

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.strokeStyle = themeColor;
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.stroke();
      }

      // Draw the central disc with album art
      ctx.save();
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.clip();

      if (imgRef.current) {
        ctx.translate(centerX, centerY);
        ctx.rotate(rotationRef.current);
        ctx.drawImage(imgRef.current, -radius, -radius, radius * 2, radius * 2);
      } else {
        ctx.fillStyle = '#111';
        ctx.fill();
      }
      ctx.restore();

      // Central hole for the "record"
      ctx.beginPath();
      ctx.arc(centerX, centerY, 8, 0, Math.PI * 2);
      ctx.fillStyle = '#0a0a0a';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.lineWidth = 2;
      ctx.stroke();
    };

    render();

    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [analyser, themeColor, isPlaying]);

  return (
    <canvas 
      ref={canvasRef} 
      width={1000} 
      height={1000} 
      className="w-full max-w-[600px] aspect-square pointer-events-none drop-shadow-[0_0_50px_rgba(0,0,0,0.5)]"
    />
  );
};

export default Visualizer;

