    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') {
      audioContextRef.current.resume();
    }
    if (isPlaying) {
      audioRef.current?.pause();
    } else {
      audioRef.current?.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleShare = (platform?: string) => {
    const shareText = `Listening to "${album.title}" by ${album.artist} on VibeStream!`;
    const shareUrl = window.location.href;

    if (platform === 'twitter') {
      window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(shareUrl)}`);
    } else if (navigator.share) {
      navigator.share({ title: album.title, text: shareText, url: shareUrl }).catch(() => {});
    } else {
      navigator.clipboard.writeText(`${shareText} ${shareUrl}`);
      alert('Link copied to clipboard!');
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-white selection:text-black">
      {/* Dynamic Header Banner */}
      <div className="relative h-[40vh] lg:h-[50vh] overflow-hidden">
        <div 
          className="absolute inset-0 bg-cover bg-center scale-110 blur-2xl opacity-40 transition-all duration-1000"
          style={{ backgroundImage: `url(${album.headerImage || album.coverImage})` }}
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#050505] via-transparent to-black/30" />

        <div className="absolute inset-0 flex flex-col justify-end p-8 lg:p-20 max-w-7xl mx-auto w-full">
           <button 
            onClick={onBack}
            className="absolute top-8 left-8 flex items-center gap-2 text-white/50 hover:text-white transition-all hover:-translate-x-1 z-20 bg-black/20 backdrop-blur-md px-4 py-2 rounded-full"
          >
            <ArrowLeft size={18} />
            <span className="text-xs font-bold uppercase tracking-widest">Studio</span>
          </button>

          <div className="relative z-10 animate-in fade-in slide-in-from-bottom-4 duration-1000">
            <h1 className="text-6xl lg:text-9xl font-display font-bold tracking-tighter mb-4">{album.title}</h1>
            <div className="flex items-center gap-6">
              <p className="text-xl lg:text-3xl text-white/60 font-medium">{album.artist}</p>
              <div className="flex gap-2">
                <button onClick={() => handleShare('twitter')} className="p-2 bg-white/5 hover:bg-white/10 rounded-full transition-colors"><Twitter size={18} /></button>
                <button onClick={() => handleShare()} className="p-2 bg-white/5 hover:bg-white/10 rounded-full transition-colors"><Instagram size={18} /></button>
                <button onClick={() => handleShare()} className="p-2 bg-white/5 hover:bg-white/10 rounded-full transition-colors"><Share2 size={18} /></button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <audio
        ref={audioRef}
        src={currentTrack.url}
        onTimeUpdate={() => {
          if (audioRef.current) {
            setCurrentTime(audioRef.current.currentTime);
            setDuration(audioRef.current.duration);
          }
        }}
        onEnded={handleNext}
        autoPlay={isPlaying}
      />

      {/* Content Grid */}
      <div className="max-w-7xl mx-auto px-8 lg:px-20 py-12 lg:py-20 grid grid-cols-1 lg:grid-cols-12 gap-16 relative">
        {/* Left Column: Visualizer & Player */}
        <div className="lg:col-span-7 flex flex-col items-center">
          <Visualizer 
            analyser={analyser} 
            themeColor={album.themeColor} 
            coverImage={album.coverImage}
            isPlaying={isPlaying}
          />

          <div className="w-full max-w-xl mt-12 bg-white/[0.03] backdrop-blur-2xl border border-white/5 p-8 lg:p-10 rounded-[3rem]">
            <div className="flex items-center justify-between mb-8">
              <div className="flex flex-col">
                <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-white/30 mb-1">Now Playing</span>
                <h2 className="text-2xl font-bold truncate">{currentTrack.title}</h2>
              </div>
              <span className="text-xs font-mono text-white/30 bg-white/5 px-3 py-1 rounded-full">{currentTrackIndex + 1} / {album.tracks.length}</span>
            </div>

            <div className="mb-10">
              <div className="relative h-1.5 w-full bg-white/5 rounded-full overflow-hidden cursor-pointer">
                <div 
                  className="absolute h-full transition-all duration-150"
                  style={{ width: `${duration > 0 ? (currentTime / duration) * 100 : 0}%`, backgroundColor: album.themeColor }}
                />
              </div>
              <div className="flex justify-between mt-3 text-[10px] font-mono text-white/40 tracking-wider">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(duration)}</span>
              </div>
            </div>

            <div className="flex items-center justify-center gap-10 mb-10">
              <button onClick={handlePrev} className="text-white/40 hover:text-white transition-all transform hover:scale-110 active:scale-95"><SkipBack fill="currentColor" size={28} /></button>
              <button 
                onClick={togglePlay}
                className="w-20 h-20 rounded-full flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-[0_0_50px_rgba(255,255,255,0.1)] group"
                style={{ backgroundColor: album.themeColor }}
              >
                {isPlaying ? <Pause size={36} /> : <Play fill="white" size={36} className="ml-1" />}
              </button>
              <button onClick={handleNext} className="text-white/40 hover:text-white transition-all transform hover:scale-110 active:scale-95"><SkipForward fill="currentColor" size={28} /></button>
            </div>

            <div className="flex items-center gap-5 text-white/20">
              <Volume2 size={18} />
              <input 
                type="range" min="0" max="1" step="0.01" value={volume}
