import React, { useState } from 'react';
import { Album, Track } from '../types';
import { generateAlbumMetadata } from '../services/geminiService';
import { Music, Upload, Loader2, X, Plus, Image as ImageIcon } from 'lucide-react';

interface AlbumCreatorProps {
  onCreated: (album: Album) => void;
  onCancel: () => void;
}

const AlbumCreator: React.FC<AlbumCreatorProps> = ({ onCreated, onCancel }) => {
  const [title, setTitle] = useState('');
  const [artist, setArtist] = useState('');
  const [tracks, setTracks] = useState<Track[]>([]);
  const [coverImage, setCoverImage] = useState('https://images.unsplash.com/photo-1614613535308-eb5fbd3d2c17?q=80&w=1000&auto=format&fit=crop');
  const [headerImage, setHeaderImage] = useState<string | undefined>(undefined);
  const [isGenerating, setIsGenerating] = useState(false);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newTracks: Track[] = [];
    const fileArray = Array.from(files) as File[];

    for (const file of fileArray) {
      if (file.type.startsWith('audio/')) {
        newTracks.push({
          id: Math.random().toString(36).substr(2, 9),
          title: file.name.replace(/\.[^/.]+$/, "").replace(/^\d+\s*[-_]*\s*/, ""),
          artist: artist || "Unknown Artist",
          file: file,
          url: URL.createObjectURL(file),
        });
      }
    }

    setTracks(prev => [...prev, ...newTracks]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || tracks.length === 0) return;

    setIsGenerating(true);
    const trackNames = tracks.map(t => t.title);
    const metadata = await generateAlbumMetadata(title, trackNames);

    const newAlbum: Album = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      artist: artist || "Unknown Artist",
      coverImage,
      headerImage: headerImage || coverImage,
      description: metadata.description,
      themeColor: metadata.themeColor,
      tracks,
      createdAt: Date.now(),
    };

    onCreated(newAlbum);
    setIsGenerating(false);
  };

  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center z-50 p-4">
      <div className="max-w-5xl w-full bg-[#0a0a0a] border border-white/10 rounded-[2.5rem] overflow-hidden flex flex-col lg:flex-row shadow-2xl h-[90vh]">
        {/* Preview Side */}
        <div className="lg:w-2/5 p-12 bg-white/[0.02] flex flex-col items-center justify-center text-center border-b lg:border-b-0 lg:border-r border-white/5 relative">
          <div className="absolute top-0 left-0 w-full h-1/2 bg-gradient-to-b from-white/[0.02] to-transparent pointer-events-none" />

          <div className="relative group mb-8">
            <img 
              src={coverImage} 
              alt="Album Cover" 
              className="w-56 h-56 lg:w-72 lg:h-72 rounded-[2rem] object-cover shadow-[0_40px_80px_rgba(0,0,0,0.8)] mb-6 ring-1 ring-white/10"
            />
            <label className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-all cursor-pointer rounded-[2rem] backdrop-blur-sm">
              <div className="flex flex-col items-center gap-2">
                <ImageIcon className="text-white" size={32} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Update Art</span>
              </div>
              <input 
                type="file" 
                className="hidden" 
                accept="image/*"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) setCoverImage(URL.createObjectURL(file));
                }}
              />
            </label>
          </div>

          <h3 className="text-3xl font-display font-bold mb-2 tracking-tighter">{title || "Album Title"}</h3>
          <p className="text-white/40 font-medium tracking-wide">{artist || "Artist Name"}</p>

          <div className="mt-10 flex flex-col items-center gap-4">
             <label className="flex items-center gap-3 px-6 py-2 bg-white/5 hover:bg-white/10 rounded-full cursor-pointer border border-white/5 transition-colors group">
                <ImageIcon size={16} className="text-white/30 group-hover:text-white" />
                <span className="text-[10px] font-bold uppercase tracking-widest text-white/50 group-hover:text-white">
                  {headerImage ? 'Header Image Set' : 'Custom Header Banner'}
                </span>
                <input 
                  type="file" 
                  className="hidden" 
                  accept="image/*"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) setHeaderImage(URL.createObjectURL(file));
                  }}
                />
             </label>
             {headerImage && (
               <button onClick={() => setHeaderImage(undefined)} className="text-[10px] font-bold text-white/20 hover:text-red-500 uppercase tracking-widest">Remove Custom Header</button>
             )}
          </div>
        </div>

        {/* Form Side */}
        <form onSubmit={handleSubmit} className="flex-1 p-12 lg:p-16 overflow-y-auto custom-scrollbar">
          <div className="flex items-center justify-between mb-12">
            <div>
              <h2 className="text-3xl font-display font-bold tracking-tight mb-2">Microsite Studio</h2>
              <p className="text-white/30 text-sm">Create a standalone digital experience for your album.</p>
            </div>
            <button type="button" onClick={onCancel} className="p-3 bg-white/5 rounded-2xl text-white/40 hover:text-white hover:bg-white/10 transition-all">
              <X size={20} />
            </button>
          </div>

          <div className="space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-white/30 ml-1">Album Title</label>
                <input 
                  type="text" 
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="Midnight Melodies"
                  className="w-full bg-white/[0.03] border border-white/5 rounded-2xl px-6 py-4 text-white focus:outline-none focus:ring-1 focus:ring-white/20 transition-all"
                  required
                />
              </div>
              <div className="space-y-2">
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-white/30 ml-1">Artist Name</label>
                <input 
                  type="text" 
                  value={artist}
                  onChange={(e) => setArtist(e.target.value)}
                  placeholder="Neon Noir"
                  className="w-full bg-white/[0.03] border border-white/5 rounded-2xl px-6 py-4 text-white focus:outline-none focus:ring-1 focus:ring-white/20 transition-all"
                />
              </div>
            </div>

            <div className="space-y-4">
              <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-white/30 ml-1">Track Files</label>
              <div className="relative group">
                <input 
                  type="file" multiple accept="audio/*"
                  onChange={handleFolderSelect}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                />
                <div className="w-full py-12 border-2 border-dashed border-white/5 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 group-hover:bg-white/[0.02] group-hover:border-white/20 transition-all">
                  <div className="p-5 rounded-full bg-white/5 text-white/40 group-hover:text-white transition-all">
                    <Upload size={32} />
                  </div>
                  <div className="text-center">
                    <p className="text-sm font-medium text-white/60 mb-1">Upload Folder or Files</p>
                    <p className="text-[10px] text-white/20 uppercase tracking-widest">Supports MP3, WAV, FLAC</p>
                  </div>
                </div>
              </div>
            </div>

            {tracks.length > 0 && (
              <div className="space-y-4 animate-in fade-in slide-in-from-top-4 duration-500">
                <div className="flex items-center justify-between px-1">
                  <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-white/30">Imported Tracks ({tracks.length})</label>
                  <button type="button" onClick={() => setTracks([])} className="text-[10px] font-bold text-white/20 hover:text-red-500 uppercase tracking-widest">Clear All</button>
                </div>
                <div className="grid grid-cols-1 gap-2 max-h-56 overflow-y-auto pr-4 custom-scrollbar">
                  {tracks.map((track, i) => (
                    <div key={track.id} className="flex items-center justify-between p-4 rounded-2xl bg-white/[0.02] border border-white/5 group hover:bg-white/[0.04] transition-all">
                      <div className="flex items-center gap-4 overflow-hidden">
                        <span className="text-[10px] font-mono text-white/20">{String(i + 1).padStart(2, '0')}</span>
                        <span className="text-sm font-medium truncate tracking-tight">{track.title}</span>
                      </div>
                      <button 
                        type="button" 
                        onClick={() => setTracks(tracks.filter(t => t.id !== track.id))}
                        className="text-white/20 hover:text-red-400 transition-colors"
                      >
                        <X size={16} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="pt-8">
              <button 
                type="submit"
                disabled={isGenerating || !title || tracks.length === 0}
                className="w-full py-5 bg-white text-black font-black uppercase tracking-widest rounded-full transition-all hover:scale-[1.01] active:scale-[0.99] shadow-2xl disabled:opacity-30 disabled:cursor-not-allowed flex items-center justify-center gap-3"
              >
                {isGenerating ? (
                  <>
                    <Loader2 className="animate-spin" size={20} />
                    <span>Engaging Creative Intelligence...</span>
                  </>
                ) : (
                  'Launch Digital Experience'
                )}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AlbumCreator;

import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  themeColor: string;
  coverImage: string;
  isPlaying: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, themeColor, coverImage, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>();
  const rotationRef = useRef(0);
  const imgRef = useRef<HTMLImageElement | null>(null);

  useEffect(() => {
    const img = new Image();
    img.src = coverImage;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      imgRef.current = img;
    };
  }, [coverImage]);

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      const centerX = width / 2;
      const centerY = height / 2;
      const radius = Math.min(width, height) / 4.2;

      // Update rotation if playing
      if (isPlaying) {
        rotationRef.current += 0.005;
      }

      // Draw bass-driven glow
      let sum = 0;
      for (let i = 0; i < 12; i++) sum += dataArray[i];
      const avgLow = sum / 12;
      const pulse = radius + (avgLow / 255) * 60;

      const gradient = ctx.createRadialGradient(centerX, centerY, radius, centerX, centerY, pulse + 40);
      gradient.addColorStop(0, `${themeColor}44`);
      gradient.addColorStop(1, 'transparent');

      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(centerX, centerY, pulse + 40, 0, Math.PI * 2);
      ctx.fill();

      // Draw visualizer bars (radial)
      const barCount = 120;
      for (let i = 0; i < barCount; i++) {
        const value = dataArray[i];
        const barHeight = (value / 255) * 120;
        const angle = (i / barCount) * Math.PI * 2 + rotationRef.current;

        const x1 = centerX + Math.cos(angle) * (radius + 10);
        const y1 = centerY + Math.sin(angle) * (radius + 10);
        const x2 = centerX + Math.cos(angle) * (radius + 10 + barHeight);
        const y2 = centerY + Math.sin(angle) * (radius + 10 + barHeight);

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.strokeStyle = themeColor;
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.stroke();
      }

      // Draw central spinning disc
      ctx.save();
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
      ctx.clip();

      if (imgRef.current) {
        ctx.translate(centerX, centerY);
        ctx.rotate(rotationRef.current);
        // Draw image to fill circular area
        const img = imgRef.current;
        const size = radius * 2;
        ctx.drawImage(img, -radius, -radius, size, size);

        // Vinyl grooves overlay
        ctx.restore();
        ctx.save();
        ctx.globalAlpha = 0.2;
        for (let j = 10; j < radius; j += 15) {
            ctx.beginPath();
            ctx.arc(centerX, centerY, j, 0, Math.PI * 2);
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 1;
            ctx.stroke();
        }
      } else {
        ctx.fillStyle = '#111';
        ctx.fill();
      }
      ctx.restore();

      // Center "spindle"
      ctx.beginPath();
      ctx.arc(centerX, centerY, 6, 0, Math.PI * 2);
      ctx.fillStyle = '#050505';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.2)';
      ctx.lineWidth = 1;
      ctx.stroke();
    };

    render();

    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [analyser, themeColor, isPlaying]);

  return (
    <canvas 
      ref={canvasRef} 
      width={1200} 
      height={1200} 
      className="w-full max-w-[650px] aspect-square pointer-events-none drop-shadow-[0_0_80px_rgba(0,0,0,0.6)]"
    />
  );
};

export default Visualizer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track } from '../types';
import Visualizer from './Visualizer';
import { Play, Pause, SkipBack, SkipForward, Volume2, Share2, ArrowLeft, Twitter, Instagram, ExternalLink } from 'lucide-react';

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

