import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track } from '../types';
import Visualizer from './Visualizer';
import { Play, Pause, SkipBack, SkipForward, Volume2, Share2, ArrowLeft, Twitter, Instagram, ExternalLink, Repeat, Repeat1 } from 'lucide-react';

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
}

type RepeatMode = 'off' | 'all' | 'one';

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [repeatMode, setRepeatMode] = useState<RepeatMode>('all');
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;

      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 1024; // Increased for smoother visuals
      analyserNode.smoothingTimeConstant = 0.8;
      setAnalyser(analyserNode);
    }

    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {
        console.warn("Audio connection attempt deferred:", err);
      }
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') {
      audioContextRef.current.resume();
    }
    if (isPlaying) {
      audioRef.current?.pause();
    } else {
      audioRef.current?.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback((isAuto: boolean = false) => {
    if (isAuto && repeatMode === 'one') {
      if (audioRef.current) {
        audioRef.current.currentTime = 0;
        audioRef.current.play();
      }
      return;
    }

    const isLastTrack = currentTrackIndex === album.tracks.length - 1;

    if (isAuto && repeatMode === 'off' && isLastTrack) {
      setIsPlaying(false);
      return;
    }

    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length, repeatMode, currentTrackIndex]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const toggleRepeatMode = () => {
    const modes: RepeatMode[] = ['off', 'all', 'one'];
    const currentIndex = modes.indexOf(repeatMode);
    setRepeatMode(modes[(currentIndex + 1) % modes.length]);
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleShare = (platform?: string) => {
    const shareText = `Listening to "${album.title}" by ${album.artist} on VibeStream!`;
    const shareUrl = window.location.href;

    if (platform === 'twitter') {
      window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(shareUrl)}`);
    } else if (navigator.share) {
      navigator.share({ title: album.title, text: shareText, url: shareUrl }).catch(() => {});
    } else {
      navigator.clipboard.writeText(`${shareText} ${shareUrl}`);
      alert('Link copied to clipboard!');
    }
  };

  return (
    <div className="min-h-screen bg-[#020202] text-white selection:bg-white selection:text-black">
      {/* Immersive Header */}
      <div className="relative h-[45vh] lg:h-[60vh] overflow-hidden">
        <div 
          className="absolute inset-0 bg-cover bg-center scale-105 opacity-50 blur-xl transition-all duration-1000"
          style={{ backgroundImage: `url(${album.headerImage || album.coverImage})` }}
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#020202] via-[#020202]/40 to-black/40" />

        <div className="absolute inset-0 flex flex-col justify-end p-10 lg:p-24 max-w-7xl mx-auto w-full">
           <button 
            onClick={onBack}
            className="absolute top-10 left-10 flex items-center gap-2 text-white/50 hover:text-white transition-all hover:-translate-x-1 z-20 bg-white/5 backdrop-blur-xl px-5 py-2.5 rounded-full border border-white/5"
          >
            <ArrowLeft size={18} />
            <span className="text-xs font-bold uppercase tracking-widest">Back to Studio</span>
          </button>

          <div className="relative z-10 animate-in fade-in slide-in-from-bottom-8 duration-1000">
            <h1 className="text-7xl lg:text-[10rem] font-display font-black tracking-tighter mb-6 leading-none">{album.title}</h1>
            <div className="flex flex-col md:flex-row md:items-center gap-8">
              <p className="text-2xl lg:text-4xl text-white/70 font-medium">{album.artist}</p>
              <div className="flex gap-3">
                <button onClick={() => handleShare('twitter')} className="p-3 bg-white/5 hover:bg-white/10 rounded-full transition-all hover:scale-110"><Twitter size={20} /></button>
                <button onClick={() => handleShare()} className="p-3 bg-white/5 hover:bg-white/10 rounded-full transition-all hover:scale-110"><Instagram size={20} /></button>
                <button onClick={() => handleShare()} className="p-3 bg-white/5 hover:bg-white/10 rounded-full transition-all hover:scale-110"><Share2 size={20} /></button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <audio
        ref={audioRef}
        src={currentTrack.url}
        onTimeUpdate={() => {
          if (audioRef.current) {
            setCurrentTime(audioRef.current.currentTime);
            setDuration(audioRef.current.duration);
          }
        }}
        onEnded={() => handleNext(true)}
        autoPlay={isPlaying}
      />

      {/* Main Experience Grid */}
      <div className="max-w-7xl mx-auto px-10 lg:px-24 py-16 lg:py-32 grid grid-cols-1 lg:grid-cols-12 gap-24">
        {/* Left Side: Visualizer and Player controls */}
        <div className="lg:col-span-7 flex flex-col items-center">
          <div className="relative w-full flex justify-center">
            <Visualizer 
              analyser={analyser} 
              themeColor={album.themeColor} 
              coverImage={album.coverImage}
              isPlaying={isPlaying}
            />
          </div>

          <div className="w-full max-w-2xl mt-16 bg-white/[0.02] backdrop-blur-3xl border border-white/5 p-10 lg:p-14 rounded-[4rem] shadow-2xl">
            <div className="flex items-center justify-between mb-10">
              <div className="flex flex-col">
                <span className="text-[11px] font-black uppercase tracking-[0.3em] text-white/20 mb-2">Streaming Now</span>
                <h2 className="text-3xl font-bold tracking-tight truncate max-w-[300px]">{currentTrack.title}</h2>
              </div>
              <div className="flex items-center gap-4">
                 <span className="text-[11px] font-mono text-white/30 tracking-widest">{currentTrackIndex + 1} / {album.tracks.length}</span>
              </div>
            </div>

            <div className="mb-12">
              <div 
                className="relative h-2 w-full bg-white/5 rounded-full overflow-hidden cursor-pointer"
                onClick={(e) => {
                   const rect = e.currentTarget.getBoundingClientRect();
                   const x = e.clientX - rect.left;
                   const clickedPercent = x / rect.width;
                   if (audioRef.current) {
                     audioRef.current.currentTime = clickedPercent * duration;
                   }
                }}
              >
                <div 
                  className="absolute h-full transition-all duration-200"
                  style={{ width: `${duration > 0 ? (currentTime / duration) * 100 : 0}%`, backgroundColor: album.themeColor }}
                />
              </div>
              <div className="flex justify-between mt-4 text-[11px] font-mono text-white/30 tracking-widest">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(duration)}</span>
              </div>
            </div>

            <div className="flex items-center justify-center gap-12 mb-12">
              <button 
                onClick={toggleRepeatMode} 
                className={`transition-all ${repeatMode !== 'off' ? 'text-white' : 'text-white/20 hover:text-white/40'}`}
                title={`Repeat Mode: ${repeatMode.toUpperCase()}`}
              >
                {repeatMode === 'one' ? <Repeat1 size={24} /> : <Repeat size={24} />}
              </button>
              <button onClick={handlePrev} className="text-white/30 hover:text-white transition-all transform hover:scale-125"><SkipBack fill="currentColor" size={32} /></button>
              <button 
                onClick={togglePlay}
                className="w-24 h-24 rounded-full flex items-center justify-center transition-all hover:scale-105 active:scale-95 shadow-[0_20px_60px_rgba(255,255,255,0.05)]"
                style={{ backgroundColor: album.themeColor }}
              >
                {isPlaying ? <Pause size={44} /> : <Play fill="white" size={44} className="ml-1" />}
              </button>
              <button onClick={() => handleNext(false)} className="text-white/30 hover:text-white transition-all transform hover:scale-125"><SkipForward fill="currentColor" size={32} /></button>
              <div className="w-6 h-6" /> {/* Spacer for balance */}
            </div>

            <div className="flex items-center gap-6 text-white/10">
              <Volume2 size={20} />
              <input 
                type="range" min="0" max="1" step="0.01" value={volume}
                onChange={(e) => {
                  const val = parseFloat(e.target.value);
                  setVolume(val);
                  if (audioRef.current) audioRef.current.volume = val;
                }}
                className="w-full h-1 bg-white/5 rounded-full appearance-none cursor-pointer accent-white"
              />
            </div>
          </div>
        </div>

        {/* Right Side: Tracklist and Descriptions */}
        <div className="lg:col-span-5 flex flex-col space-y-20">
          <section className="animate-in slide-in-from-right-12 duration-1000">
            <h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-white/20 mb-8 border-b border-white/5 pb-4">Album Philosophy</h3>
            <div className="max-w-none">
              <p className="text-white/50 text-xl leading-relaxed font-light italic indent-8">
                {album.description}
              </p>
            </div>
          </section>

          <section className="animate-in slide-in-from-right-16 duration-1000 delay-200">
            <h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-white/20 mb-8 border-b border-white/5 pb-4">Tracklist</h3>
            <div className="flex flex-col gap-3">
              {album.tracks.map((track, idx) => (
                <button 
                  key={track.id}
                  onClick={() => { setCurrentTrackIndex(idx); setIsPlaying(true); }}
                  className={`group flex items-center justify-between p-6 rounded-[2rem] transition-all border ${
                    currentTrackIndex === idx 
                    ? 'bg-white/5 border-white/10 text-white' 
                    : 'border-transparent hover:bg-white/[0.02] text-white/20'
                  }`}
                >
                  <div className="flex items-center gap-6 overflow-hidden">
                    <span className="text-xs font-mono opacity-20">{String(idx + 1).padStart(2, '0')}</span>
                    <span className="text-lg font-medium truncate tracking-tight">{track.title}</span>
                  </div>
                  {currentTrackIndex === idx && isPlaying ? (
                    <div className="flex gap-1 items-end h-4 pr-2">
                       <div className="w-1 h-full bg-current animate-[bounce_1.2s_infinite]" style={{ animationDelay: '0ms' }} />
                       <div className="w-1 h-2/3 bg-current animate-[bounce_0.8s_infinite]" style={{ animationDelay: '200ms' }} />
                       <div className="w-1 h-full bg-current animate-[bounce_1s_infinite]" style={{ animationDelay: '400ms' }} />
                    </div>
                  ) : (
                    <div className="opacity-0 group-hover:opacity-100 transition-all flex items-center gap-2 text-white/40">
                       <span className="text-[10px] font-black uppercase tracking-widest">Play</span>
                       <Play size={14} fill="currentColor" />
                    </div>
                  )}
                </button>
              ))}
            </div>
          </section>

          <footer className="pt-16 border-t border-white/5 flex flex-col items-center lg:items-start gap-4">
             <div className="flex items-center gap-3 opacity-30">
                <div className="w-7 h-7 rounded-lg bg-white/10 flex items-center justify-center">
                  <ExternalLink size={14} />
                </div>
                <span className="text-xs font-display tracking-[0.3em] font-black uppercase">VibeStream Microsite</span>
             </div>
             <p className="text-[9px] text-white/10 uppercase tracking-[0.5em] text-center lg:text-left">
               Engineered with Gemini AI Intelligence
             </p>
          </footer>
        </div>
      </div>
    </div>
  );
};

