import { GoogleGenAI, Type } from "@google/genai";

export const generateAlbumMetadata = async (albumTitle: string, trackNames: string[]) => {
  // Fix: Create a new GoogleGenAI instance right before making an API call to ensure it uses the up-to-date API key.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a compelling, artistic album description and a recommended primary theme color (hex code) for a music album titled "${albumTitle}" with the following tracks: ${trackNames.join(', ')}. The description should sound like it was written by a professional music critic.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: {
              type: Type.STRING,
              description: "An evocative 2-3 paragraph description of the album's vibe.",
            },
            themeColor: {
              type: Type.STRING,
              description: "A sleek hex color code (e.g., #4f46e5) that matches the vibe.",
            },
          },
          required: ["description", "themeColor"],
        },
      },
    });

    // Fix: Access .text property directly (it's a getter, not a method) as per SDK instructions.
    const result = JSON.parse(response.text);
    return result;
  } catch (error) {
    console.error("Error generating metadata:", error);
    return {
      description: "A mysterious sonic journey through diverse soundscapes.",
      themeColor: "#6366f1",
    };
  }
};

