import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track } from '../types';
import Visualizer from './Visualizer';
import { publishToCloud } from '../services/backendService';
import { Play, Pause, SkipBack, SkipForward, Volume2, Share2, ArrowLeft, Twitter, Instagram, ExternalLink, Repeat, Repeat1, Disc, Zap, Globe, Copy, Check, X, Loader2 } from 'lucide-react';

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
}

type RepeatMode = 'off' | 'all' | 'one';

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [repeatMode, setRepeatMode] = useState<RepeatMode>('all');
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const [showShareModal, setShowShareModal] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [publicUrl, setPublicUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;

      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 1024;
      analyserNode.smoothingTimeConstant = 0.8;
      setAnalyser(analyserNode);
    }

    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {
        console.warn("Audio connection attempt deferred:", err);
      }
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') {
      audioContextRef.current.resume();
    }
    if (isPlaying) {
      audioRef.current?.pause();
    } else {
      audioRef.current?.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback((isAuto: boolean = false) => {
    if (isAuto && repeatMode === 'one') {
      if (audioRef.current) {
        audioRef.current.currentTime = 0;
        audioRef.current.play();
      }
      return;
    }
    const isLastTrack = currentTrackIndex === album.tracks.length - 1;
    if (isAuto && repeatMode === 'off' && isLastTrack) {
      setIsPlaying(false);
      return;
    }
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length, repeatMode, currentTrackIndex]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const toggleRepeatMode = () => {
    const modes: RepeatMode[] = ['off', 'all', 'one'];
    const currentIndex = modes.indexOf(repeatMode);
    setRepeatMode(modes[(currentIndex + 1) % modes.length]);
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    try {
      const url = await publishToCloud(album);
      setPublicUrl(url);
    } catch (err) {
      console.error(err);
    } finally {
      setIsPublishing(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(publicUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-[#020202] text-white selection:bg-white selection:text-black">
      {/* Immersive Cinematic Header */}
      <div className="relative h-[55vh] lg:h-[70vh] overflow-hidden">
        <div 
          className="absolute inset-0 bg-cover bg-center scale-110 opacity-60 blur-2xl transition-all duration-[3000ms]"
          style={{ backgroundImage: `url(${album.headerImage || album.coverImage})` }}
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#020202] via-[#020202]/50 to-black/20" />

        <div className="absolute inset-0 flex flex-col justify-end p-10 lg:p-32 max-w-7xl mx-auto w-full">
           <button 
            onClick={onBack}
            className="absolute top-12 left-10 lg:left-32 flex items-center gap-3 text-white/40 hover:text-white transition-all hover:-translate-x-1 z-20 bg-white/5 backdrop-blur-2xl px-6 py-3 rounded-full border border-white/10 group"
          >
            <ArrowLeft size={18} className="transition-transform group-hover:-translate-x-1" />
            <span className="text-[10px] font-black uppercase tracking-[0.3em]">My Library</span>
          </button>

          <div className="relative z-10 animate-in fade-in slide-in-from-bottom-12 duration-1000">
            <div className="flex items-center gap-3 mb-8">
               <div className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
               <span className="text-[11px] font-black uppercase tracking-[0.5em] text-white/40">Exclusive Digital Edition</span>
            </div>
            <h1 className="text-8xl lg:text-[14rem] font-display font-black tracking-tighter mb-10 leading-[0.8] drop-shadow-2xl">{album.title}</h1>
            <div className="flex flex-col md:flex-row md:items-center gap-10">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 rounded-full overflow-hidden border border-white/10 bg-white/5 flex items-center justify-center p-1">
                  <img src={album.coverImage} className="w-full h-full rounded-full object-cover grayscale opacity-50" />
                </div>
                <p className="text-3xl lg:text-5xl text-white/80 font-medium tracking-tight">{album.artist}</p>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setShowShareModal(true)} className="p-4 bg-white/5 hover:bg-white/10 border border-white/10 rounded-full transition-all hover:scale-110 text-white/60 hover:text-white flex items-center gap-3">
                  <Globe size={22} />
                  <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Publish to Cloud</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <audio
        ref={audioRef}
        src={currentTrack.url}
        onTimeUpdate={() => {
          if (audioRef.current) {
            setCurrentTime(audioRef.current.currentTime);
            setDuration(audioRef.current.duration);
          }
        }}
        onEnded={() => handleNext(true)}
        autoPlay={isPlaying}
      />

      {/* Main Experience Grid */}
      <div className="max-w-7xl mx-auto px-10 lg:px-32 py-24 lg:py-40 grid grid-cols-1 lg:grid-cols-12 gap-32">
        <div className="lg:col-span-7 flex flex-col items-center">
          <div className="relative w-full flex justify-center">
            <Visualizer analyser={analyser} themeColor={album.themeColor} coverImage={album.coverImage} isPlaying={isPlaying} />
          </div>
          <div className="w-full max-w-2xl mt-24 bg-white/[0.03] backdrop-blur-3xl border border-white/5 p-12 lg:p-16 rounded-[4rem] shadow-2xl relative">
            <div className="flex items-center justify-between mb-12">
              <div className="flex flex-col">
                <h2 className="text-4xl font-black tracking-tighter truncate max-w-[400px] mb-2">{currentTrack.title}</h2>
                <div className="flex items-center gap-3">
                   <Disc size={14} className="text-white/20 animate-spin-slow" />
                   <span className="text-[11px] font-black uppercase tracking-[0.3em] text-white/20">{album.artist}</span>
                </div>
              </div>
            </div>
            <div className="mb-14">
              <div 
                className="relative h-2 w-full bg-white/5 rounded-full overflow-hidden cursor-pointer group"
                onClick={(e) => {
                   const rect = e.currentTarget.getBoundingClientRect();
                   const x = e.clientX - rect.left;
                   if (audioRef.current) audioRef.current.currentTime = (x / rect.width) * duration;
                }}
              >
                <div className="absolute h-full" style={{ width: `${duration > 0 ? (currentTime / duration) * 100 : 0}%`, backgroundColor: album.themeColor }} />
              </div>
              <div className="flex justify-between mt-5 text-xs font-mono text-white/20 tracking-widest uppercase">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(duration)}</span>
              </div>
            </div>
            <div className="flex items-center justify-center gap-14 mb-16">
              <button onClick={toggleRepeatMode} className={`transition-all ${repeatMode !== 'off' ? 'text-white scale-110' : 'text-white/10'}`}>
                {repeatMode === 'one' ? <Repeat1 size={28} /> : <Repeat size={28} />}
              </button>
              <button onClick={handlePrev} className="text-white/20 hover:text-white transition-all"><SkipBack fill="currentColor" size={36} /></button>
              <button onClick={togglePlay} className="w-28 h-28 rounded-full flex items-center justify-center transition-all hover:scale-105 shadow-2xl" style={{ backgroundColor: album.themeColor }}>
                {isPlaying ? <Pause size={48} /> : <Play fill="white" size={48} className="ml-2" />}
              </button>
              <button onClick={() => handleNext(false)} className="text-white/20 hover:text-white transition-all"><SkipForward fill="currentColor" size={36} /></button>
            </div>
            <div className="flex items-center gap-8 text-white/10">
              <Volume2 size={22} />
              <input type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => {
                const val = parseFloat(e.target.value);
                setVolume(val);
                if (audioRef.current) audioRef.current.volume = val;
              }} className="w-full h-1 appearance-none bg-white/10 rounded-full" />
            </div>
          </div>
        </div>

        <div className="lg:col-span-5 flex flex-col space-y-24">
          <section>
            <h3 className="text-[11px] font-black uppercase tracking-[0.5em] text-white/20 mb-10 border-b border-white/5 pb-6">Liner Notes</h3>
            <p className="text-white/50 text-2xl lg:text-3xl leading-relaxed font-light italic indent-12">{album.description}</p>
          </section>
          <section>
            <h3 className="text-[11px] font-black uppercase tracking-[0.5em] text-white/20 mb-10 border-b border-white/5 pb-6">Experience Sequence</h3>
            <div className="flex flex-col gap-4">
              {album.tracks.map((track, idx) => (
                <button key={track.id} onClick={() => { setCurrentTrackIndex(idx); setIsPlaying(true); }} className={`group flex items-center justify-between p-8 rounded-[2.5rem] transition-all border ${currentTrackIndex === idx ? 'bg-white/5 border-white/20 text-white' : 'border-transparent text-white/20'}`}>
                  <div className="flex items-center gap-8">
                    <span className="text-xs font-mono opacity-20">{String(idx + 1).padStart(2, '0')}</span>
                    <span className="text-xl font-bold truncate tracking-tight uppercase">{track.title}</span>
                  </div>
                  {currentTrackIndex === idx && isPlaying ? <div className="flex gap-1.5 h-5"><div className="w-1 bg-current animate-bounce" /></div> : <Play size={16} fill="currentColor" />}
                </button>
              ))}
            </div>
          </section>
        </div>
      </div>

      {/* Share/Publish Modal */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-3xl z-[60] flex items-center justify-center p-6">
          <div className="max-w-xl w-full bg-[#0a0a0a] border border-white/10 p-12 rounded-[3rem] shadow-3xl text-center">
            <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 text-white/20 hover:text-white"><X size={32} /></button>
            <div className="w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center mx-auto mb-10">
              <Globe size={40} className="text-white" />
            </div>
            <h2 className="text-4xl font-display font-black tracking-tight mb-4">Go Live</h2>
            <p className="text-white/40 mb-10">Generate a public URL for your microsite. Anyone with this link can experience your album on any device.</p>

            {!publicUrl ? (
              <button 
                onClick={handlePublish}
                disabled={isPublishing}
                className="w-full py-6 bg-white text-black rounded-full font-black uppercase tracking-[0.2em] transition-all hover:scale-105 active:scale-95 flex items-center justify-center gap-3"
              >
                {isPublishing ? <><Loader2 className="animate-spin" /> Publishing to Cloud...</> : 'Launch Public URL'}
              </button>
            ) : (
              <div className="space-y-6 animate-in zoom-in duration-300">
                <div className="flex items-center gap-3 p-6 bg-white/[0.03] border border-white/5 rounded-3xl group">
                   <span className="flex-1 text-left text-sm text-white/60 truncate font-mono">{publicUrl}</span>
                   <button onClick={copyToClipboard} className="p-3 bg-white text-black rounded-2xl transition-all active:scale-90">
