import { Album, Track } from '../types';

/**
 * SERVICE ARCHITECTURE:
 * This service simulates a Google Cloud Storage / Firebase Backend.
 * To enable 'access from anywhere', we upload the audio binaries to a public
 * file host and bundle the metadata into a shareable state.
 */

const FILE_HOST_API = 'https://tmpfiles.org/api/v1/upload';

async function uploadFileToCloud(file: File): Promise<string> {
  const formData = new FormData();
  formData.append('file', file);

  try {
    const response = await fetch(FILE_HOST_API, {
      method: 'POST',
      body: formData,
    });

    if (!response.ok) throw new Error('Cloud Storage Upload Failed');

    const result = await response.json();
    // tmpfiles.org returns a view link, we convert it to a direct download link for streaming
    const viewUrl = result.data.url;
    return viewUrl.replace('tmpfiles.org/', 'tmpfiles.org/dl/');
  } catch (error) {
    console.error("Cloud Upload Error:", error);
    throw error;
  }
}

export const publishToCloud = async (album: Album): Promise<string> => {
  // 1. Upload all track files to the cloud bucket
  const cloudTracks = await Promise.all(
    album.tracks.map(async (track) => {
      if (track.file) {
        const cloudUrl = await uploadFileToCloud(track.file);
        return { ...track, url: cloudUrl, file: undefined }; // Strip local file reference
      }
      return track;
    })
  );

  // 2. Prepare the final "Cloud Album" payload
  const cloudAlbum = {
    ...album,
    tracks: cloudTracks,
  };

  // 3. Serialize and compress the project data for the URL
  // In a full production app, you would save this JSON to Firestore.
  // Here, we use a robust base64 encoding to ensure the link contains the 'Source of Truth'.
  const serialized = btoa(encodeURIComponent(JSON.stringify(cloudAlbum)));

  const publicUrl = `${window.location.origin}${window.location.pathname}?data=${serialized}`;
  return publicUrl;
};

export const fetchProjectFromCloud = async (serializedData: string): Promise<Album | null> => {
  try {
    const json = decodeURIComponent(atob(serializedData));
    const album = JSON.parse(json) as Album;
    return album;
  } catch (error) {
    console.error("Failed to resolve cloud project:", error);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { Album, AppView } from './types';
import AlbumCreator from './components/AlbumCreator';
import PlayerView from './components/PlayerView';
import { getAllLocalAlbums, saveAlbumLocally, deleteLocalAlbum } from './services/storageService';
