  // Load persistence and handle Cloud Routing
  useEffect(() => {
    const initApp = async () => {
      try {
        const params = new URLSearchParams(window.location.search);
        const cloudData = params.get('data');

        if (cloudData) {
          const remoteAlbum = await fetchProjectFromCloud(cloudData);
          if (remoteAlbum) {
            setSelectedAlbum(remoteAlbum);
            setView('PLAYER');
            setIsPublicView(true);
            setIsLoading(false);
            return;
          }
        }

        const savedAlbums = await getAllLocalAlbums();
        setAlbums(savedAlbums);
      } catch (e) {
        console.error("Initialization failure:", e);
