              <Music2 size={20} className="text-black" />
            </div>
            <span className="font-display font-black text-2xl tracking-tighter">VibeStream</span>
          </div>

          <nav className="space-y-3 flex-1">
            <button 
              onClick={() => setView('DASHBOARD')}
              className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${view === 'DASHBOARD' ? 'bg-white/10 text-white border border-white/10' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
            >
              <Layers size={22} />
              <span className="text-sm font-bold tracking-tight">Project Library</span>
            </button>
          </nav>

