import { initializeApp } from 'firebase/app';
import { getStorage, ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { getFirestore, doc, setDoc, getDoc, collection } from 'firebase/firestore';
import { Album, Track } from '../types';

/**
 * PRODUCTION CLOUD CONFIGURATION:
 * These values are typically managed via environment variables.
 * Firebase acts as the secure bridge to Google Cloud Platform services.
 */
const firebaseConfig = {
  apiKey: process.env.API_KEY,
  authDomain: "vibestream-studio.firebaseapp.com",
  projectId: "vibestream-studio",
  storageBucket: "vibestream-studio.appspot.com",
  messagingSenderId: "1234567890",
  appId: "1:1234567890:web:abcdef"
};

const app = initializeApp(firebaseConfig);
const storage = getStorage(app);
const db = getFirestore(app);

/**
 * Uploads a binary file to Google Cloud Storage and returns its public URL.
 */
async function uploadFileToGCS(path: string, file: File, onProgress?: (percent: number) => void): Promise<string> {
  const storageRef = ref(storage, path);
  const uploadTask = uploadBytesResumable(storageRef, file);

  return new Promise((resolve, reject) => {
    uploadTask.on('state_changed', 
      (snapshot) => {
        const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        if (onProgress) onProgress(progress);
      }, 
      (error) => reject(error), 
      async () => {
        const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
        resolve(downloadURL);
      }
    );
  });
}

/**
 * Publishes an entire album project to the cloud.
 */
export const publishToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  onProgress?.("Uploading Audio Assets", 0);

  // 1. Upload all tracks to GCS
  const cloudTracks = await Promise.all(
    album.tracks.map(async (track, index) => {
      if (track.file) {
        const gcsPath = `albums/${album.id}/tracks/${track.id}_${track.file.name}`;
        const cloudUrl = await uploadFileToGCS(gcsPath, track.file, (p) => {
          // Weighted progress for the overall album upload
          const overallProgress = (index / album.tracks.length) * 100 + (p / album.tracks.length);
          onProgress?.(`Uploading: ${track.title}`, Math.round(overallProgress));
        });
        return { ...track, url: cloudUrl, file: undefined };
      }
      return track;
    })
  );

  onProgress?.("Saving Metadata to Cloud Registry", 95);

  // 2. Save Metadata to Firestore
  const cloudAlbum = {
    ...album,
    tracks: cloudTracks,
    publishedAt: Date.now()
  };

  await setDoc(doc(db, "projects", album.id), cloudAlbum);

  onProgress?.("Deployment Complete", 100);

  // Return the public URL
  return `${window.location.origin}${window.location.pathname}?id=${album.id}`;
};

/**
 * Fetches a published project from the Cloud Firestore registry.
 */
export const fetchProjectFromCloud = async (id: string): Promise<Album | null> => {
  try {
    const docRef = doc(db, "projects", id);
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      return docSnap.data() as Album;
    }
    return null;
  } catch (error) {
    console.error("Cloud Retrieval Error:", error);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { Album, AppView } from './types';
import AlbumCreator from './components/AlbumCreator';
import PlayerView from './components/PlayerView';
import { getAllLocalAlbums, saveAlbumLocally, deleteLocalAlbum } from './services/storageService';
import { fetchProjectFromCloud } from './services/backendService';
import { Plus, Music2, Layers, Play, ArrowRight, Zap, Globe, Sparkles, Loader2, Trash2 } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [albums, setAlbums] = useState<Album[]>([]);
  const [selectedAlbum, setSelectedAlbum] = useState<Album | null>(null);
  const [showCreator, setShowCreator] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isPublicView, setIsPublicView] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      try {
        const params = new URLSearchParams(window.location.search);
        const projectId = params.get('id');

        if (projectId) {
          const remoteAlbum = await fetchProjectFromCloud(projectId);
          if (remoteAlbum) {
            setSelectedAlbum(remoteAlbum);
            setView('PLAYER');
            setIsPublicView(true);
            setIsLoading(false);
            return;
          }
        }

        const savedAlbums = await getAllLocalAlbums();
        setAlbums(savedAlbums);
      } catch (e) {
        console.error("Initialization failure:", e);
      } finally {
        setIsLoading(false);
      }
    };
    initApp();
  }, []);

  const handleCreateAlbum = async (newAlbum: Album) => {
    await saveAlbumLocally(newAlbum);
    setAlbums([newAlbum, ...albums]);
    setShowCreator(false);
  };

  const handleDeleteAlbum = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Delete this project from your library?")) {
      await deleteLocalAlbum(id);
      setAlbums(albums.filter(a => a.id !== id));
    }
  };

  const openAlbum = (album: Album) => {
    setSelectedAlbum(album);
    setView('PLAYER');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleBackToDashboard = () => {
    if (isPublicView) {
      window.history.replaceState({}, '', window.location.pathname);
      setIsPublicView(false);
      setSelectedAlbum(null);
    }
    setView('DASHBOARD');
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#020202] flex flex-col items-center justify-center gap-6">
        <div className="relative">
          <div className="w-16 h-16 border-2 border-white/5 rounded-full animate-spin border-t-indigo-500" />
          <Music2 className="absolute inset-0 m-auto text-white/20" size={20} />
        </div>
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-white/20">Syncing with Google Cloud</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex bg-[#020202]">
      {!isPublicView && (
        <aside className="w-72 border-r border-white/5 flex flex-col p-8 hidden lg:flex sticky top-0 h-screen">
          <div className="flex items-center gap-3 mb-16">
            <div className="w-10 h-10 rounded-2xl bg-white flex items-center justify-center shadow-2xl">
              <Music2 size={20} className="text-black" />
            </div>
            <span className="font-display font-black text-2xl tracking-tighter">VibeStream</span>
          </div>
          <nav className="space-y-3 flex-1">
            <button onClick={() => setView('DASHBOARD')} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${view === 'DASHBOARD' ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white'}`}>
              <Layers size={22} />
              <span className="text-sm font-bold">Studio Library</span>
            </button>
