import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track } from '../types';
import Visualizer from './Visualizer';
import { publishToCloud } from '../services/backendService';
import { Play, Pause, SkipBack, SkipForward, Volume2, ArrowLeft, Disc, Globe, Copy, Check, X, Loader2, Cloud, Sparkles } from 'lucide-react';

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const [showShareModal, setShowShareModal] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [publishStatus, setPublishStatus] = useState({ text: '', percent: 0 });
  const [publicUrl, setPublicUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;
      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 1024;
      setAnalyser(analyserNode);
    }
    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {}
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') audioContextRef.current.resume();
    isPlaying ? audioRef.current?.pause() : audioRef.current?.play();
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    try {
      const url = await publishToCloud(album, (text, percent) => {
        setPublishStatus({ text, percent });
      });
      setPublicUrl(url);
    } catch (err) {
      alert("Cloud deployment failed. Check your storage bucket permissions.");
    } finally {
      setIsPublishing(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(publicUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-[#020202] text-white">
      <div className="relative h-[60vh] overflow-hidden">
        <div className="absolute inset-0 bg-cover bg-center opacity-40 blur-3xl scale-110" style={{ backgroundImage: `url(${album.headerImage || album.coverImage})` }} />
        <div className="absolute inset-0 bg-gradient-to-t from-[#020202] to-transparent" />
        <div className="absolute inset-0 flex flex-col justify-end p-10 lg:p-32 max-w-7xl mx-auto w-full">
          <button onClick={onBack} className="absolute top-12 left-10 lg:left-32 flex items-center gap-3 text-white/40 hover:text-white transition-all bg-white/5 px-6 py-3 rounded-full border border-white/10 backdrop-blur-xl">
            <ArrowLeft size={18} />
            <span className="text-[10px] font-black uppercase tracking-[0.3em]">Return</span>
          </button>
          <div className="relative z-10 animate-in fade-in slide-in-from-bottom-8 duration-1000">
            <h1 className="text-7xl lg:text-[12rem] font-display font-black tracking-tighter mb-10 leading-[0.8]">{album.title}</h1>
            <div className="flex flex-col md:flex-row md:items-center gap-10">
              <p className="text-3xl lg:text-5xl text-white/80 font-medium">{album.artist}</p>
              <button onClick={() => setShowShareModal(true)} className="p-4 bg-indigo-600 hover:bg-indigo-500 rounded-full transition-all flex items-center gap-3 shadow-2xl">
                <Cloud size={20} />
                <span className="text-[10px] font-black uppercase tracking-widest px-2">Launch to Cloud</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      <audio ref={audioRef} key={currentTrack.id} src={currentTrack.url} onTimeUpdate={() => { if (audioRef.current) { setCurrentTime(audioRef.current.currentTime); setDuration(audioRef.current.duration); } }} onEnded={handleNext} autoPlay={isPlaying} />

      <div className="max-w-7xl mx-auto px-10 lg:px-32 py-24 grid grid-cols-1 lg:grid-cols-12 gap-32">
        <div className="lg:col-span-7">
          <Visualizer analyser={analyser} themeColor={album.themeColor} coverImage={album.coverImage} isPlaying={isPlaying} />
          <div className="mt-20 bg-white/[0.03] border border-white/5 p-12 rounded-[4rem] relative shadow-3xl">
            <div className="flex justify-between items-end mb-10">
              <div>
                <h2 className="text-4xl font-black mb-2">{currentTrack.title}</h2>
                <div className="flex items-center gap-3 text-white/20"><Disc size={14} className="animate-spin-slow" /> <span className="text-[10px] font-black uppercase tracking-widest">{album.artist}</span></div>
              </div>
            </div>
            <div className="mb-14">
              <div className="h-1 w-full bg-white/5 rounded-full overflow-hidden" onClick={(e) => { const rect = e.currentTarget.getBoundingClientRect(); if (audioRef.current) audioRef.current.currentTime = ((e.clientX - rect.left) / rect.width) * duration; }}>
                <div className="h-full transition-all duration-300" style={{ width: `${(currentTime/duration)*100}%`, backgroundColor: album.themeColor }} />
              </div>
              <div className="flex justify-between mt-5 text-[10px] font-mono text-white/20"><span>{formatTime(currentTime)}</span><span>{formatTime(duration)}</span></div>
            </div>
            <div className="flex items-center justify-center gap-14 mb-16">
              <button onClick={handlePrev} className="text-white/20 hover:text-white"><SkipBack size={36} /></button>
              <button onClick={togglePlay} className="w-24 h-24 rounded-full flex items-center justify-center shadow-2xl" style={{ backgroundColor: album.themeColor }}>{isPlaying ? <Pause size={40} /> : <Play fill="white" size={40} className="ml-1" />}</button>
              <button onClick={handleNext} className="text-white/20 hover:text-white"><SkipForward size={36} /></button>
            </div>
            <div className="flex items-center gap-8 text-white/10"><Volume2 size={20} /><input type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => { setVolume(parseFloat(e.target.value)); if (audioRef.current) audioRef.current.volume = parseFloat(e.target.value); }} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer" /></div>
          </div>
        </div>
        <div className="lg:col-span-5 space-y-24">
          <section><h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-white/20 mb-10 border-b border-white/5 pb-4">Liner Notes</h3><p className="text-white/40 text-2xl leading-relaxed italic">{album.description}</p></section>
          <section><h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-white/20 mb-10 border-b border-white/5 pb-4">Experience Sequence</h3><div className="flex flex-col gap-3">{album.tracks.map((t, i) => (<button key={t.id} onClick={() => { setCurrentTrackIndex(i); setIsPlaying(true); }} className={`flex items-center justify-between p-6 rounded-3xl border transition-all ${currentTrackIndex === i ? 'bg-white/5 border-white/20' : 'border-transparent text-white/20'}`}><span className="font-bold text-lg">{t.title}</span>{currentTrackIndex === i && isPlaying && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse" />}</button>))}</div></section>
        </div>
      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[60] flex items-center justify-center p-6">
          <div className="max-w-xl w-full bg-[#0a0a0a] border border-white/10 p-12 rounded-[3.5rem] text-center relative shadow-3xl">
            <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 text-white/20 hover:text-white"><X size={32} /></button>
            <div className="w-20 h-20 bg-indigo-600/10 rounded-3xl flex items-center justify-center mx-auto mb-10"><Cloud size={40} className="text-indigo-500" /></div>
            <h2 className="text-4xl font-display font-black tracking-tight mb-4">Go Global</h2>
            <p className="text-white/40 mb-10 text-lg">We'll deploy your binaries to Google Cloud Storage for high-speed streaming across all platforms.</p>

            {!publicUrl ? (
              <div className="space-y-8">
                <button onClick={handlePublish} disabled={isPublishing} className="w-full py-6 bg-white text-black rounded-full font-black uppercase tracking-[0.2em] shadow-2xl disabled:opacity-20 flex items-center justify-center gap-3">
                  {isPublishing ? <Loader2 className="animate-spin" /> : <Sparkles size={20} />}
                  {isPublishing ? 'Deploying...' : 'Start Cloud Deployment'}
                </button>
                {isPublishing && (
                  <div className="space-y-4 animate-in fade-in duration-500">
                    <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                      <div className="h-full bg-indigo-500 transition-all duration-500" style={{ width: `${publishStatus.percent}%` }} />
                    </div>
                    <p className="text-[10px] font-black uppercase tracking-widest text-white/30">{publishStatus.text} — {publishStatus.percent}%</p>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-6 animate-in zoom-in duration-500">
                <div className="flex items-center gap-3 p-6 bg-white/[0.03] border border-white/5 rounded-3xl group">
                   <span className="flex-1 text-left text-sm text-white/60 truncate font-mono">{publicUrl}</span>
                   <button onClick={copyToClipboard} className="p-3 bg-white text-black rounded-2xl active:scale-90 shadow-xl">{copied ? <Check size={20} className="text-green-600" /> : <Copy size={20} />}</button>
                </div>
                <div className="p-6 bg-green-500/10 border border-green-500/20 rounded-3xl"><p className="text-[10px] font-black uppercase tracking-widest text-green-500">Live on the Google Cloud CDN Network</p></div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default PlayerView;

import React, { useState, useEffect } from 'react';
import { Album, AppView } from './types';
import AlbumCreator from './components/AlbumCreator';
import PlayerView from './components/PlayerView';
import { getAllLocalAlbums, saveAlbumLocally, deleteLocalAlbum } from './services/storageService';
import { fetchProjectFromCloud } from './services/backendService';
import { Plus, Music2, Layers, Play, ArrowRight, Zap, Globe, Sparkles, Loader2, Trash2, Home } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [albums, setAlbums] = useState<Album[]>([]);
  const [selectedAlbum, setSelectedAlbum] = useState<Album | null>(null);
  const [showCreator, setShowCreator] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isPublicView, setIsPublicView] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      try {
        const params = new URLSearchParams(window.location.search);
        const projectId = params.get('id');

        if (projectId) {
          const remoteAlbum = await fetchProjectFromCloud(projectId);
          if (remoteAlbum) {
            setSelectedAlbum(remoteAlbum);
            setView('PLAYER');
            setIsPublicView(true);
            document.title = `${remoteAlbum.title} by ${remoteAlbum.artist} | VibeStream`;
            setIsLoading(false);
            return;
          }
        }

        const savedAlbums = await getAllLocalAlbums();
        setAlbums(savedAlbums);
        document.title = "VibeStream Studio";
      } catch (e) {
        console.error("Initialization failure:", e);
      } finally {
        setIsLoading(false);
      }
    };
    initApp();
  }, []);

  const handleCreateAlbum = async (newAlbum: Album) => {
    await saveAlbumLocally(newAlbum);
    setAlbums([newAlbum, ...albums]);
    setShowCreator(false);
  };

  const handleDeleteAlbum = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Permanently delete this project from your library?")) {
      await deleteLocalAlbum(id);
      setAlbums(albums.filter(a => a.id !== id));
    }
  };

  const openAlbum = (album: Album) => {
    setSelectedAlbum(album);
    setView('PLAYER');
    document.title = `${album.title} | Studio Preview`;
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleBackToDashboard = () => {
    if (isPublicView) {
      window.history.replaceState({}, '', window.location.pathname);
      setIsPublicView(false);
      setSelectedAlbum(null);
      document.title = "VibeStream Studio";
    }
    setView('DASHBOARD');
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#020202] flex flex-col items-center justify-center gap-6">
        <div className="relative">
          <div className="w-16 h-16 border-2 border-white/5 rounded-full animate-spin border-t-indigo-500" />
          <Music2 className="absolute inset-0 m-auto text-white/20" size={20} />
        </div>
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-white/20">Syncing with Google Cloud CDN</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex bg-[#020202]">
      {!isPublicView && (
        <aside className="w-72 border-r border-white/5 flex flex-col p-8 hidden lg:flex sticky top-0 h-screen">
          <div className="flex items-center gap-3 mb-16">
            <div className="w-10 h-10 rounded-2xl bg-white flex items-center justify-center shadow-2xl">
              <Music2 size={20} className="text-black" />
            </div>
            <span className="font-display font-black text-2xl tracking-tighter">VibeStream</span>
          </div>
          <nav className="space-y-3 flex-1">
            <button onClick={() => setView('DASHBOARD')} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${view === 'DASHBOARD' ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white'}`}>
              <Layers size={22} />
              <span className="text-sm font-bold">Studio Library</span>
            </button>
          </nav>
          <div className="pt-8 border-t border-white/5">
            <button onClick={() => setShowCreator(true)} className="w-full flex items-center justify-center gap-3 py-4 bg-white text-black rounded-2xl font-black text-sm hover:scale-[1.02] shadow-2xl transition-all">
              <Plus size={20} /> Create Microsite
            </button>
          </div>
        </aside>
      )}

      <main className="flex-1 flex flex-col">
        {view === 'DASHBOARD' && (
          <div className="p-8 lg:p-20 max-w-7xl mx-auto w-full">
            {albums.length === 0 ? (
              <div className="min-h-[80vh] flex flex-col items-center justify-center text-center">
                <div className="w-20 h-20 bg-white/5 rounded-[2rem] flex items-center justify-center mb-10 border border-white/10">
                  <Music2 size={32} className="text-indigo-400" />
                </div>
                <h1 className="text-6xl lg:text-8xl font-display font-black tracking-tightest leading-[0.9] mb-10 max-w-4xl">
                  Proper hosting <span className="text-white/40">made simple.</span>
                </h1>
                <p className="text-xl text-white/40 max-w-2xl mb-16 leading-relaxed">
                  Turn your music into a professionally hosted Google Cloud microsite. Share unique public URLs that stream globally.
                </p>
                <button onClick={() => setShowCreator(true)} className="px-12 py-6 bg-white text-black rounded-full font-black text-lg flex items-center gap-4 shadow-2xl hover:scale-105 transition-all">
                  Launch Your First Site <ArrowRight size={22} />
                </button>
              </div>
            ) : (
              <div className="animate-in fade-in duration-700">
                <header className="flex flex-col md:flex-row md:items-end justify-between gap-10 mb-20">
                  <div>
                    <h1 className="text-5xl lg:text-7xl font-display font-black tracking-tighter">Studio Library</h1>
                    <p className="text-white/30 mt-2">Manage your locally saved projects and cloud deployments.</p>
                  </div>
                  <button onClick={() => setShowCreator(true)} className="flex items-center justify-center gap-3 py-4 px-8 bg-white text-black rounded-2xl font-black text-sm hover:scale-[1.02] shadow-2xl transition-all">
                    <Plus size={20} /> New Site
                  </button>
                </header>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-10">
                  {albums.map((album) => (
                    <div key={album.id} onClick={() => openAlbum(album)} className="group cursor-pointer">
                      <div className="relative aspect-square rounded-[3rem] overflow-hidden mb-6 shadow-2xl transition-all duration-700 group-hover:scale-[1.02] ring-1 ring-white/5">
                        <img src={album.coverImage} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-1000" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center backdrop-blur-sm">
                           <Play fill="black" size={48} />
                        </div>
                        <button onClick={(e) => handleDeleteAlbum(e, album.id)} className="absolute top-6 left-6 p-3 bg-white/10 text-white/40 rounded-full opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500 hover:text-white">
                          <Trash2 size={16} />
