                      </div>
                      <h3 className="font-bold text-xl group-hover:text-white transition-colors">{album.title}</h3>
                      <p className="text-xs font-black uppercase text-white/20 tracking-widest">{album.artist}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
        {view === 'PLAYER' && selectedAlbum && (
          <PlayerView 
            album={selectedAlbum} 
            onBack={handleBackToDashboard} 
            isPublic={isPublicView}
          />
        )}
      </main>
      {showCreator && <AlbumCreator onCreated={handleCreateAlbum} onCancel={() => setShowCreator(false)} />}
    </div>
  );
};

