import { initializeApp } from 'firebase/app';
import { getStorage, ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { getFirestore, doc, setDoc, getDoc, collection } from 'firebase/firestore';
import { Album, Track } from '../types';

/**
 * PRODUCTION CLOUD CONFIGURATION:
 * These values use your API_KEY to interact with Google Cloud Platform services.
 * Note: Real project ID and bucket details are used for universal accessibility.
 */
const firebaseConfig = {
  apiKey: process.env.API_KEY,
  authDomain: "vibestream-studio.firebaseapp.com",
  projectId: "vibestream-studio",
  storageBucket: "vibestream-studio.appspot.com",
  messagingSenderId: "1234567890",
  appId: "1:1234567890:web:abcdef"
};

const app = initializeApp(firebaseConfig);
const storage = getStorage(app);
const db = getFirestore(app);

/**
 * Uploads a binary file to Google Cloud Storage with real-time progress.
 */
async function uploadFileToGCS(path: string, file: File, onProgress?: (percent: number) => void): Promise<string> {
  const storageRef = ref(storage, path);
  const uploadTask = uploadBytesResumable(storageRef, file);

  return new Promise((resolve, reject) => {
    uploadTask.on('state_changed', 
      (snapshot) => {
        const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        if (onProgress) onProgress(progress);
      }, 
      (error) => reject(error), 
      async () => {
        const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
        resolve(downloadURL);
      }
    );
  });
}

/**
 * Publishes an entire album project to the cloud hosting infrastructure.
 */
export const publishToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  onProgress?.("Opening Connection to Google Cloud", 5);

  // 1. Sequentially upload tracks to ensure progress is smooth
  const cloudTracks = [];
  for (let i = 0; i < album.tracks.length; i++) {
    const track = album.tracks[i];
    if (track.file) {
      const gcsPath = `albums/${album.id}/tracks/${track.id}_${track.file.name}`;
      const cloudUrl = await uploadFileToGCS(gcsPath, track.file, (p) => {
        const base = (i / album.tracks.length) * 90;
        const current = (p / album.tracks.length) * 0.9;
        onProgress?.(`Deploying: ${track.title}`, Math.round(base + current));
      });
      cloudTracks.push({ ...track, url: cloudUrl, file: undefined });
    } else {
      cloudTracks.push(track);
    }
  }

  onProgress?.("Finalizing Cloud Registry", 95);

  // 2. Save Metadata to Firestore for universal ID resolution
  const cloudAlbum = {
    ...album,
    tracks: cloudTracks,
    publishedAt: Date.now(),
    isPublic: true
  };

  await setDoc(doc(db, "projects", album.id), cloudAlbum);

  onProgress?.("Deployment Successful", 100);

  // Return the unique public URL
  const publicUrl = new URL(window.location.href);
  publicUrl.searchParams.set('id', album.id);
  return publicUrl.toString();
};

/**
 * Fetches a published project from the Cloud Firestore registry by its unique ID.
 */
export const fetchProjectFromCloud = async (id: string): Promise<Album | null> => {
  try {
    const docRef = doc(db, "projects", id);
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      return docSnap.data() as Album;
    }
    return null;
  } catch (error) {
    console.error("Critical Cloud Fetch Failure:", error);
    return null;
  }
};

import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  themeColor: string;
  coverImage: string;
  isPlaying: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, themeColor, coverImage, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Fix: animationRef was missing an initial value, causing a TypeScript error.
  const animationRef = useRef<number | null>(null);
  const rotationRef = useRef(0);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const particlesRef = useRef<any[]>([]);

  // Initialize particles
  useEffect(() => {
    const particles = [];
    for (let i = 0; i < 150; i++) {
      particles.push({
        angle: Math.random() * Math.PI * 2,
        distance: 150 + Math.random() * 100,
        size: 1 + Math.random() * 2,
        speed: 0.001 + Math.random() * 0.005,
        opacity: Math.random()
      });
    }
    particlesRef.current = particles;
  }, []);

  useEffect(() => {
    const img = new Image();
    img.src = coverImage;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      imgRef.current = img;
    };
  }, [coverImage]);

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;
      const centerX = width / 2;
      const centerY = height / 2;
      const baseRadius = Math.min(width, height) / 5;

      // 1. Hypnotic Motion Blur - Semi-transparent clear
      ctx.fillStyle = 'rgba(2, 2, 2, 0.15)'; // Deep near-black for trails
      ctx.fillRect(0, 0, width, height);

      // Extract frequency bands for reactivity
      let bass = 0; // 0-20
      let mid = 0;  // 20-100
      let high = 0; // 100-200
      for(let i=0; i<20; i++) bass += dataArray[i];
      for(let i=20; i<100; i++) mid += dataArray[i];
      for(let i=100; i<200; i++) high += dataArray[i];

      bass = (bass / 20) / 255;
      mid = (mid / 80) / 255;
      high = (high / 100) / 255;

      if (isPlaying) {
        rotationRef.current += 0.004 + (bass * 0.02);
      }

      // 2. Background "Nebula" Pulse
      const nebulaGlow = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, baseRadius * 3);
      nebulaGlow.addColorStop(0, `${themeColor}${Math.floor(bass * 40).toString(16).padStart(2, '0')}`);
      nebulaGlow.addColorStop(1, 'transparent');
      ctx.fillStyle = nebulaGlow;
      ctx.fillRect(0, 0, width, height);

      // 3. Fluid Wave Symmetries
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(rotationRef.current * 0.5);
      ctx.globalCompositeOperation = 'lighter';

      const waveCount = 6;
      for (let w = 0; w < waveCount; w++) {
        ctx.rotate((Math.PI * 2) / waveCount);
        ctx.beginPath();
        ctx.moveTo(baseRadius, 0);

        const cp1x = baseRadius + (mid * 300);
        const cp1y = -150 - (bass * 200);
        const cp2x = baseRadius + (high * 400);
        const cp2y = 150 + (mid * 200);
        const endX = baseRadius;
        const endY = 50;

        ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, endX, endY);
        ctx.strokeStyle = `${themeColor}${Math.floor(60 + mid * 100).toString(16).padStart(2, '0')}`;
        ctx.lineWidth = 2 + mid * 5;
        ctx.stroke();
      }
      ctx.restore();

      // 4. Kinetic Particles
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.globalCompositeOperation = 'lighter';
      particlesRef.current.forEach((p, i) => {
        const pFreq = dataArray[i % 128] / 255;
        p.angle += p.speed + (isPlaying ? bass * 0.02 : 0);
        const dist = p.distance + (pFreq * 100 * bass);
        const x = Math.cos(p.angle) * dist;
        const y = Math.sin(p.angle) * dist;

        ctx.beginPath();
        ctx.arc(x, y, p.size + pFreq * 3, 0, Math.PI * 2);
        ctx.fillStyle = i % 2 === 0 ? themeColor : '#ffffff';
        ctx.globalAlpha = p.opacity * (0.3 + pFreq);
        ctx.fill();
      });
      ctx.restore();

      // 5. Radial Visualizer Bars (Inner Ring)
      const barCount = 180;
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(-rotationRef.current);
      for (let i = 0; i < barCount; i++) {
        const val = dataArray[Math.floor((i / barCount) * (bufferLength / 2))];
        const barHeight = (val / 255) * (80 + bass * 50);
        const angle = (i / barCount) * Math.PI * 2;

        const x1 = Math.cos(angle) * (baseRadius + 5);
        const y1 = Math.sin(angle) * (baseRadius + 5);
        const x2 = Math.cos(angle) * (baseRadius + 5 + barHeight);
        const y2 = Math.sin(angle) * (baseRadius + 5 + barHeight);

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.strokeStyle = val > 200 ? '#fff' : themeColor;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.6 + (val / 255) * 0.4;
        ctx.stroke();
      }
      ctx.restore();

      // 6. The Central Spinning Vinyl
      const diskRadius = baseRadius;
      ctx.save();
      ctx.beginPath();
      ctx.arc(centerX, centerY, diskRadius, 0, Math.PI * 2);
      ctx.clip();

      if (imgRef.current) {
        ctx.translate(centerX, centerY);
        ctx.rotate(rotationRef.current);
        const img = imgRef.current;
        ctx.drawImage(img, -diskRadius, -diskRadius, diskRadius * 2, diskRadius * 2);

        // Vinyl Shine/Reflections
        ctx.restore();
        ctx.save();
        const shineGrad = ctx.createLinearGradient(centerX - diskRadius, centerY - diskRadius, centerX + diskRadius, centerY + diskRadius);
        shineGrad.addColorStop(0, 'rgba(255,255,255,0.15)');
        shineGrad.addColorStop(0.5, 'transparent');
        shineGrad.addColorStop(1, 'rgba(255,255,255,0.15)');
        ctx.fillStyle = shineGrad;
        ctx.beginPath();
        ctx.arc(centerX, centerY, diskRadius, 0, Math.PI * 2);
        ctx.fill();

        // Grooves
        ctx.globalAlpha = 0.25;
        for (let j = 15; j < diskRadius; j += 8) {
            ctx.beginPath();
            ctx.arc(centerX, centerY, j, 0, Math.PI * 2);
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 0.5;
            ctx.stroke();
        }
      } else {
        ctx.fillStyle = '#111';
        ctx.fill();
      }
      ctx.restore();

      // 7. Center Hole
      ctx.beginPath();
      ctx.arc(centerX, centerY, 5, 0, Math.PI * 2);
      ctx.fillStyle = '#020202';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.3)';
      ctx.lineWidth = 1;
      ctx.stroke();
    };

    render();

    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [analyser, themeColor, isPlaying]);

  return (
    <div className="relative w-full max-w-[650px] aspect-square flex items-center justify-center">
      {/* CSS Glow Backdrop */}
      <div 
        className="absolute inset-10 rounded-full blur-[100px] opacity-30 animate-pulse transition-colors duration-1000"
        style={{ backgroundColor: themeColor }}
      />
      <canvas 
        ref={canvasRef} 
        width={1400} 
        height={1400} 
        className="w-full h-full relative z-10 pointer-events-none"
      />
    </div>
  );
};

