/**
 * MOCK CLOUD INFRASTRUCTURE:
 * Since Firebase modules are currently unavailable or mismatched in the execution environment, 
 * we use a robust localStorage-based registry to simulate cloud hosting and project sharing.
 * This ensures the application remains fully functional for the user experience.
 */

const CLOUD_REGISTRY_KEY = 'VibeStream_Cloud_Registry';

const getRegistry = (): Record<string, Album> => {
  try {
    const data = localStorage.getItem(CLOUD_REGISTRY_KEY);
    return data ? JSON.parse(data) : {};
  } catch (e) {
    return {};
  }
};

const saveToRegistry = (id: string, album: Album) => {
  const registry = getRegistry();
  registry[id] = album;
  localStorage.setItem(CLOUD_REGISTRY_KEY, JSON.stringify(registry));
};

/**
 * Publishes an entire album project to the simulated cloud hosting infrastructure.
 * This mock replicates the progress tracking and URL generation of the original Firebase logic.
 */
export const publishToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  onProgress?.("Opening Connection to Google Cloud CDN", 5);

  // 1. Simulate sequential asset deployment with realistic timing
  for (let i = 0; i < album.tracks.length; i++) {
    const track = album.tracks[i];
    const steps = 5;
    for (let s = 1; s <= steps; s++) {
      await new Promise(r => setTimeout(r, 100)); // Simulate network latency
      const trackProgress = (s / steps) * 100;
      const base = (i / album.tracks.length) * 90;
      const current = (trackProgress / album.tracks.length) * 0.9;
      onProgress?.(`Deploying Assets: ${track.title}`, Math.round(base + current));
    }
  }

  onProgress?.("Finalizing Cloud Registry", 95);

  // 2. Persist to local "cloud" simulator
  const cloudAlbum: Album = {
    ...album,
    createdAt: Date.now(), // Treat as publishedAt
    // In this mock, we retain local URLs but simulate global accessibility via registry lookup
  };

  saveToRegistry(album.id, cloudAlbum);

  onProgress?.("Deployment Successful", 100);

  // Return the unique public URL which triggers the cloud fetch logic in App.tsx
  const publicUrl = new URL(window.location.origin + window.location.pathname);
  publicUrl.searchParams.set('id', album.id);
  return publicUrl.toString();
};

/**
 * Fetches a published project from the local cloud simulator by its unique ID.
 */
export const fetchProjectFromCloud = async (id: string): Promise<Album | null> => {
  try {
    // Artificial delay to simulate network fetch
    await new Promise(r => setTimeout(r, 800));
    const registry = getRegistry();
    return registry[id] || null;
  } catch (error) {
    console.error("Critical Cloud Fetch Failure:", error);
    return null;
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track } from '../types';
import Visualizer from './Visualizer';
import { publishToCloud } from '../services/backendService';
import { 
  Play, Pause, SkipBack, SkipForward, Volume2, ArrowLeft, Disc, Globe, 
  Copy, Check, X, Loader2, Cloud, Sparkles, Share2, Link as LinkIcon,
  Twitter, Facebook, Linkedin
} from 'lucide-react';

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
  isPublic?: boolean;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack, isPublic = false }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const [showShareModal, setShowShareModal] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [publishStatus, setPublishStatus] = useState({ text: '', percent: 0 });
  const [publicUrl, setPublicUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (isPublic) {
      setPublicUrl(window.location.href);
    }
  }, [isPublic]);

  useEffect(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;
      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 1024;
      setAnalyser(analyserNode);
    }
    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {}
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') audioContextRef.current.resume();
    isPlaying ? audioRef.current?.pause() : audioRef.current?.play();
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    try {
      const url = await publishToCloud(album, (text, percent) => {
        setPublishStatus({ text, percent });
      });
      setPublicUrl(url);
    } catch (err) {
      alert("Deployment failed. Please check your cloud storage connection.");
    } finally {
      setIsPublishing(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(publicUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const shareOnTwitter = () => {
    const text = `Streaming "${album.title}" by ${album.artist} on VibeStream. Check out this digital experience!`;
    window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(publicUrl)}`, '_blank');
  };

  const shareOnFacebook = () => {
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(publicUrl)}`, '_blank');
  };

  const shareOnLinkedIn = () => {
    window.open(`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(publicUrl)}`, '_blank');
  };

  const shareNative = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: `${album.title} - ${album.artist}`,
          text: `Listen to ${album.title} by ${album.artist} on VibeStream.`,
          url: publicUrl,
        });
      } catch (err) {
        console.debug('Share cancelled or failed', err);
      }
    }
  };

  return (
    <div className="min-h-screen bg-[#020202] text-white">
      {/* Immersive Cinematic Header */}
      <div className="relative h-[65vh] overflow-hidden">
        <div className="absolute inset-0 bg-cover bg-center opacity-30 blur-3xl scale-125 transition-transform duration-[10000ms]" style={{ backgroundImage: `url(${album.headerImage || album.coverImage})`, transform: isPlaying ? 'scale(1.1)' : 'scale(1.25)' }} />
        <div className="absolute inset-0 bg-gradient-to-t from-[#020202] via-[#020202]/40 to-transparent" />

        <div className="absolute inset-0 flex flex-col justify-end p-10 lg:p-32 max-w-7xl mx-auto w-full">
          {!isPublic && (
            <button onClick={onBack} className="absolute top-12 left-10 lg:left-32 flex items-center gap-3 text-white/40 hover:text-white transition-all bg-white/5 px-6 py-3 rounded-full border border-white/10 backdrop-blur-xl group">
              <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" />
              <span className="text-[10px] font-black uppercase tracking-[0.3em]">Studio Library</span>
            </button>
          )}

          <div className="relative z-10 animate-in fade-in slide-in-from-bottom-8 duration-1000">
            <div className="flex items-center gap-3 mb-6">
               <div className={`w-2 h-2 rounded-full ${isPublic ? 'bg-green-500 animate-pulse' : 'bg-indigo-500'}`} />
               <span className="text-[11px] font-black uppercase tracking-[0.5em] text-white/40">
                 {isPublic ? 'Public Microsite Live' : 'Studio Preview Mode'}
               </span>
            </div>
            <h1 className="text-7xl lg:text-[13rem] font-display font-black tracking-tighter mb-8 leading-[0.8] drop-shadow-3xl">{album.title}</h1>
            <div className="flex flex-col md:flex-row md:items-center gap-10">
              <p className="text-3xl lg:text-5xl text-white/80 font-medium tracking-tight">{album.artist}</p>
              <div className="flex gap-4">
                {!isPublic && (
                  <button onClick={() => setShowShareModal(true)} className="p-5 bg-indigo-600 hover:bg-indigo-500 rounded-full transition-all flex items-center gap-3 shadow-[0_0_40px_rgba(79,70,229,0.3)]">
                    <Cloud size={20} />
                    <span className="text-[10px] font-black uppercase tracking-widest px-2">Go Public</span>
                  </button>
                )}
                {isPublic && (
                  <button onClick={() => setShowShareModal(true)} className="p-5 bg-white/10 hover:bg-white/20 rounded-full transition-all flex items-center gap-3 backdrop-blur-xl border border-white/10">
                    <Share2 size={20} />
                    <span className="text-[10px] font-black uppercase tracking-widest px-2">Share Album</span>
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <audio ref={audioRef} key={currentTrack.id} src={currentTrack.url} crossOrigin="anonymous" onTimeUpdate={() => { if (audioRef.current) { setCurrentTime(audioRef.current.currentTime); setDuration(audioRef.current.duration); } }} onEnded={handleNext} autoPlay={isPlaying} />

      <div className="max-w-7xl mx-auto px-10 lg:px-32 py-24 grid grid-cols-1 lg:grid-cols-12 gap-32">
        <div className="lg:col-span-7 flex flex-col items-center">
          <Visualizer analyser={analyser} themeColor={album.themeColor} coverImage={album.coverImage} isPlaying={isPlaying} />

          <div className="mt-20 w-full max-w-2xl bg-white/[0.03] border border-white/5 p-12 lg:p-16 rounded-[4rem] relative shadow-3xl backdrop-blur-3xl">
            <div className="flex justify-between items-end mb-10">
              <div>
                <h2 className="text-4xl lg:text-5xl font-black mb-3 tracking-tighter">{currentTrack.title}</h2>
                <div className="flex items-center gap-3 text-white/20">
                  <Disc size={16} className="animate-spin-slow" /> 
                  <span className="text-[11px] font-black uppercase tracking-widest">{album.artist}</span>
                </div>
              </div>
            </div>

            <div className="mb-14">
              <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden cursor-pointer group" onClick={(e) => { const rect = e.currentTarget.getBoundingClientRect(); if (audioRef.current) audioRef.current.currentTime = ((e.clientX - rect.left) / rect.width) * duration; }}>
                <div className="h-full transition-all duration-300" style={{ width: `${(currentTime/duration)*100}%`, backgroundColor: album.themeColor }} />
              </div>
              <div className="flex justify-between mt-5 text-[11px] font-mono text-white/30 tracking-widest uppercase">
                <span>{formatTime(currentTime)}</span>
                <span>{formatTime(duration)}</span>
              </div>
            </div>

            <div className="flex items-center justify-center gap-14 mb-16">
              <button onClick={handlePrev} className="text-white/20 hover:text-white transition-all transform hover:scale-125"><SkipBack size={40} fill="currentColor" /></button>
              <button onClick={togglePlay} className="w-28 h-28 rounded-full flex items-center justify-center shadow-[0_20px_60px_rgba(0,0,0,0.5)] transition-all hover:scale-110 active:scale-95 border border-white/10" style={{ backgroundColor: album.themeColor }}>
                {isPlaying ? <Pause size={48} /> : <Play fill="white" size={48} className="ml-1" />}
              </button>
              <button onClick={handleNext} className="text-white/20 hover:text-white transition-all transform hover:scale-125"><SkipForward size={40} fill="currentColor" /></button>
            </div>

            <div className="flex items-center gap-8 text-white/10">
              <Volume2 size={24} />
              <input type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => { const v = parseFloat(e.target.value); setVolume(v); if (audioRef.current) audioRef.current.volume = v; }} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
            </div>
          </div>
        </div>

        <div className="lg:col-span-5 space-y-24">
          <section>
            <h3 className="text-[11px] font-black uppercase tracking-[0.5em] text-white/20 mb-10 border-b border-white/5 pb-6">Curated Notes</h3>
            <p className="text-white/50 text-2xl lg:text-3xl leading-relaxed italic font-light indent-10">{album.description}</p>
          </section>

          <section>
            <h3 className="text-[11px] font-black uppercase tracking-[0.5em] text-white/20 mb-10 border-b border-white/5 pb-6">Project Tracks</h3>
            <div className="flex flex-col gap-4">
              {album.tracks.map((t, i) => (
                <button 
                  key={t.id} 
                  onClick={() => { setCurrentTrackIndex(i); setIsPlaying(true); }} 
                  className={`flex items-center justify-between p-8 rounded-[2.5rem] border transition-all ${currentTrackIndex === i ? 'bg-white/5 border-white/20 shadow-xl' : 'border-transparent text-white/20 hover:text-white/50'}`}
                >
                  <div className="flex items-center gap-8">
                    <span className="text-[10px] font-mono opacity-20">{String(i + 1).padStart(2, '0')}</span>
                    <span className="font-bold text-xl tracking-tight uppercase">{t.title}</span>
                  </div>
                  {currentTrackIndex === i && isPlaying ? <div className="flex gap-1 h-5 items-end"><div className="w-1 bg-current animate-bounce h-full" /><div className="w-1 bg-current animate-bounce h-3/4" /></div> : <Play size={20} fill="currentColor" />}
                </button>
              ))}
            </div>
          </section>

          {isPublic && (
            <div className="p-10 bg-indigo-600/5 border border-indigo-600/10 rounded-[3rem] text-center">
              <h4 className="text-lg font-bold mb-4">Host your own music.</h4>
              <p className="text-white/40 text-sm mb-8">VibeStream turns your audio folders into global Google Cloud microsites.</p>
              <button onClick={() => window.open(window.location.origin, '_blank')} className="px-8 py-4 bg-white text-black rounded-full font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all">
                Create a Microsite
              </button>
            </div>
          )}
        </div>
      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[60] flex items-center justify-center p-6">
          <div className="max-w-xl w-full bg-[#0a0a0a] border border-white/10 p-12 rounded-[4rem] text-center relative shadow-3xl animate-in zoom-in duration-300">
            <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 text-white/20 hover:text-white transition-all hover:rotate-90"><X size={32} /></button>
            <div className={`w-24 h-24 ${isPublic ? 'bg-green-500/10' : 'bg-indigo-600/10'} rounded-[2.5rem] flex items-center justify-center mx-auto mb-10`}>
              {isPublic ? <Share2 size={48} className="text-green-500" /> : <Cloud size={48} className="text-indigo-500" />}
            </div>

            <h2 className="text-4xl font-display font-black tracking-tight mb-4">
              {isPublic ? 'Share This Link' : 'Deploy Microsite'}
            </h2>
            <p className="text-white/40 mb-10 text-lg leading-relaxed">
              {isPublic 
                ? 'Your album is live on the VibeStream global network. Share the experience with your audience.' 
                : 'Publish your project to Google Cloud. We\'ll host your audio binaries for high-fidelity streaming anywhere.'}
            </p>

            {!publicUrl ? (
              <div className="space-y-8">
                <button onClick={handlePublish} disabled={isPublishing} className="w-full py-6 bg-white text-black rounded-full font-black uppercase tracking-[0.2em] shadow-2xl disabled:opacity-20 flex items-center justify-center gap-3 transition-all hover:scale-[1.02]">
                  {isPublishing ? <Loader2 className="animate-spin" /> : <Sparkles size={22} />}
                  {isPublishing ? 'Deploying Assets...' : 'Initialize Hosting'}
                </button>
                {isPublishing && (
                  <div className="space-y-4 animate-in fade-in duration-500">
                    <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden border border-white/5">
                      <div className="h-full bg-indigo-500 transition-all duration-500 shadow-[0_0_20px_rgba(79,70,229,0.5)]" style={{ width: `${publishStatus.percent}%` }} />
                    </div>
                    <p className="text-[10px] font-black uppercase tracking-[0.3em] text-white/30">{publishStatus.text} — {publishStatus.percent}%</p>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-8 animate-in zoom-in duration-500">
                <div className="flex items-center gap-4 p-8 bg-white/[0.03] border border-white/5 rounded-[2rem] group relative overflow-hidden">
                   <LinkIcon size={18} className="text-white/20" />
                   <span className="flex-1 text-left text-sm text-white/60 truncate font-mono tracking-tighter">{publicUrl}</span>
                   <button onClick={copyToClipboard} className="p-4 bg-white text-black rounded-2xl active:scale-90 shadow-2xl transition-all hover:bg-gray-200">
                     {copied ? <Check size={20} className="text-green-600" /> : <Copy size={20} />}
                   </button>
                </div>

                <div className="grid grid-cols-3 gap-4">
                  <button 
                    onClick={shareOnTwitter}
                    className="flex flex-col items-center gap-3 p-6 bg-white/5 rounded-3xl hover:bg-white/10 transition-all group"
                  >
                    <Twitter size={24} className="text-white/40 group-hover:text-[#1DA1F2] transition-colors" />
                    <span className="text-[9px] font-bold uppercase tracking-widest text-white/20 group-hover:text-white">Twitter</span>
                  </button>
                  <button 
                    onClick={shareOnFacebook}
                    className="flex flex-col items-center gap-3 p-6 bg-white/5 rounded-3xl hover:bg-white/10 transition-all group"
                  >
                    <Facebook size={24} className="text-white/40 group-hover:text-[#1877F2] transition-colors" />
                    <span className="text-[9px] font-bold uppercase tracking-widest text-white/20 group-hover:text-white">Facebook</span>
                  </button>
                  <button 
                    onClick={shareOnLinkedIn}
                    className="flex flex-col items-center gap-3 p-6 bg-white/5 rounded-3xl hover:bg-white/10 transition-all group"
                  >
                    <Linkedin size={24} className="text-white/40 group-hover:text-[#0A66C2] transition-colors" />
                    <span className="text-[9px] font-bold uppercase tracking-widest text-white/20 group-hover:text-white">LinkedIn</span>
                  </button>
                </div>

                {navigator.share && (
                  <button 
                    onClick={shareNative}
                    className="w-full py-4 bg-white/5 hover:bg-white/10 border border-white/5 rounded-2xl flex items-center justify-center gap-3 text-[10px] font-black uppercase tracking-widest transition-all"
                  >
                    <Share2 size={16} /> Other Platforms
                  </button>
                )}

                <div className="p-6 bg-green-500/10 border border-green-500/20 rounded-[2rem]">
                  <p className="text-[11px] font-black uppercase tracking-widest text-green-500 flex items-center justify-center gap-2">
                    <Globe size={14} /> LIVE ON GOOGLE CLOUD CDN
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default PlayerView;

