          style={{ backgroundImage: `url(${album.headerImage || album.coverImage})`, transform: isPlaying ? 'scale(1.1) rotate(2deg)' : 'scale(1.5)' }} 
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#020202] via-[#020202]/20 to-transparent" />

        <div className="absolute inset-0 flex flex-col justify-center items-center p-10 text-center">
