  const [isLoading, setIsLoading] = useState(true);
  const [isPublicView, setIsPublicView] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      try {
        const params = new URLSearchParams(window.location.search);
        const projectId = params.get('id');

        if (projectId) {
          const remoteAlbum = await fetchProjectFromCloud(projectId);
          if (remoteAlbum) {
            setSelectedAlbum(remoteAlbum);
            setView('PLAYER');
            setIsPublicView(true);
            document.title = `${remoteAlbum.title} by ${remoteAlbum.artist} | VibeStream`;
            setIsLoading(false);
            return;
          }
        }

        const savedAlbums = await getAllLocalAlbums();
        setAlbums(savedAlbums);
        document.title = "VibeStream Studio";
      } catch (e) {
        console.error("Initialization failure:", e);
      } finally {
        setIsLoading(false);
      }
    };
    initApp();
  }, []);

  const handleCreateAlbum = async (newAlbum: Album) => {
    await saveAlbumLocally(newAlbum);
    setAlbums([newAlbum, ...albums]);
    setShowCreator(false);
    setSelectedAlbum(newAlbum);
    setView('PREVIEW');
  };

  const handleDeleteAlbum = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Permanently delete this project from your library?")) {
      await deleteLocalAlbum(id);
      setAlbums(albums.filter(a => a.id !== id));
    }
  };

  const openAlbum = (album: Album) => {
    setSelectedAlbum(album);
    setView('PLAYER');
    document.title = `${album.title} | Studio Library`;
    window.scrollTo({ top: 0, behavior: 'smooth' });
