            <div className={`w-20 h-20 lg:w-28 lg:h-28 ${isPublic ? 'bg-green-500/10' : 'bg-white/5'} rounded-[2rem] lg:rounded-[3rem] flex items-center justify-center mx-auto mb-8 shadow-2xl`}>
