};

export default PlayerView;

import React, { useState } from 'react';
import { Album, Track } from '../types';
import { generateAlbumMetadata } from '../services/geminiService';
import { Music, Upload, Loader2, X, Plus, Image as ImageIcon } from 'lucide-react';

interface AlbumCreatorProps {
  onCreated: (album: Album) => void;
  onCancel: () => void;
}

const AlbumCreator: React.FC<AlbumCreatorProps> = ({ onCreated, onCancel }) => {
  const [title, setTitle] = useState('');
  const [artist, setArtist] = useState('');
  const [tracks, setTracks] = useState<Track[]>([]);
  const [coverImage, setCoverImage] = useState('https://images.unsplash.com/photo-1614613535308-eb5fbd3d2c17?q=80&w=1000&auto=format&fit=crop');
  const [headerImage, setHeaderImage] = useState<string | undefined>(undefined);
  const [isGenerating, setIsGenerating] = useState(false);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newTracks: Track[] = [];
    const fileArray = Array.from(files) as File[];

    for (const file of fileArray) {
      if (file.type.startsWith('audio/')) {
        newTracks.push({
          id: Math.random().toString(36).substr(2, 9),
          title: file.name.replace(/\.[^/.]+$/, "").replace(/^\d+\s*[-_]*\s*/, ""),
          artist: artist || "Unknown Artist",
          file: file,
          url: URL.createObjectURL(file),
        });
      }
    }
    setTracks(prev => [...prev, ...newTracks]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || tracks.length === 0) return;

    setIsGenerating(true);
    const trackNames = tracks.map(t => t.title);
    const metadata = await generateAlbumMetadata(title, trackNames);

    const newAlbum: Album = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      artist: artist || "Unknown Artist",
      coverImage,
      headerImage: headerImage || coverImage,
      description: metadata.description,
      themeColor: metadata.themeColor,
      tracks,
      createdAt: Date.now(),
    };

    onCreated(newAlbum);
    setIsGenerating(false);
  };

  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center z-[200] p-4 md:p-10">
      <div className="max-w-6xl w-full bg-[#0a0a0a] border border-white/10 rounded-[2.5rem] md:rounded-[3rem] overflow-hidden flex flex-col lg:flex-row shadow-2xl h-full lg:h-[90vh] max-h-[1000px]">
        {/* Preview Side - Scrollable but fixed on large */}
        <div className="lg:w-2/5 p-8 md:p-12 bg-white/[0.02] flex flex-col items-center justify-center text-center border-b lg:border-b-0 lg:border-r border-white/5 relative shrink-0">
          <button type="button" onClick={onCancel} className="lg:hidden absolute top-6 right-6 p-3 bg-white/5 rounded-2xl text-white/40">
            <X size={20} />
          </button>

          <div className="relative group mb-8">
            <img 
              src={coverImage} 
              alt="Album Cover" 
              className="w-40 h-40 md:w-56 md:h-56 lg:w-72 lg:h-72 rounded-[2rem] object-cover shadow-2xl mb-6 ring-1 ring-white/10 transition-transform lg:group-hover:scale-105"
            />
            <label className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-all cursor-pointer rounded-[2rem] backdrop-blur-sm">
              <div className="flex flex-col items-center gap-2">
                <ImageIcon className="text-white" size={28} />
                <span className="text-[9px] font-bold uppercase tracking-widest">Update Art</span>
              </div>
              <input type="file" className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) setCoverImage(URL.createObjectURL(f)); }} />
            </label>
          </div>

          <h3 className="text-2xl md:text-3xl font-display font-bold mb-2 tracking-tighter truncate w-full px-4">{title || "Untitled Project"}</h3>
          <p className="text-white/40 font-medium tracking-wide truncate w-full px-4">{artist || "New Artist"}</p>

          <div className="mt-8 flex flex-col items-center gap-4">
             <label className="flex items-center gap-3 px-6 py-2 bg-white/5 hover:bg-white/10 rounded-full cursor-pointer border border-white/5 transition-colors group">
                <ImageIcon size={14} className="text-white/30 group-hover:text-white" />
                <span className="text-[9px] font-bold uppercase tracking-widest text-white/50 group-hover:text-white">
                  {headerImage ? 'Header Set' : 'Add Header'}
                </span>
                <input type="file" className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) setHeaderImage(URL.createObjectURL(f)); }} />
             </label>
          </div>
        </div>

        {/* Form Side - Always scrollable */}
        <form onSubmit={handleSubmit} className="flex-1 p-8 md:p-12 lg:p-16 overflow-y-auto">
          <div className="flex items-center justify-between mb-10 lg:mb-12">
            <div>
              <h2 className="text-2xl md:text-3xl font-display font-bold tracking-tight mb-2">Studio Setup</h2>
              <p className="text-white/30 text-xs md:text-sm">Prepare your album for the global network.</p>
            </div>
            <button type="button" onClick={onCancel} className="hidden lg:flex p-3 bg-white/5 rounded-2xl text-white/40 hover:text-white hover:bg-white/10 transition-all">
              <X size={20} />
            </button>
          </div>

          <div className="space-y-8 lg:space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
              <div className="space-y-2">
                <label className="block text-[9px] font-bold uppercase tracking-[0.2em] text-white/30 ml-1">Album Title</label>
                <input 
                  type="text" 
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="Midnight Bloom"
                  className="w-full bg-white/[0.03] border border-white/5 rounded-2xl px-6 py-4 text-white focus:outline-none focus:ring-1 focus:ring-white/20"
                  required
                />
              </div>
              <div className="space-y-2">
                <label className="block text-[9px] font-bold uppercase tracking-[0.2em] text-white/30 ml-1">Artist Name</label>
                <input 
                  type="text" 
                  value={artist}
                  onChange={(e) => setArtist(e.target.value)}
                  placeholder="Ethereal Waves"
                  className="w-full bg-white/[0.03] border border-white/5 rounded-2xl px-6 py-4 text-white focus:outline-none focus:ring-1 focus:ring-white/20"
                />
              </div>
            </div>

            <div className="space-y-4">
              <label className="block text-[9px] font-bold uppercase tracking-[0.2em] text-white/30 ml-1">Audio Master Files</label>
              <div className="relative group">
                <input type="file" multiple accept="audio/*" onChange={handleFolderSelect} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                <div className="w-full py-10 md:py-12 border-2 border-dashed border-white/5 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 group-hover:bg-white/[0.02] group-hover:border-white/20 transition-all">
                  <div className="p-4 rounded-full bg-white/5 text-white/40 group-hover:text-white transition-all">
                    <Upload size={24} md:size={32} />
                  </div>
                  <div className="text-center px-4">
                    <p className="text-sm font-medium text-white/60 mb-1">Drag & Drop Masters</p>
                    <p className="text-[8px] text-white/20 uppercase tracking-widest">Select Folder or Files</p>
                  </div>
                </div>
              </div>
            </div>

            {tracks.length > 0 && (
              <div className="space-y-4 animate-in fade-in duration-500">
