/**
 * CINEMATIC ATMOSPHERIC BACKGROUND
 */
const AtmosphericBackground: React.FC<{ album: Album; analyser: AnalyserNode | null; isPlaying: boolean }> = ({ album, analyser, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);

  useEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = album.headerImage || album.coverImage;
    img.crossOrigin = "anonymous";

    const dataArray = new Uint8Array(analyser?.frequencyBinCount || 1024);
    let offset = 0;

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      if (analyser) analyser.getByteFrequencyData(dataArray);

      const width = (canvas.width = window.innerWidth);
      const height = (canvas.height = window.innerHeight);

      let bass = 0;
      for (let i = 0; i < 10; i++) bass += dataArray[i];
      bass = (bass / 10) / 255;

      ctx.clearRect(0, 0, width, height);

      if (img.complete) {
        ctx.save();
        // Technical grading: High contrast, cinematic blur
        ctx.filter = `blur(60px) contrast(1.4) saturate(${1 + bass * 0.5})`;
        ctx.globalAlpha = 0.4 + bass * 0.1;

        offset += 0.001;
        const driftX = Math.sin(offset) * 30;
        const driftY = Math.cos(offset * 0.8) * 30;

        const scale = 1.1 + bass * 0.05;
        const drawW = width * scale;
        const drawH = height * scale;

        ctx.drawImage(img, (width - drawW)/2 + driftX, (height - drawH)/2 + driftY, drawW, drawH);

        // Add "Scanline" texture
        ctx.restore();
        ctx.globalAlpha = 0.05;
        for(let i=0; i<height; i+=4) {
          ctx.fillStyle = '#000';
          ctx.fillRect(0, i, width, 1);
        }
      }

      // HUD Vignette
      const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, Math.max(width, height) * 0.7);
      grad.addColorStop(0, 'transparent');
      grad.addColorStop(0.8, 'rgba(0,0,0,0.6)');
      grad.addColorStop(1, 'rgba(0,0,0,0.9)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, width, height);
    };

    render();
    return () => { if (animationRef.current) cancelAnimationFrame(animationRef.current); };
  }, [album, analyser, isPlaying]);

  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full pointer-events-none z-0" />;
};

/**
 * HUD COMMENT MODULE
 */
const HUDCommentModule: React.FC<{ albumId: string; trackId: string | null; isPublic: boolean; themeColor: string }> = ({ albumId, trackId, isPublic, themeColor }) => {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [author, setAuthor] = useState('GUEST_USER');
  const [isPosting, setIsPosting] = useState(false);

  useEffect(() => {
    if (!isPublic) return;
    const unsubscribe = subscribeToComments(albumId, trackId, setComments);
    return () => unsubscribe();
  }, [albumId, trackId, isPublic]);

  const handlePost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !isPublic) return;
    setIsPosting(true);
    try {
      await postComment(albumId, {
        author,
        text: newComment,
        timestamp: Date.now(),
        trackId: trackId || 'album'
      });
      setNewComment('');
    } finally {
      setIsPosting(false);
    }
  };

  return (
    <div className="flex flex-col h-full font-mono-tech">
      <div className="flex-1 space-y-4 overflow-y-auto pr-4 mb-4 custom-scrollbar">
        {comments.map(c => (
          <div key={c.id} className="p-4 bg-white/[0.02] border-l-2 border-white/10">
            <div className="flex justify-between items-center mb-1">
              <span className="text-[8px] opacity-40">[{c.author}]</span>
              <span className="text-[8px] opacity-20">{new Date(c.timestamp).toLocaleTimeString()}</span>
            </div>
            <p className="text-[10px] text-white/70 leading-relaxed">{c.text}</p>
          </div>
        ))}
      </div>
      {isPublic && (
        <form onSubmit={handlePost} className="relative mt-auto">
          <input 
            type="text" 
            placeholder="COMM_BUF_IN >" 
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2 text-[10px] outline-none focus:border-white/30"
          />
          <button type="submit" disabled={isPosting} className="absolute right-3 top-1/2 -translate-y-1/2 text-white/20 hover:text-white">
            <Send size={12} />
          </button>
        </form>
      )}
    </div>
  );
};

