import React, { useEffect, useRef } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  themeColor: string;
  coverImage: string;
  isPlaying: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, themeColor, coverImage, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const rotationRef = useRef(0);
  const particlesRef = useRef<any[]>([]);

  useEffect(() => {
    const particles = [];
    for (let i = 0; i < 200; i++) {
      particles.push({
        x: Math.random(),
        y: Math.random(),
        size: Math.random() * 2 + 1,
        vx: (Math.random() - 0.5) * 0.001,
        vy: (Math.random() - 0.5) * 0.001,
        life: Math.random()
      });
    }
    particlesRef.current = particles;
  }, []);

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      analyser.getByteFrequencyData(dataArray);

      const width = (canvas.width = canvas.clientWidth * devicePixelRatio);
      const height = (canvas.height = canvas.clientHeight * devicePixelRatio);
      const centerX = width / 2;
      const centerY = height / 2;
      const baseRadius = Math.min(width, height) / 4;

      ctx.clearRect(0, 0, width, height);

      // Extract bands
      let bass = 0;
      let mid = 0;
      let high = 0;
      for(let i=0; i<15; i++) bass += dataArray[i];
      for(let i=15; i<80; i++) mid += dataArray[i];
      for(let i=80; i<180; i++) high += dataArray[i];

      bass = (bass / 15) / 255;
      mid = (mid / 65) / 255;
      high = (high / 100) / 255;

      if (isPlaying) {
        rotationRef.current += 0.002 + (bass * 0.01);
      }

      // 1. Floating Particles (Background Layer)
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      particlesRef.current.forEach((p) => {
        p.x += p.vx + (isPlaying ? bass * 0.002 : 0);
        p.y += p.vy;
        if (p.x > 1) p.x = 0; if (p.x < 0) p.x = 1;
        if (p.y > 1) p.y = 0; if (p.y < 0) p.y = 1;

        ctx.beginPath();
        ctx.arc(p.x * width, p.y * height, p.size * (1 + high), 0, Math.PI * 2);
        ctx.fillStyle = themeColor;
        ctx.globalAlpha = 0.1 * p.life;
        ctx.fill();
      });
      ctx.restore();

      // 2. Hypnotic Flow Ribbons
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(rotationRef.current);

      const ribbonCount = 8;
      for (let i = 0; i < ribbonCount; i++) {
        const angle = (i / ribbonCount) * Math.PI * 2;
        ctx.save();
        ctx.rotate(angle);

        ctx.beginPath();
        ctx.moveTo(baseRadius * 0.5, 0);

        const cp1x = baseRadius * (1.5 + mid * 2);
        const cp1y = -baseRadius * (1 + bass * 2);
        const cp2x = baseRadius * (2 + high * 3);
        const cp2y = baseRadius * (1 + mid * 2);
        const endX = baseRadius * 0.8;
        const endY = baseRadius * 0.2;

        const grad = ctx.createLinearGradient(0, 0, cp2x, cp2y);
        grad.addColorStop(0, themeColor);
        grad.addColorStop(0.5, '#ffffff');
        grad.addColorStop(1, 'transparent');

        ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, endX, endY);
        ctx.strokeStyle = grad;
        ctx.lineWidth = 1 + bass * 20;
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.3 + mid * 0.4;
        ctx.stroke();
        ctx.restore();
      }
      ctx.restore();

      // 3. Central Core (Pulsing Glow)
      const coreSize = baseRadius * (0.8 + bass * 0.4);
      const coreGrad = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, coreSize);
      coreGrad.addColorStop(0, 'rgba(255,255,255,0.8)');
      coreGrad.addColorStop(0.2, themeColor);
      coreGrad.addColorStop(1, 'transparent');

      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.fillStyle = coreGrad;
      ctx.globalAlpha = 0.4 + bass * 0.4;
      ctx.beginPath();
      ctx.arc(centerX, centerY, coreSize, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // 4. Subtle Frequency Ring
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(-rotationRef.current * 0.5);
      const ringPoints = 120;
      ctx.beginPath();
      for (let i = 0; i < ringPoints; i++) {
        const freqIndex = Math.floor((i / ringPoints) * (bufferLength / 4));
        const val = dataArray[freqIndex] / 255;
        const r = baseRadius * 1.2 + (val * 100 * (0.5 + mid));
        const a = (i / ringPoints) * Math.PI * 2;
        const x = Math.cos(a) * r;
        const y = Math.sin(a) * r;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.restore();
    };

    render();

    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [analyser, themeColor, isPlaying]);

  return (
    <canvas 
      ref={canvasRef} 
      className="w-full h-full relative z-10 pointer-events-none transition-all duration-700"
    />
  );
};

export default Visualizer;

