/**
 * CINEMATIC ATMOSPHERIC BACKGROUND
 */
const AtmosphericBackground: React.FC<{ album: Album; analyser: AnalyserNode | null; isPlaying: boolean }> = ({ album, analyser, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);

  useEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = album.headerImage || album.coverImage;
    img.crossOrigin = "anonymous";

    const dataArray = new Uint8Array(analyser?.frequencyBinCount || 1024);
    let offset = 0;

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      if (analyser) analyser.getByteFrequencyData(dataArray);

      const width = (canvas.width = window.innerWidth);
      const height = (canvas.height = window.innerHeight);

      let bass = 0;
      for (let i = 0; i < 10; i++) bass += dataArray[i];
      bass = (bass / 10) / 255;

      ctx.clearRect(0, 0, width, height);

      if (img.complete) {
        ctx.save();
        ctx.filter = `blur(80px) contrast(1.2) saturate(${1 + bass})`;
        ctx.globalAlpha = 0.3 + bass * 0.1;

        offset += 0.0005;
        const driftX = Math.sin(offset) * 50;
        const driftY = Math.cos(offset * 1.2) * 50;

        const scale = 1.15 + bass * 0.1;
        const drawW = width * scale;
        const drawH = height * scale;

        ctx.drawImage(img, (width - drawW)/2 + driftX, (height - drawH)/2 + driftY, drawW, drawH);

        ctx.restore();
        ctx.globalAlpha = 0.03;
        for(let i=0; i<height; i+=3) {
          ctx.fillStyle = '#fff';
          ctx.fillRect(0, i, width, 1);
        }
      }

      const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, Math.max(width, height) * 0.8);
      grad.addColorStop(0, 'transparent');
      grad.addColorStop(1, 'rgba(0,0,0,0.95)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, width, height);
    };

    render();
    return () => { if (animationRef.current) cancelAnimationFrame(animationRef.current); };
  }, [album, analyser, isPlaying]);

  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full pointer-events-none z-0" />;
};

/**
 * HUD COMMENT MODULE
 */
const HUDCommentModule: React.FC<{ albumId: string; trackId: string | null; isPublic: boolean; themeColor: string }> = ({ albumId, trackId, isPublic, themeColor }) => {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [author, setAuthor] = useState('ANONYMOUS');
  const [isPosting, setIsPosting] = useState(false);

  useEffect(() => {
    if (!isPublic) return;
    const unsubscribe = subscribeToComments(albumId, trackId, setComments);
    return () => unsubscribe();
  }, [albumId, trackId, isPublic]);

  const handlePost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !isPublic) return;
    setIsPosting(true);
    try {
      await postComment(albumId, {
        author,
        text: newComment,
        timestamp: Date.now(),
        trackId: trackId || 'album'
      });
      setNewComment('');
    } finally {
      setIsPosting(false);
    }
  };

  return (
    <div className="flex flex-col h-full font-sans">
      <div className="flex-1 space-y-4 overflow-y-auto pr-4 mb-4 custom-scrollbar">
        {comments.map(c => (
          <div key={c.id} className="p-5 bg-white/[0.03] border-l-4 rounded-r-xl" style={{ borderLeftColor: themeColor }}>
            <div className="flex justify-between items-center mb-1">
              <span className="text-[10px] font-bold text-white/40 uppercase tracking-widest">{c.author}</span>
              <span className="text-[9px] font-medium opacity-20">{new Date(c.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>
            <p className="text-xs text-white/80 leading-relaxed font-medium">{c.text}</p>
          </div>
        ))}
      </div>
      {isPublic && (
        <form onSubmit={handlePost} className="relative mt-auto">
          <input 
            type="text" 
            placeholder="ADD_COMMENT //" 
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            className="w-full bg-white/5 border border-white/10 rounded-xl px-5 py-4 text-xs font-bold outline-none focus:border-white/30 transition-all"
          />
          <button type="submit" disabled={isPosting} className="absolute right-4 top-1/2 -translate-y-1/2 text-white/20 hover:text-white transition-all">
            <Send size={16} />
          </button>
        </form>
      )}
    </div>
  );
};

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
  isPublic?: boolean;
  isPreview?: boolean;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack, isPublic = false, isPreview = false }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [repeatMode, setRepeatMode] = useState<RepeatMode>('NONE');
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);
  const [activeHUD, setActiveHUD] = useState<'INFO' | 'COMMENTS' | 'TRACKS'>('INFO');

  const [showShareModal, setShowShareModal] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [publishStatus, setPublishStatus] = useState({ text: '', percent: 0 });
  const [publicUrl, setPublicUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;
      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 512;
      setAnalyser(analyserNode);
    }
    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {}
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') audioContextRef.current.resume();
    isPlaying ? audioRef.current?.pause() : audioRef.current?.play();
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const handleAudioEnded = () => {
    if (repeatMode === 'ONE') {
      if (audioRef.current) {
        audioRef.current.currentTime = 0;
        audioRef.current.play();
      }
    } else if (repeatMode === 'ALL') {
      handleNext();
    } else {
      if (currentTrackIndex < album.tracks.length - 1) {
        handleNext();
      } else {
        setIsPlaying(false);
      }
    }
  };

  const formatTime = (time: number) => {
    if (isNaN(time)) return "0:00";
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    try {
      const url = await publishToCloud(album, (text, percent) => {
        setPublishStatus({ text, percent });
      });
      setPublicUrl(url);
    } catch (err) {
      alert("Uplink failed.");
    } finally {
      setIsPublishing(false);
    }
  };

  return (
    <div 
      className="min-h-screen bg-black text-white overflow-hidden relative selection:bg-white selection:text-black font-sans"
      style={{ '--theme-color': album.themeColor } as React.CSSProperties}
    >
      <AtmosphericBackground album={album} analyser={analyser} isPlaying={isPlaying} />

      {/* Prime Screen Visualizer Area */}
      <div className="fixed inset-0 lg:right-[40%] pointer-events-none z-10 flex items-center justify-center p-20">
         <Visualizer analyser={analyser} themeColor={album.themeColor} coverImage={album.coverImage} isPlaying={isPlaying} />
      </div>

      <div className="relative z-40 w-full min-h-screen flex flex-col p-8 lg:p-16">

        {/* Header Module */}
