          <button 
            onClick={onBack} 
            className="flex items-center gap-3 px-8 py-4 bg-white/5 border border-white/10 rounded-full hover:bg-white/10 transition-all group"
          >
            <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" />
            <span className="text-sm font-bold uppercase tracking-widest">Library</span>
          </button>

          <div className="flex items-center gap-12 text-[10px] font-bold text-white/30 uppercase tracking-[0.3em]">
             <div className="text-right flex flex-col items-end">
                <span>Samplerate</span>
                <span className="text-white">48.0 Khz</span>
             </div>
             <div className="w-px h-8 bg-white/10" />
             <div className="text-right flex flex-col items-end">
                <span>Connection</span>
                <span className="text-green-500">Secured</span>
             </div>
             {isPublic && (
               <button onClick={() => setShowShareModal(true)} className="p-4 bg-white/5 border border-white/10 rounded-full hover:bg-white/10 transition-all text-white">
                 <Share2 size={20} />
               </button>
