          </div>
        </header>

        {/* HUD Cluster - Right Aligned Control Center */}
        <div className="flex flex-col lg:items-end gap-10 mt-12 mb-auto lg:max-w-[45%] lg:ml-auto">

          {/* Main Track Info Module */}
          <div className="w-full bg-black/40 backdrop-blur-3xl border border-white/10 p-10 lg:p-16 rounded-[2.5rem] shadow-3xl animate-in slide-in-from-right-20 duration-1000">
             <div className="flex flex-col gap-4">
                <div className="flex items-center gap-3">
                   <div className="px-3 py-1 bg-white/10 rounded-md text-[9px] font-black uppercase tracking-widest text-white/50">Active_Track</div>
