import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAlbumMetadata = async (albumTitle: string, trackNames: string[]) => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a compelling, artistic album description and a recommended primary theme color (hex code) for a music album titled "${albumTitle}" with the following tracks: ${trackNames.join(', ')}. The description should sound like it was written by a professional music critic.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: {
              type: Type.STRING,
              description: "An evocative 2-3 paragraph description.",
            },
            themeColor: {
              type: Type.STRING,
              description: "A sleek hex color code.",
            },
          },
          required: ["description", "themeColor"],
        },
      },
    });
    return JSON.parse(response.text);
  } catch (error) {
    return { description: "A sonic journey through sound.", themeColor: "#ffffff" };
  }
};

export const generateTrackLyrics = async (title: string, artist: string) => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate 12 lines of poetic, abstract lyrics for a song titled "${title}" by "${artist}". The lyrics should be moody and atmospheric. Return as a JSON array of strings.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text) as string[];
  } catch (error) {
    return ["Music is the only language...", "Lost in the frequency.", "Deep within the soundscape."];
  }
};

import React, { useEffect, useRef, useState } from 'react';
import { generateTrackLyrics } from '../services/geminiService';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  themeColor: string;
  trackTitle: string;
  artist: string;
  isPlaying: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, themeColor, trackTitle, artist, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const [lyrics, setLyrics] = useState<string[]>([]);
  const rotationRef = useRef(0);
  const lyricPosRef = useRef(0);

  useEffect(() => {
    let active = true;
    const fetchLyrics = async () => {
      const result = await generateTrackLyrics(trackTitle, artist);
      if (active) setLyrics(result);
    };
    fetchLyrics();
    return () => { active = false; };
  }, [trackTitle, artist]);

  useEffect(() => {
    if (!canvasRef.current || !analyser) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      analyser.getByteFrequencyData(dataArray);

      const width = (canvas.width = canvas.clientWidth * devicePixelRatio);
      const height = (canvas.height = canvas.clientHeight * devicePixelRatio);
      const centerX = width / 2;
      const centerY = height / 2;
      const baseRadius = Math.min(width, height) / 4;

      ctx.clearRect(0, 0, width, height);

      let bass = 0;
      let mid = 0;
      for(let i=0; i<15; i++) bass += dataArray[i];
      for(let i=15; i<80; i++) mid += dataArray[i];
      bass = (bass / 15) / 255;
      mid = (mid / 65) / 255;

      if (isPlaying) {
        rotationRef.current += 0.002 + (bass * 0.01);
        lyricPosRef.current += 1 + (bass * 2);
      }

      // 1. Hypnotic Flow
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(rotationRef.current);

      const ribbonCount = 6;
      for (let i = 0; i < ribbonCount; i++) {
        const angle = (i / ribbonCount) * Math.PI * 2;
        ctx.save();
        ctx.rotate(angle);

        ctx.beginPath();
        ctx.moveTo(baseRadius * 0.5, 0);

        const cp1x = baseRadius * (1.5 + mid * 2);
        const cp1y = -baseRadius * (1 + bass * 2);
        const cp2x = baseRadius * (2 + bass * 3);
        const cp2y = baseRadius * (1 + mid * 2);

        const grad = ctx.createLinearGradient(0, 0, cp2x, cp2y);
        grad.addColorStop(0, themeColor);
        grad.addColorStop(1, 'transparent');

        ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, baseRadius, baseRadius);
        ctx.strokeStyle = grad;
        ctx.lineWidth = 2 + bass * 15;
        ctx.globalAlpha = 0.4 + mid * 0.4;
        ctx.stroke();
        ctx.restore();
      }
      ctx.restore();

      // 2. Scrolling Lyrics at bottom of visualizer
      if (lyrics.length > 0) {
        ctx.save();
        ctx.font = `bold ${Math.floor(24 * devicePixelRatio)}px 'Space Grotesk'`;
        ctx.fillStyle = 'rgba(255,255,255,0.4)';
        ctx.textAlign = 'left';

        const lyricsText = lyrics.join(" • ").toUpperCase();
        const textWidth = ctx.measureText(lyricsText).width;

        if (lyricPosRef.current > textWidth) lyricPosRef.current = -width;

        ctx.fillText(lyricsText, width - lyricPosRef.current, height - (40 * devicePixelRatio));
        ctx.restore();
      }
    };

    render();
    return () => { if (animationRef.current) cancelAnimationFrame(animationRef.current); };
  }, [analyser, themeColor, isPlaying, lyrics]);

  return <canvas ref={canvasRef} className="w-full h-full pointer-events-none" />;
};

export default Visualizer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track, Comment } from '../types';
import Visualizer from './Visualizer';
import { publishToCloud, postComment, subscribeToComments } from '../services/backendService';
import { 
  Play, Pause, SkipBack, SkipForward, Volume2, ArrowLeft, Disc, Globe, 
  Copy, Check, X, Loader2, Cloud, Sparkles, Share2, Link as LinkIcon,
  Twitter, Facebook, Linkedin, ExternalLink, Zap,
  Layers, Music2, Plus, MessageSquare, Send, User, Clock, Activity, Repeat, Repeat1
} from 'lucide-react';

type RepeatMode = 'NONE' | 'ONE' | 'ALL';

const AtmosphericBackground: React.FC<{ album: Album; analyser: AnalyserNode | null; isPlaying: boolean }> = ({ album, analyser, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);

  useEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = album.headerImage || album.coverImage;
    img.crossOrigin = "anonymous";

    const dataArray = new Uint8Array(analyser?.frequencyBinCount || 1024);
    let offset = 0;

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      if (analyser) analyser.getByteFrequencyData(dataArray);

      const width = (canvas.width = window.innerWidth);
      const height = (canvas.height = window.innerHeight);

      let bass = 0;
      for (let i = 0; i < 10; i++) bass += dataArray[i];
      bass = (bass / 10) / 255;

      ctx.clearRect(0, 0, width, height);

      if (img.complete) {
        ctx.save();
        ctx.filter = `blur(100px) contrast(1.1) saturate(${1 + bass})`;
        ctx.globalAlpha = 0.25 + bass * 0.1;

        offset += 0.0005;
        const driftX = Math.sin(offset) * 40;
        const driftY = Math.cos(offset * 1.5) * 40;
        const scale = 1.1 + bass * 0.1;

        ctx.drawImage(img, (width - width*scale)/2 + driftX, (height - height*scale)/2 + driftY, width*scale, height*scale);
        ctx.restore();
      }

      const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, Math.max(width, height) * 0.8);
      grad.addColorStop(0, 'transparent');
      grad.addColorStop(1, 'rgba(0,0,0,1)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, width, height);
    };

    render();
    return () => { if (animationRef.current) cancelAnimationFrame(animationRef.current); };
  }, [album, analyser, isPlaying]);

  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full pointer-events-none z-0" />;
};

const HUDCommentModule: React.FC<{ albumId: string; trackId: string | null; isPublic: boolean; themeColor: string }> = ({ albumId, trackId, isPublic, themeColor }) => {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [author, setAuthor] = useState('LISTENER');
  const [isPosting, setIsPosting] = useState(false);

  useEffect(() => {
    if (!isPublic) return;
    const unsubscribe = subscribeToComments(albumId, trackId, setComments);
    return () => unsubscribe();
  }, [albumId, trackId, isPublic]);

  const handlePost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !isPublic) return;
    setIsPosting(true);
    try {
      await postComment(albumId, { author, text: newComment, timestamp: Date.now(), trackId: trackId || 'album' });
      setNewComment('');
    } finally { setIsPosting(false); }
  };

  return (
    <div className="flex flex-col h-full font-sans">
      <div className="flex-1 space-y-4 overflow-y-auto pr-4 mb-4 custom-scrollbar">
        {comments.map(c => (
          <div key={c.id} className="p-5 bg-white/[0.04] border-l-4 rounded-xl" style={{ borderLeftColor: themeColor }}>
            <span className="text-[10px] font-black uppercase tracking-widest text-white/30 block mb-1">{c.author}</span>
            <p className="text-sm text-white/70 font-medium leading-relaxed">{c.text}</p>
          </div>
        ))}
      </div>
      {isPublic && (
        <form onSubmit={handlePost} className="relative mt-auto">
          <input type="text" placeholder="WRITE_COMMENT..." value={newComment} onChange={(e) => setNewComment(e.target.value)}
            className="w-full bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-white/30 transition-all" />
          <button type="submit" disabled={isPosting} className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40 hover:text-white transition-all"><Send size={18} /></button>
        </form>
      )}
    </div>
  );
};

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
  isPublic?: boolean;
  isPreview?: boolean;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack, isPublic = false, isPreview = false }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [repeatMode, setRepeatMode] = useState<RepeatMode>('NONE');
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);
  const [activeHUD, setActiveHUD] = useState<'INFO' | 'COMMENTS' | 'TRACKS'>('TRACKS');

  const [showShareModal, setShowShareModal] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [publishStatus, setPublishStatus] = useState({ text: '', percent: 0 });
  const [publicUrl, setPublicUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;
      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 512;
      setAnalyser(analyserNode);
    }
    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {}
    }
  }, [analyser]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') audioContextRef.current.resume();
    isPlaying ? audioRef.current?.pause() : audioRef.current?.play();
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const handleAudioEnded = () => {
    if (repeatMode === 'ONE') { if (audioRef.current) { audioRef.current.currentTime = 0; audioRef.current.play(); } }
    else if (repeatMode === 'ALL') { handleNext(); }
    else { if (currentTrackIndex < album.tracks.length - 1) handleNext(); else setIsPlaying(false); }
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    try {
      const url = await publishToCloud(album, (text, percent) => { setPublishStatus({ text, percent }); });
      setPublicUrl(url);
    } catch (err) { alert("Cloud uplink error."); } finally { setIsPublishing(false); }
  };

  return (
    <div className="min-h-screen bg-black text-white overflow-hidden relative selection:bg-white selection:text-black font-sans">
      <AtmosphericBackground album={album} analyser={analyser} isPlaying={isPlaying} />

      {/* Prime Visual Area (Left 60%) */}
      <div className="fixed inset-0 lg:right-[40%] pointer-events-none z-10 flex flex-col p-12 lg:p-24">
         <Visualizer analyser={analyser} themeColor={album.themeColor} trackTitle={currentTrack.title} artist={album.artist} isPlaying={isPlaying} />
      </div>

      <div className="relative z-40 w-full min-h-screen flex flex-col p-8 lg:p-16">
        {/* Navigation */}
        <header className="flex justify-between items-start mb-auto">
          {!isPublic && (
            <button onClick={onBack} className="flex items-center gap-4 px-8 py-4 bg-white/5 border border-white/10 rounded-full hover:bg-white/10 transition-all font-black text-xs uppercase tracking-widest">
              <ArrowLeft size={18} /> Library
            </button>
          )}
          {isPublic && (
            <div className="flex items-center gap-4 px-8 py-4 bg-white/5 border border-white/10 rounded-full font-black text-xs uppercase tracking-widest">
              <Globe size={18} className="text-green-500 animate-pulse" /> Live Instance
