import React, { useState } from 'react';
import { Album, Track } from '../types';
import { generateAlbumMetadata } from '../services/geminiService';
import { Music, Upload, Loader2, X, Plus, Image as ImageIcon, User, BookOpen } from 'lucide-react';

interface AlbumCreatorProps {
  onCreated: (album: Album) => void;
  onCancel: () => void;
}

const AlbumCreator: React.FC<AlbumCreatorProps> = ({ onCreated, onCancel }) => {
  const [title, setTitle] = useState('');
  const [artist, setArtist] = useState('');
  const [artistBio, setArtistBio] = useState('');
  const [artistImage, setArtistImage] = useState<string | undefined>(undefined);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [coverImage, setCoverImage] = useState('https://images.unsplash.com/photo-1614613535308-eb5fbd3d2c17?q=80&w=1000&auto=format&fit=crop');
  const [headerImage, setHeaderImage] = useState<string | undefined>(undefined);
  const [slideshow, setSlideshow] = useState<string[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newTracks: Track[] = [];
    const fileArray = Array.from(files) as File[];

    for (const file of fileArray) {
      if (file.type.startsWith('audio/')) {
        newTracks.push({
          id: Math.random().toString(36).substr(2, 9),
          title: file.name.replace(/\.[^/.]+$/, "").replace(/^\d+\s*[-_]*\s*/, ""),
          artist: artist || "Unknown Artist",
          file: file,
          url: URL.createObjectURL(file),
        });
      }
    }
    setTracks(prev => [...prev, ...newTracks]);
  };

  const handleSlideshowUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const urls = Array.from(files).map(f => URL.createObjectURL(f));
    setSlideshow(prev => [...prev, ...urls]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || tracks.length === 0) return;

    setIsGenerating(true);
    const trackNames = tracks.map(t => t.title);
    const metadata = await generateAlbumMetadata(title, trackNames);

    const newAlbum: Album = {
      id: Math.random().toString(36).substr(2, 9),
      title,
      artist: artist || "Unknown Artist",
      artistBio: artistBio || `Exploring the boundaries of sound as ${artist}.`,
      artistImage: artistImage || coverImage,
      coverImage,
      headerImage: headerImage || coverImage,
      description: metadata.description,
      themeColor: metadata.themeColor,
      tracks,
      slideshow,
      createdAt: Date.now(),
    };

    onCreated(newAlbum);
    setIsGenerating(false);
  };

  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center z-[200] p-4 md:p-10">
      <div className="max-w-6xl w-full bg-[#0a0a0a] border border-white/10 rounded-[3rem] overflow-hidden flex flex-col lg:flex-row shadow-2xl h-full lg:h-[90vh] max-h-[1000px]">
        {/* Preview Side */}
        <div className="lg:w-2/5 p-8 bg-white/[0.02] flex flex-col items-center justify-center text-center border-b lg:border-b-0 lg:border-r border-white/5 relative shrink-0">
          <button type="button" onClick={onCancel} className="lg:hidden absolute top-6 right-6 p-3 bg-white/5 rounded-2xl text-white/40">
            <X size={20} />
          </button>

          <div className="relative group mb-8">
            <img 
              src={coverImage} 
              alt="Album Cover" 
              className="w-56 h-56 lg:w-72 lg:h-72 rounded-[2rem] object-cover shadow-2xl mb-6 ring-1 ring-white/10 transition-transform group-hover:scale-105"
            />
            <label className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-all cursor-pointer rounded-[2rem] backdrop-blur-sm">
              <div className="flex flex-col items-center gap-2">
                <ImageIcon className="text-white" size={28} />
                <span className="text-[9px] font-bold uppercase tracking-widest">Change Cover</span>
              </div>
              <input type="file" className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) setCoverImage(URL.createObjectURL(f)); }} />
            </label>
          </div>

          <h3 className="text-3xl font-display font-bold mb-2 tracking-tighter truncate w-full px-4">{title || "Untitled"}</h3>
          <p className="text-white/40 font-medium tracking-wide truncate w-full px-4 mb-8">{artist || "New Artist"}</p>

          <div className="flex flex-wrap justify-center gap-4">
             <label className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full cursor-pointer border border-white/5 transition-all group">
                <ImageIcon size={12} className="text-white/30 group-hover:text-white" />
                <span className="text-[8px] font-black uppercase tracking-widest text-white/40 group-hover:text-white">Slideshow ({slideshow.length})</span>
                <input type="file" multiple className="hidden" accept="image/*" onChange={handleSlideshowUpload} />
             </label>
             <label className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full cursor-pointer border border-white/5 transition-all group">
                <User size={12} className="text-white/30 group-hover:text-white" />
                <span className="text-[8px] font-black uppercase tracking-widest text-white/40 group-hover:text-white">Artist Photo</span>
                <input type="file" className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) setArtistImage(URL.createObjectURL(f)); }} />
             </label>
          </div>
        </div>

        {/* Form Side */}
        <form onSubmit={handleSubmit} className="flex-1 p-8 lg:p-16 overflow-y-auto custom-scrollbar">
          <div className="flex items-center justify-between mb-12">
            <div>
              <h2 className="text-4xl font-display font-black tracking-tight mb-2 uppercase">Microsite Studio</h2>
              <p className="text-white/30 text-xs font-bold uppercase tracking-[0.2em]">Crafting a unique sonic identity.</p>
            </div>
          </div>

          <div className="space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Project Title</label>
                <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="NEON DREAM"
                  className="w-full bg-white/[0.03] border border-white/5 rounded-3xl px-8 py-5 text-white font-bold focus:outline-none focus:ring-2 focus:ring-white/10 transition-all" required />
              </div>
              <div className="space-y-4">
                <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Creator Identity</label>
                <input type="text" value={artist} onChange={(e) => setArtist(e.target.value)} placeholder="SILICON SOUL"
                  className="w-full bg-white/[0.03] border border-white/5 rounded-3xl px-8 py-5 text-white font-bold focus:outline-none focus:ring-2 focus:ring-white/10 transition-all" />
              </div>
            </div>

            <div className="space-y-4">
              <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">About the Artist</label>
              <textarea value={artistBio} onChange={(e) => setArtistBio(e.target.value)} placeholder="Tell the world about your creative journey..."
                className="w-full bg-white/[0.03] border border-white/5 rounded-[2rem] px-8 py-6 text-white font-medium text-sm focus:outline-none focus:ring-2 focus:ring-white/10 h-32 resize-none transition-all" />
            </div>

            <div className="space-y-4">
              <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Audio Distribution Files</label>
              <div className="relative group">
                <input type="file" multiple accept="audio/*" onChange={handleFolderSelect} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                <div className="w-full py-16 border-2 border-dashed border-white/5 rounded-[3rem] flex flex-col items-center justify-center gap-6 group-hover:bg-white/[0.02] group-hover:border-white/20 transition-all">
                  <div className="p-6 rounded-full bg-white/5 text-white/40 group-hover:text-white transition-all shadow-xl">
                    <Upload size={32} />
                  </div>
                  <div className="text-center">
                    <p className="text-base font-black uppercase tracking-widest text-white/60 mb-1">Upload Music Folder</p>
                    <p className="text-[10px] text-white/20 font-bold uppercase tracking-[0.3em]">FLAC / ALAC / WAV / MP3</p>
                  </div>
                </div>
              </div>
            </div>

            {tracks.length > 0 && (
              <div className="space-y-6">
                <div className="flex items-center justify-between px-2">
                  <label className="text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Asset Queue ({tracks.length})</label>
                  <button type="button" onClick={() => setTracks([])} className="text-[10px] font-black text-white/20 hover:text-white transition-colors uppercase tracking-[0.2em]">Purge</button>
                </div>
                <div className="grid grid-cols-1 gap-3 max-h-64 overflow-y-auto pr-3 custom-scrollbar">
                  {tracks.map((track, i) => (
                    <div key={track.id} className="flex items-center justify-between p-6 rounded-[2rem] bg-white/[0.02] border border-white/5 hover:bg-white/[0.05] transition-all group">
                      <div className="flex items-center gap-6 overflow-hidden">
                        <span className="text-[10px] font-mono font-black text-white/20">{String(i + 1).padStart(2, '0')}</span>
                        <span className="text-sm font-bold uppercase tracking-wide truncate">{track.title}</span>
                      </div>
                      <button type="button" onClick={() => setTracks(tracks.filter(t => t.id !== track.id))} className="text-white/20 hover:text-red-500 transition-colors">
                        <X size={20} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <button type="submit" disabled={isGenerating || !title || tracks.length === 0}
              className="w-full py-8 bg-white text-black font-black uppercase tracking-[0.3em] text-xs rounded-full transition-all hover:scale-[1.02] active:scale-[0.98] shadow-3xl disabled:opacity-30 flex items-center justify-center gap-4">
              {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <Sparkles size={20} />}
              {isGenerating ? 'Synthesizing Microsite...' : 'Launch Digital Experience'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

