import React, { useState, useEffect } from 'react';
import { Album, AppView } from './types';
import AlbumCreator from './components/AlbumCreator';
import PlayerView from './components/PlayerView';
import { getAllLocalAlbums, saveAlbumLocally, deleteLocalAlbum } from './services/storageService';
import { fetchProjectFromCloud, loginWithGoogle, logout, onAuthUpdate, fetchUserAlbums, deleteCloudAlbum } from './services/backendService';
import { Plus, Music2, Layers, Play, ArrowRight, Trash2, Loader2, Sparkles, LogOut, User, Globe, Mail, LogIn } from 'lucide-react';
import { User as FirebaseUser } from 'firebase/auth';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [albums, setAlbums] = useState<Album[]>([]);
  const [selectedAlbum, setSelectedAlbum] = useState<Album | null>(null);
  const [showCreator, setShowCreator] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isPublicView, setIsPublicView] = useState(false);
  const [user, setUser] = useState<FirebaseUser | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthUpdate(async (currentUser) => {
      setUser(currentUser);

      const params = new URLSearchParams(window.location.search);
      const projectId = params.get('id');

      if (projectId) {
        const remoteAlbum = await fetchProjectFromCloud(projectId);
        if (remoteAlbum) {
          setSelectedAlbum(remoteAlbum);
          setView('PLAYER');
          setIsPublicView(true);
          document.title = `${remoteAlbum.title} by ${remoteAlbum.artist} | VibeStream`;
          setIsLoading(false);
          return;
        }
      }

      // Load local albums always
      const localAlbums = await getAllLocalAlbums();
      let combined = [...localAlbums];

      if (currentUser) {
        const cloudAlbums = await fetchUserAlbums(currentUser.uid);
        // Merge - prioritizing cloud for published stuff but keeping local drafts if needed
        cloudAlbums.forEach(cloud => {
           if (!combined.find(c => c.id === cloud.id)) combined.push(cloud);
        });
      }

      setAlbums(combined.sort((a,b) => b.createdAt - a.createdAt));
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleCreateAlbum = async (newAlbum: Album) => {
    if (user) newAlbum.ownerId = user.uid;
    await saveAlbumLocally(newAlbum);
    setAlbums([newAlbum, ...albums]);
    setShowCreator(false);
    setSelectedAlbum(newAlbum);
    setView('PREVIEW');
  };

  const handleDeleteAlbum = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Permanently delete this project from your library?")) {
      await deleteLocalAlbum(id);
      if (user) await deleteCloudAlbum(id);
      setAlbums(albums.filter(a => a.id !== id));
    }
  };

  const openAlbum = (album: Album) => {
    setSelectedAlbum(album);
    setView('PLAYER');
    document.title = `${album.title} | Studio Library`;
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleBackToDashboard = () => {
    setView('DASHBOARD');
    setSelectedAlbum(null);
    document.title = "VibeStream Studio";
    // Clear search params if we were in public view
    if (isPublicView) {
      window.history.pushState({}, '', window.location.pathname);
      setIsPublicView(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#020202] flex flex-col items-center justify-center gap-6 px-10">
        <div className="relative">
          <div className="w-16 h-16 border-2 border-white/5 rounded-full animate-spin border-t-white" />
          <Music2 className="absolute inset-0 m-auto text-white/20" size={20} />
        </div>
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-white/40 text-center">Initializing Identity Hub</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#020202]">
      {(!isPublicView && (view === 'DASHBOARD' || view === 'CREATOR')) && (
        <>
          {/* Mobile Top Header */}
          <header className="lg:hidden w-full p-6 border-b border-white/5 flex items-center justify-between sticky top-0 bg-black/80 backdrop-blur-xl z-50">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-white flex items-center justify-center">
                <Music2 size={16} className="text-black" />
              </div>
              <span className="font-display font-black text-lg tracking-tighter">VibeStream</span>
            </div>
            <div className="flex gap-4">
               <button onClick={() => setShowCreator(true)} className="p-3 bg-white text-black rounded-full shadow-lg">
                 <Plus size={20} />
               </button>
               {user ? (
                 <button onClick={logout} className="p-3 bg-white/10 text-white rounded-full">
                   <LogOut size={20} />
                 </button>
               ) : (
                 <button onClick={loginWithGoogle} className="p-3 bg-white/10 text-white rounded-full">
                   <LogIn size={20} />
                 </button>
               )}
            </div>
          </header>

          <aside className="w-80 border-r border-white/5 flex flex-col p-10 hidden lg:flex sticky top-0 h-screen bg-black/50 backdrop-blur-md">
            <div className="flex items-center gap-4 mb-16">
              <div className="w-12 h-12 rounded-[1.2rem] bg-white flex items-center justify-center shadow-[0_0_30px_rgba(255,255,255,0.2)]">
                <Music2 size={24} className="text-black" />
              </div>
              <div>
                <span className="font-display font-black text-2xl tracking-tighter block leading-none">VibeStream</span>
                <span className="text-[9px] font-black uppercase tracking-[0.3em] text-white/30">Studio Hub</span>
              </div>
            </div>

            <nav className="space-y-4 flex-1">
              <button onClick={() => setView('DASHBOARD')} className={`w-full flex items-center gap-4 px-6 py-5 rounded-[1.5rem] transition-all ${view === 'DASHBOARD' ? 'bg-white/10 text-white' : 'text-white/30 hover:text-white'}`}>
                <Layers size={22} />
                <span className="text-sm font-bold uppercase tracking-widest">Library</span>
              </button>
            </nav>

            <div className="pt-10 border-t border-white/5 space-y-6">
              {user ? (
                <div className="p-6 bg-white/[0.02] border border-white/5 rounded-3xl">
                  <div className="flex items-center gap-4 mb-4">
                     <div className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center overflow-hidden">
                        {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <User size={18} />}
                     </div>
                     <div className="overflow-hidden">
                        <p className="text-[9px] font-black uppercase tracking-widest text-white truncate">{user.displayName || 'User'}</p>
                        <p className="text-[8px] font-bold text-white/20 truncate">{user.email}</p>
                     </div>
                  </div>
                  <button onClick={logout} className="w-full flex items-center gap-3 text-[9px] font-black uppercase tracking-[0.3em] text-white/30 hover:text-white transition-colors">
                    <LogOut size={12} /> Sign Out
                  </button>
                </div>
              ) : (
                <div className="p-6 bg-white/[0.02] border border-white/5 rounded-3xl">
                  <p className="text-[9px] font-black uppercase tracking-widest text-white/20 mb-4 text-center">Cloud Access Disabled</p>
                  <button onClick={loginWithGoogle} className="w-full flex items-center justify-center gap-3 py-3 bg-white/5 border border-white/10 rounded-2xl text-[9px] font-black uppercase tracking-widest text-white hover:bg-white/10 transition-all">
                    <Mail size={12} /> Sign In
                  </button>
                </div>
              )}
              <button onClick={() => setShowCreator(true)} className="w-full flex items-center justify-center gap-3 py-6 bg-white text-black rounded-[1.5rem] font-black text-xs uppercase tracking-widest hover:scale-[1.02] shadow-3xl transition-all active:scale-95">
                <Plus size={18} /> New Album
              </button>
            </div>
          </aside>
        </>
      )}

      <main className="flex-1 flex flex-col w-full overflow-x-hidden">
        {view === 'DASHBOARD' && (
          <div className="p-6 md:p-12 lg:p-24 max-w-7xl mx-auto w-full">
            {albums.length === 0 ? (
              <div className="min-h-[70vh] lg:min-h-[80vh] flex flex-col items-center justify-center text-center px-4">
                <div className="w-16 h-16 lg:w-24 lg:h-24 bg-white/5 rounded-[1.5rem] lg:rounded-[2.5rem] flex items-center justify-center mb-8 lg:mb-12 border border-white/10 relative">
                  <Music2 size={32} className="text-white/40" />
                </div>
                <h1 className="text-5xl md:text-7xl lg:text-[10rem] font-display font-black tracking-tightest leading-[0.9] mb-8 lg:mb-12">
                  Artful <span className="text-white/20 italic">Sharing.</span>
                </h1>
                <p className="text-lg lg:text-2xl text-white/30 max-w-2xl mb-12 lg:mb-20 leading-relaxed font-light">
                  Convert audio folders into elegant, cloud-hosted microsites that look as good as they sound.
                </p>
                <button onClick={() => setShowCreator(true)} className="w-full sm:w-auto px-10 lg:px-14 py-6 lg:py-8 bg-white text-black rounded-full font-black text-base lg:text-xl flex items-center justify-center gap-4 lg:gap-6 shadow-4xl hover:scale-105 transition-all group">
                  Start Your First Project <ArrowRight size={24} className="group-hover:translate-x-2 transition-transform" />
                </button>
              </div>
            ) : (
              <div className="animate-in fade-in slide-in-from-bottom-10 duration-1000">
                <header className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16 lg:mb-24">
                  <div>
                    <h1 className="text-5xl lg:text-9xl font-display font-black tracking-tightest mb-4 uppercase">Library</h1>
                    <p className="text-white/20 text-lg lg:text-xl font-light tracking-wide uppercase">{albums.length} Private Projects</p>
                  </div>
                  <button onClick={() => setShowCreator(true)} className="hidden md:flex items-center justify-center gap-6 py-5 px-10 bg-white/5 border border-white/10 text-white rounded-full font-black text-xs uppercase tracking-widest hover:bg-white hover:text-black transition-all shadow-xl">
                    <Plus size={20} /> Create New
                  </button>
                </header>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-12 lg:gap-16">
                  {albums.map((album) => (
                    <div key={album.id} onClick={() => openAlbum(album)} className="group cursor-pointer">
                      <div className="relative aspect-square rounded-[2.5rem] lg:rounded-[3.5rem] overflow-hidden mb-8 shadow-2xl transition-all duration-700 group-hover:scale-[1.03] ring-1 ring-white/5">
                        <img src={album.coverImage} alt={album.title} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/70 opacity-0 lg:group-hover:opacity-100 transition-all flex items-center justify-center backdrop-blur-xl">
                           <div className="w-20 h-20 rounded-full bg-white flex items-center justify-center shadow-4xl scale-90 group-hover:scale-100 transition-transform duration-500">
                             <Play fill="black" size={28} className="ml-1" />
                           </div>
                        </div>
                        {album.isPublic && (
                           <div className="absolute top-8 left-8 p-3 bg-green-500 text-black rounded-full shadow-lg">
                              <Globe size={16} />
                           </div>
                        )}
                        <button onClick={(e) => handleDeleteAlbum(e, album.id)} className="absolute top-8 right-8 p-4 bg-black/60 text-white/40 rounded-full opacity-100 lg:opacity-0 lg:group-hover:opacity-100 transition-all hover:bg-red-500 hover:text-white backdrop-blur-xl border border-white/10">
                          <Trash2 size={18} />
                        </button>
                      </div>
                      <h3 className="font-bold text-2xl mb-1 tracking-tight uppercase truncate">{album.title}</h3>
                      <p className="text-[10px] font-black uppercase text-white/20 tracking-[0.4em]">{album.artist}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
        {(view === 'PLAYER' || view === 'PREVIEW') && selectedAlbum && (
          <PlayerView 
            album={selectedAlbum} 
            onBack={handleBackToDashboard} 
            isPublic={isPublicView}
