import { initializeApp, getApps, getApp, FirebaseApp } from 'firebase/app';
import { getStorage, ref, uploadBytesResumable, getDownloadURL, FirebaseStorage } from 'firebase/storage';
import { getFirestore, doc, setDoc, getDoc, collection, addDoc, query, where, orderBy, onSnapshot, limit, getDocs, deleteDoc, Firestore } from 'firebase/firestore';
import { getAuth, GoogleAuthProvider, signInWithPopup, signOut, onAuthStateChanged, User as FirebaseUser, Auth } from 'firebase/auth';
import { Album, Track, Comment } from '../types';

// Using a placeholder config for demonstration - in production, this should be valid.
const firebaseConfig = {
  apiKey: process.env.API_KEY,
  authDomain: "vibestream-studio.firebaseapp.com",
  projectId: "vibestream-studio",
  storageBucket: "vibestream-studio.appspot.com",
  messagingSenderId: "1234567890",
  appId: "1:1234567890:web:abcdef123456"
};

// Initialize Firebase App as a singleton
let app: FirebaseApp;
try {
  app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApp();
} catch (e) {
  console.error("Firebase App failed to initialize", e);
}

// Initialize Auth
let auth: Auth | undefined;
try {
  if (app!) auth = getAuth(app);
} catch (e) {
  console.error("Firebase Auth failed to initialize", e);
}
const googleProvider = new GoogleAuthProvider();

// Safe storage initialization
let storage: FirebaseStorage | null = null;
try {
  if (app!) storage = getStorage(app);
} catch (e) {
  console.error("Firebase Storage initialization failed.", e);
}

// Safe firestore initialization
let db: Firestore | null = null;
try {
  if (app!) db = getFirestore(app);
} catch (e) {
  console.error("Firebase Firestore initialization failed.", e);
}

export const loginWithGoogle = () => {
  if (!auth) {
    alert("Authentication service is unavailable.");
    return Promise.reject("Auth unavailable");
  }
  return signInWithPopup(auth, googleProvider);
};

export const logout = () => {
  if (!auth) return Promise.resolve();
  return signOut(auth);
};

export const onAuthUpdate = (callback: (user: FirebaseUser | null) => void) => {
  if (!auth) {
    callback(null);
    return () => {};
  }
  return onAuthStateChanged(auth, callback);
};

async function uploadFileToGCS(path: string, file: File, onProgress?: (percent: number) => void): Promise<string> {
  if (!storage) {
    throw new Error("Cloud Storage service is currently unavailable.");
  }

  const storageRef = ref(storage, path);
  const uploadTask = uploadBytesResumable(storageRef, file);

  return new Promise((resolve, reject) => {
    uploadTask.on('state_changed', 
      (snapshot) => {
        const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        if (onProgress) onProgress(progress);
      }, 
      (error) => reject(error), 
      async () => {
        const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
        resolve(downloadURL);
      }
    );
  });
}

export const publishToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  const user = auth?.currentUser;
  if (!user) throw new Error("Authentication required for cloud deployment");
  if (!db) throw new Error("Database service is currently unavailable.");

  onProgress?.("Establishing Cloud Secure Connection", 5);

  const cloudTracks: Track[] = [];

  for (let i = 0; i < album.tracks.length; i++) {
    const track = album.tracks[i];
    if (track.file) {
      const gcsPath = `users/${user.uid}/albums/${album.id}/tracks/${track.id}_${track.file.name}`;
      try {
        const cloudUrl = await uploadFileToGCS(gcsPath, track.file, (p) => {
          const base = (i / album.tracks.length) * 85;
          const current = (p / album.tracks.length) * 0.85;
          onProgress?.(`Deploying Audio: ${track.title}`, Math.round(base + current));
        });
        cloudTracks.push({ ...track, url: cloudUrl, file: undefined as any });
      } catch (err) {
        console.error(`Upload failed for ${track.title}:`, err);
        cloudTracks.push(track);
      }
    } else {
      cloudTracks.push(track);
    }
  }

  onProgress?.("Writing Metadata to Cloud Registry", 92);
  const cloudAlbum = { ...album, ownerId: user.uid, tracks: cloudTracks, isPublic: true };

  try {
    await setDoc(doc(db, "projects", album.id), cloudAlbum);
    onProgress?.("Deployment Successful", 100);
  } catch (err) {
    console.error("Firestore sync failed:", err);
    throw new Error("Cloud registry failure");
  }

  const publicUrl = new URL(window.location.origin + window.location.pathname);
  publicUrl.searchParams.set('id', album.id);
  return publicUrl.toString();
};

export const fetchUserAlbums = async (uid: string): Promise<Album[]> => {
  if (!db) return [];
  try {
    const q = query(collection(db, "projects"), where("ownerId", "==", uid));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => doc.data() as Album);
  } catch (e) {
    console.error("Failed to fetch user albums:", e);
    return [];
  }
};

export const deleteCloudAlbum = async (albumId: string) => {
  if (!db) return;
  try {
    await deleteDoc(doc(db, "projects", albumId));
  } catch (e) {
    console.error("Failed to delete cloud album:", e);
  }
};

export const fetchProjectFromCloud = async (id: string): Promise<Album | null> => {
  if (!db) return null;
  try {
    const docRef = doc(db, "projects", id);
    const docSnap = await getDoc(docRef);
    return docSnap.exists() ? docSnap.data() as Album : null;
  } catch (error) {
    console.error("Error fetching project:", error);
    return null;
  }
};

export const subscribeToComments = (albumId: string, trackId: string | null, callback: (comments: Comment[]) => void) => {
  if (!db) return () => {};
  const commentsRef = collection(db, "projects", albumId, "comments");
  const q = query(
    commentsRef, 
    where("trackId", "==", trackId || "album"),
    orderBy("timestamp", "desc"),
    limit(50)
  );

  return onSnapshot(q, (snapshot) => {
    const comments = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Comment));
    callback(comments);
  }, (err) => {
    console.warn("Comments subscription error:", err);
  });
};

export const postComment = async (albumId: string, comment: Omit<Comment, 'id'>) => {
  if (!db) return;
  try {
    const commentsRef = collection(db, "projects", albumId, "comments");
    await addDoc(commentsRef, comment);
  } catch (e) {
    console.error("Failed to post comment:", e);
  }
};

