// Helper to convert data URLs to Blobs for storage upload
async function dataUrlToBlob(dataUrl: string): Promise<Blob> {
  const res = await fetch(dataUrl);
  return await res.blob();
}

export const saveAlbumToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  if (!db || !storage) throw new Error("Cloud services unavailable");

  const userId = auth?.currentUser?.uid || 'anonymous';
  onProgress?.("Initiating Cloud Sync", 5);

  // 1. Upload Cover Image if it's a local URL
  let cloudCover = album.coverImage;
  if (album.coverImage.startsWith('blob:')) {
    onProgress?.("Uploading Artwork", 10);
    const blob = await dataUrlToBlob(album.coverImage);
    cloudCover = await uploadFileToGCS(`media/${userId}/${album.id}/cover.png`, blob);
  }

  // 2. Upload Artist Image
  let cloudArtistImg = album.artistImage;
  if (album.artistImage && album.artistImage.startsWith('blob:')) {
    const blob = await dataUrlToBlob(album.artistImage);
    cloudArtistImg = await uploadFileToGCS(`media/${userId}/${album.id}/artist.png`, blob);
  }

  // 3. Upload Tracks
  const cloudTracks: Track[] = [];
  for (let i = 0; i < album.tracks.length; i++) {
    const track = album.tracks[i];
    if (track.file) {
      const gcsPath = `media/${userId}/${album.id}/tracks/${track.id}_${track.file.name}`;
      try {
        const cloudUrl = await uploadFileToGCS(gcsPath, track.file, (p) => {
          const base = 20 + (i / album.tracks.length) * 70;
          const current = (p / album.tracks.length) * 0.7;
          onProgress?.(`Uploading Track ${i+1}: ${track.title}`, Math.round(base + current));
        });
        cloudTracks.push({ ...track, url: cloudUrl, file: undefined as any });
      } catch (err) {
        console.error(`Upload failed for ${track.title}`, err);
        cloudTracks.push(track);
      }
    } else {
      cloudTracks.push(track);
    }
  }

  // 4. Update Firestore Metadata
  onProgress?.("Finalizing Database Entry", 95);
  const cloudAlbum = { 
    ...album, 
    ownerId: userId, 
    tracks: cloudTracks, 
    coverImage: cloudCover,
    artistImage: cloudArtistImg,
    isPublic: true 
  };

  await setDoc(doc(db, "projects", album.id), cloudAlbum);
  onProgress?.("Complete", 100);

  return album.id;
};

