import { Plus, Music2, Layers, Play, ArrowRight, Trash2, Globe, Mail, LogOut, User, Share2, Check } from 'lucide-react';
import { User as FirebaseUser } from 'firebase/auth';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [albums, setAlbums] = useState<Album[]>([]);
  const [selectedAlbum, setSelectedAlbum] = useState<Album | null>(null);
  const [showCreator, setShowCreator] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isPublicView, setIsPublicView] = useState(false);
  const [user, setUser] = useState<FirebaseUser | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const loadAlbums = async () => {
    const publicAlbums = await fetchAllPublicAlbums();
    setAlbums(publicAlbums);
  };

  useEffect(() => {
    const unsubscribe = onAuthUpdate(async (currentUser) => {
      setUser(currentUser);

      const params = new URLSearchParams(window.location.search);
      const projectId = params.get('id');

      if (projectId) {
        const remoteAlbum = await fetchProjectFromCloud(projectId);
        if (remoteAlbum) {
          setSelectedAlbum(remoteAlbum);
          setView('PLAYER');
          setIsPublicView(true);
          document.title = `${remoteAlbum.title} | VibeStream`;
          setIsLoading(false);
          return;
        }
      }

      await loadAlbums();
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleCreateAlbum = async (newAlbum: Album) => {
    setAlbums([newAlbum, ...albums]);
    setShowCreator(false);
    setSelectedAlbum(newAlbum);
    setView('PREVIEW');
  };

  const handleDeleteAlbum = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Delete this cloud deployment permanently?")) {
      await deleteCloudAlbum(id);
      setAlbums(albums.filter(a => a.id !== id));
    }
  };

  const handleShareAlbum = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const url = `${window.location.origin}${window.location.pathname}?id=${id}`;
    navigator.clipboard.writeText(url);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleBackToDashboard = () => {
    setView('DASHBOARD');
    setSelectedAlbum(null);
    if (isPublicView) {
      window.history.pushState({}, '', window.location.pathname);
      setIsPublicView(false);
    }
    loadAlbums();
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#020202] flex flex-col items-center justify-center gap-6">
        <div className="relative">
          <div className="w-16 h-16 border-2 border-white/5 rounded-full animate-spin border-t-white" />
          <Music2 className="absolute inset-0 m-auto text-white/20" size={20} />
        </div>
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-white/40">Accessing Cloud Registry</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#020202]">
      {(!isPublicView && (view === 'DASHBOARD' || view === 'CREATOR')) && (
        <aside className="w-80 border-r border-white/5 flex flex-col p-10 hidden lg:flex sticky top-0 h-screen bg-black/50 backdrop-blur-md">
          <div className="flex items-center gap-4 mb-16">
            <div className="w-12 h-12 rounded-[1.2rem] bg-white flex items-center justify-center shadow-2xl">
              <Music2 size={24} className="text-black" />
            </div>
            <div>
              <span className="font-display font-black text-2xl tracking-tighter block leading-none">VibeStream</span>
              <span className="text-[9px] font-black uppercase tracking-[0.3em] text-white/30">Studio Hub</span>
            </div>
          </div>

          <nav className="flex-1 space-y-4">
            <button onClick={() => setView('DASHBOARD')} className={`w-full flex items-center gap-4 px-6 py-5 rounded-[1.5rem] transition-all ${view === 'DASHBOARD' ? 'bg-white/10 text-white' : 'text-white/30 hover:text-white'}`}>
              <Layers size={22} />
              <span className="text-sm font-bold uppercase tracking-widest">Global Feed</span>
            </button>
          </nav>

          <div className="pt-10 border-t border-white/5 space-y-6">
            {user ? (
              <div className="p-6 bg-white/[0.02] border border-white/5 rounded-3xl">
                <div className="flex items-center gap-4 mb-4">
                   <div className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center overflow-hidden">
                      {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <User size={18} />}
                   </div>
                   <div className="overflow-hidden">
                      <p className="text-[9px] font-black uppercase tracking-widest text-white truncate">{user.displayName || 'Creator'}</p>
                      <p className="text-[8px] font-bold text-white/20 truncate">{user.email}</p>
                   </div>
                </div>
                <button onClick={logout} className="w-full flex items-center gap-3 text-[9px] font-black uppercase tracking-[0.3em] text-white/30 hover:text-white transition-colors">
                  <LogOut size={12} /> Sign Out
                </button>
              </div>
            ) : (
              <button onClick={loginWithGoogle} className="w-full flex items-center justify-center gap-3 py-4 bg-white/5 border border-white/10 rounded-2xl text-[9px] font-black uppercase tracking-widest text-white hover:bg-white/10 transition-all">
                <Mail size={12} /> Sign In
              </button>
            )}
            <button onClick={() => setShowCreator(true)} className="w-full flex items-center justify-center gap-3 py-6 bg-white text-black rounded-[1.5rem] font-black text-xs uppercase tracking-widest hover:scale-[1.02] shadow-3xl transition-all">
              <Plus size={18} /> New Album
            </button>
          </div>
        </aside>
      )}

      <main className="flex-1 flex flex-col w-full">
        {view === 'DASHBOARD' && (
          <div className="p-8 lg:p-24 max-w-7xl mx-auto w-full">
            <header className="mb-16">
              <h1 className="text-5xl lg:text-9xl font-display font-black tracking-tightest mb-4 uppercase">Feed</h1>
              <p className="text-white/20 text-lg uppercase tracking-[0.2em]">{albums.length} Public Deployments</p>
            </header>

            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-12">
              {albums.map((album) => (
                <div key={album.id} onClick={() => { setSelectedAlbum(album); setView('PLAYER'); }} className="group cursor-pointer">
                  <div className="relative aspect-square rounded-[3rem] overflow-hidden mb-6 shadow-2xl ring-1 ring-white/5">
                    <img src={album.coverImage} alt={album.title} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center backdrop-blur-sm">
                       <Play fill="white" size={48} />
                    </div>
                    <div className="absolute top-6 right-6 flex gap-2">
                       <button onClick={(e) => handleShareAlbum(e, album.id)} className="p-4 bg-black/60 rounded-full text-white/40 hover:text-white backdrop-blur-md transition-all">
                        {copiedId === album.id ? <Check size={18} className="text-green-500" /> : <Share2 size={18} />}
                      </button>
                      {user?.uid === album.ownerId && (
                        <button onClick={(e) => handleDeleteAlbum(e, album.id)} className="p-4 bg-black/60 rounded-full text-white/40 hover:text-red-500 backdrop-blur-md transition-all">
                          <Trash2 size={18} />
                        </button>
                      )}
                    </div>
                  </div>
                  <h3 className="font-bold text-2xl uppercase tracking-tight">{album.title}</h3>
                  <p className="text-[10px] font-black text-white/20 uppercase tracking-widest">{album.artist}</p>
                </div>
              ))}
              {albums.length === 0 && (
                <div className="col-span-full py-20 text-center opacity-20 uppercase font-black tracking-widest">
                   No public signals detected.
                </div>
              )}
            </div>
          </div>
        )}
        {(view === 'PLAYER' || view === 'PREVIEW') && selectedAlbum && (
          <PlayerView 
            album={selectedAlbum} 
            onBack={handleBackToDashboard} 
            isPublic={isPublicView}
            isPreview={view === 'PREVIEW'}
          />
        )}
      </main>
      {showCreator && <AlbumCreator onCreated={handleCreateAlbum} onCancel={() => setShowCreator(false)} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Album, Track, Comment } from '../types';
