type RepeatMode = 'NONE' | 'ONE' | 'ALL';

/**
 * ANIMATED SLIDESHOW COMPONENT
 */
const AnimatedSlideshow: React.FC<{ images: string[]; isPlaying: boolean; themeColor: string }> = ({ images, isPlaying, themeColor }) => {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (!images.length || !isPlaying) return;
    const interval = setInterval(() => {
      setIndex((prev) => (prev + 1) % images.length);
    }, 6000);
    return () => clearInterval(interval);
  }, [images.length, isPlaying]);

  if (!images.length) return null;

  return (
    <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
      {images.map((img, i) => (
        <div
          key={i}
          className={`absolute inset-0 transition-all duration-[3000ms] ease-in-out transform ${i === index ? 'opacity-30 scale-110' : 'opacity-0 scale-100'}`}
        >
          <img src={img} alt="Slideshow" className="w-full h-full object-cover" />
          <div className="absolute inset-0 bg-black/40" />
        </div>
      ))}
    </div>
  );
};

const AtmosphericBackground: React.FC<{ album: Album; analyser: AnalyserNode | null; isPlaying: boolean }> = ({ album, analyser, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);

  useEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = album.headerImage || album.coverImage;
    img.crossOrigin = "anonymous";

    const dataArray = new Uint8Array(analyser?.frequencyBinCount || 1024);
    let offset = 0;

    const render = () => {
      animationRef.current = requestAnimationFrame(render);
      if (analyser) analyser.getByteFrequencyData(dataArray);

      const width = (canvas.width = window.innerWidth);
      const height = (canvas.height = window.innerHeight);

      let bass = 0;
      for (let i = 0; i < 10; i++) bass += dataArray[i];
      bass = (bass / 10) / 255;

      ctx.clearRect(0, 0, width, height);

      if (img.complete) {
        ctx.save();
        ctx.filter = `blur(100px) contrast(1.1) saturate(${1 + bass})`;
        ctx.globalAlpha = 0.2 + bass * 0.1;

        offset += 0.0005;
        const driftX = Math.sin(offset) * 40;
        const driftY = Math.cos(offset * 1.5) * 40;
        const scale = 1.1 + bass * 0.1;

        ctx.drawImage(img, (width - width*scale)/2 + driftX, (height - height*scale)/2 + driftY, width*scale, height*scale);
        ctx.restore();
      }

      const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, Math.max(width, height) * 0.8);
      grad.addColorStop(0, 'transparent');
      grad.addColorStop(1, 'rgba(0,0,0,1)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, width, height);
    };

    render();
    return () => { if (animationRef.current) cancelAnimationFrame(animationRef.current); };
  }, [album, analyser, isPlaying]);

  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full pointer-events-none z-0" />;
};

const HUDCommentModule: React.FC<{ albumId: string; trackId: string | null; isPublic: boolean; themeColor: string; minimal?: boolean }> = ({ albumId, trackId, isPublic, themeColor, minimal }) => {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [author, setAuthor] = useState('LISTENER');
  const [isPosting, setIsPosting] = useState(false);
  const [isOpen, setIsOpen] = useState(!minimal);

  useEffect(() => {
    const unsubscribe = subscribeToComments(albumId, trackId, setComments);
    return () => unsubscribe();
  }, [albumId, trackId]);

  const handlePost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim()) return;
    setIsPosting(true);
    try {
      await postComment(albumId, { author, text: newComment, timestamp: Date.now(), trackId: trackId || 'album' });
      setNewComment('');
    } finally { setIsPosting(false); }
  };

  if (!isOpen && minimal) {
    return (
      <button onClick={() => setIsOpen(true)} className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest text-white/30 hover:text-white transition-all py-4">
        <MessageSquare size={14} /> Open Comments ({comments.length})
      </button>
    );
  }

  return (
    <div className={`flex flex-col h-full font-sans transition-all duration-500 animate-in slide-in-from-top-4`}>
      <div className="flex items-center justify-between mb-6">
        <span className="text-[10px] font-black uppercase tracking-widest text-white/20">Discussion Feed</span>
        {minimal && <button onClick={() => setIsOpen(false)}><ChevronUp size={16} className="text-white/20" /></button>}
      </div>
      <div className="flex-1 space-y-4 overflow-y-auto pr-4 mb-4 custom-scrollbar max-h-[300px]">
        {comments.map(c => (
          <div key={c.id} className="p-4 bg-white/[0.04] border-l-2 rounded-r-2xl" style={{ borderLeftColor: themeColor }}>
            <span className="text-[9px] font-black uppercase tracking-widest text-white/30 block mb-1">{c.author}</span>
            <p className="text-xs text-white/70 font-medium leading-relaxed">{c.text}</p>
          </div>
        ))}
        {comments.length === 0 && <p className="text-[10px] uppercase font-bold text-white/10 tracking-widest text-center py-8">No signals received yet.</p>}
      </div>
      <form onSubmit={handlePost} className="relative mt-auto">
        <input type="text" placeholder="TRANSMIT_MSG..." value={newComment} onChange={(e) => setNewComment(e.target.value)}
          className="w-full bg-white/5 border border-white/10 rounded-2xl px-5 py-4 text-xs font-bold outline-none focus:border-white/30 transition-all" />
        <button type="submit" disabled={isPosting} className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40 hover:text-white transition-all"><Send size={16} /></button>
      </form>
    </div>
  );
};

interface PlayerViewProps {
  album: Album;
  onBack: () => void;
  isPublic?: boolean;
  isPreview?: boolean;
}

const PlayerView: React.FC<PlayerViewProps> = ({ album, onBack, isPublic = false, isPreview = false }) => {
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [repeatMode, setRepeatMode] = useState<RepeatMode>('NONE');
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);
  const [activeHUD, setActiveHUD] = useState<'INFO' | 'COMMENTS' | 'TRACKS' | 'ABOUT'>('TRACKS');

  const [showShareModal, setShowShareModal] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [publishStatus, setPublishStatus] = useState({ text: '', percent: 0 });
  const [publicUrl, setPublicUrl] = useState('');
  const [copied, setCopied] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  const currentTrack = album.tracks[currentTrackIndex];

  useEffect(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioContextClass();
      audioContextRef.current = ctx;
      const analyserNode = ctx.createAnalyser();
      analyserNode.fftSize = 512;
      setAnalyser(analyserNode);
    }
    if (audioRef.current && analyser && !sourceRef.current && audioContextRef.current) {
      try {
        const source = audioContextRef.current.createMediaElementSource(audioRef.current);
        source.connect(analyser);
        analyser.connect(audioContextRef.current.destination);
        sourceRef.current = source;
      } catch (err) {}
    }
  }, [analyser]);

  useEffect(() => {
    if (album.id) {
      setPublicUrl(`${window.location.origin}${window.location.pathname}?id=${album.id}`);
    }
  }, [album.id]);

  const togglePlay = () => {
    if (audioContextRef.current?.state === 'suspended') audioContextRef.current.resume();
    isPlaying ? audioRef.current?.pause() : audioRef.current?.play();
    setIsPlaying(!isPlaying);
  };

  const handleNext = useCallback(() => {
    setCurrentTrackIndex((prev) => (prev + 1) % album.tracks.length);
    setIsPlaying(true);
  }, [album.tracks.length]);

  const handlePrev = () => {
    setCurrentTrackIndex((prev) => (prev - 1 + album.tracks.length) % album.tracks.length);
    setIsPlaying(true);
  };

  const handleAudioEnded = () => {
    if (repeatMode === 'ONE') { if (audioRef.current) { audioRef.current.currentTime = 0; audioRef.current.play(); } }
    else if (repeatMode === 'ALL') { handleNext(); }
    else { if (currentTrackIndex < album.tracks.length - 1) handleNext(); else setIsPlaying(false); }
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    try {
      const url = await publishToCloud(album, (text, percent) => { setPublishStatus({ text, percent }); });
      setPublicUrl(url);
    } catch (err) { alert("Cloud uplink error."); } finally { setIsPublishing(false); }
  };

  return (
    <div className="min-h-screen bg-black text-white overflow-hidden relative selection:bg-white selection:text-black font-sans">
      <AtmosphericBackground album={album} analyser={analyser} isPlaying={isPlaying} />

      <AnimatedSlideshow images={currentTrack.images || album.slideshow || []} isPlaying={isPlaying} themeColor={album.themeColor} />

      <div className="fixed inset-0 lg:right-[40%] pointer-events-none z-10 flex flex-col p-12 lg:p-24">
         <Visualizer analyser={analyser} themeColor={album.themeColor} trackTitle={currentTrack.title} artist={album.artist} isPlaying={isPlaying} />
      </div>

      <div className="relative z-40 w-full min-h-screen flex flex-col p-8 lg:p-16">
        <header className="flex justify-between items-start mb-auto">
          {!isPublic ? (
            <button onClick={onBack} className="flex items-center gap-4 px-8 py-4 bg-white/5 border border-white/10 rounded-full hover:bg-white/10 transition-all font-black text-xs uppercase tracking-widest">
              <ArrowLeft size={18} /> Library
            </button>
          ) : (
             <div className="flex items-center gap-4 px-8 py-4 bg-black/40 backdrop-blur-md border border-white/10 rounded-full font-black text-xs uppercase tracking-widest">
              <Globe size={18} className="text-green-500 animate-pulse" /> Live Microsite
            </div>
          )}

          <div className="flex gap-4">
             <button onClick={() => setActiveHUD(activeHUD === 'ABOUT' ? 'TRACKS' : 'ABOUT')} className={`px-8 py-4 rounded-full font-black text-xs uppercase tracking-widest border transition-all ${activeHUD === 'ABOUT' ? 'bg-white text-black border-white' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}>
                {activeHUD === 'ABOUT' ? 'Close Bio' : 'About Artist'}
             </button>
             {!isPublic && (
               <button onClick={() => setShowShareModal(true)} className="px-10 py-4 bg-white text-black rounded-full font-black text-xs uppercase tracking-widest shadow-2xl hover:scale-105 transition-all flex items-center gap-3">
                 <Share2 size={18} /> Share
               </button>
             )}
          </div>
        </header>

        <div className="flex flex-col lg:items-end gap-10 lg:max-w-[45%] lg:ml-auto">
          <div className="w-full bg-black/60 backdrop-blur-3xl border border-white/10 p-10 lg:p-16 rounded-[3rem] shadow-3xl">
             <div className="flex flex-col gap-6">
                <div className="flex items-center gap-4">
                   <span className="px-3 py-1 bg-white/10 rounded-md text-[10px] font-black tracking-widest text-white/40 uppercase">Audio Session</span>
                   <span className="text-xs font-bold opacity-30 uppercase tracking-widest">Track {currentTrackIndex+1} / {album.tracks.length}</span>
                </div>
                <h1 className="text-6xl lg:text-[7rem] font-display font-black tracking-tightest leading-[0.85]">{currentTrack.title}</h1>
                <p className="text-3xl lg:text-4xl font-medium text-white/40 italic">{album.artist}</p>
             </div>
          </div>

          <div className="w-full bg-black/60 backdrop-blur-3xl border border-white/10 p-10 rounded-[3rem]">
             <div className="space-y-6 mb-12">
               <div className="flex justify-between text-[11px] font-black uppercase tracking-[0.3em] text-white/20">
                 <span className="flex items-center gap-2"><Activity size={12} /> Syncing...</span>
                 <span>{Math.floor(currentTime/60)}:{Math.floor(currentTime%60).toString().padStart(2,'0')} / {Math.floor(duration/60)}:{Math.floor(duration%60).toString().padStart(2,'0')}</span>
               </div>
               <div className="relative h-2 w-full bg-white/5 rounded-full cursor-pointer group" onClick={(e) => { const rect = e.currentTarget.getBoundingClientRect(); if (audioRef.current) audioRef.current.currentTime = ((e.clientX - rect.left) / rect.width) * duration; }}>
                 <div className="absolute inset-y-0 left-0 bg-white rounded-full transition-all duration-100 shadow-[0_0_20px_white]" style={{ width: `${(currentTime/duration)*100}%` }}>
                   <div className="absolute right-0 top-1/2 -translate-y-1/2 w-5 h-5 bg-white rounded-full shadow-[0_0_30px_white] scale-0 group-hover:scale-100 transition-transform" />
                 </div>
               </div>
             </div>

             <div className="flex items-center justify-between">
                <div className="flex items-center gap-10">
                  <button onClick={handlePrev} className="text-white/20 hover:text-white transition-all"><SkipBack size={32} /></button>
                  <button onClick={togglePlay} className="w-24 h-24 rounded-full bg-white text-black flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-2xl">
                    {isPlaying ? <Pause size={40} /> : <Play fill="black" size={40} className="ml-1" />}
                  </button>
                  <button onClick={handleNext} className="text-white/20 hover:text-white transition-all"><SkipForward size={32} /></button>
                </div>

                <div className="flex items-center gap-8">
                  <button onClick={() => setRepeatMode(m => m === 'NONE' ? 'ALL' : m === 'ALL' ? 'ONE' : 'NONE')}
                    className={`p-3 rounded-xl border transition-all ${repeatMode !== 'NONE' ? 'bg-white text-black border-white' : 'text-white/20 border-white/10'}`}>
                    {repeatMode === 'ONE' ? <Repeat1 size={20} /> : <Repeat size={20} />}
                  </button>
                  <div className="flex items-center gap-4 w-32 group">
                    <Volume2 size={20} className="text-white/20 group-hover:text-white transition-colors" />
                    <input type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => { const v = parseFloat(e.target.value); setVolume(v); if (audioRef.current) audioRef.current.volume = v; }} className="w-full h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-white" />
                  </div>
                </div>
             </div>
          </div>

          <div className="w-full min-h-[500px] flex flex-col gap-8">
             {activeHUD === 'ABOUT' && (
