import React, { useState } from 'react';
import { Album, Track } from '../types';
import { generateAlbumMetadata } from '../services/geminiService';
import { saveAlbumToCloud } from '../services/backendService';
import { Upload, Loader2, X, Image as ImageIcon, User, Sparkles } from 'lucide-react';

interface AlbumCreatorProps {
  onCreated: (album: Album) => void;
  onCancel: () => void;
}

const AlbumCreator: React.FC<AlbumCreatorProps> = ({ onCreated, onCancel }) => {
  const [title, setTitle] = useState('');
  const [artist, setArtist] = useState('');
  const [artistBio, setArtistBio] = useState('');
  const [artistImage, setArtistImage] = useState<string | undefined>(undefined);
  const [tracks, setTracks] = useState<Track[]>([]);
  const [coverImage, setCoverImage] = useState('https://images.unsplash.com/photo-1614613535308-eb5fbd3d2c17?q=80&w=1000&auto=format&fit=crop');
  const [slideshow, setSlideshow] = useState<string[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [uploadStatus, setUploadStatus] = useState({ text: '', percent: 0 });

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newTracks: Track[] = [];
    const fileArray = Array.from(files) as File[];

    for (const file of fileArray) {
      if (file.type.startsWith('audio/')) {
        newTracks.push({
          id: Math.random().toString(36).substr(2, 9),
          title: file.name.replace(/\.[^/.]+$/, "").replace(/^\d+\s*[-_]*\s*/, ""),
          artist: artist || "Unknown Artist",
          file: file,
          url: URL.createObjectURL(file),
        });
      }
    }
    setTracks(prev => [...prev, ...newTracks]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || tracks.length === 0) return;

    setIsGenerating(true);
    setUploadStatus({ text: "Analyzing Soundscape...", percent: 5 });

    try {
      const trackNames = tracks.map(t => t.title);
      const metadata = await generateAlbumMetadata(title, trackNames);

      const albumId = Math.random().toString(36).substr(2, 9);
      const newAlbum: Album = {
        id: albumId,
        title,
        artist: artist || "Unknown Artist",
        artistBio: artistBio || `Exploring the boundaries of sound as ${artist}.`,
        artistImage: artistImage || coverImage,
        coverImage,
        description: metadata.description,
        themeColor: metadata.themeColor,
        tracks,
        slideshow,
        createdAt: Date.now(),
        isPublic: true
      };

      // Perform cloud upload immediately
      await saveAlbumToCloud(newAlbum, (text, percent) => {
        setUploadStatus({ text, percent });
      });

      onCreated(newAlbum);
    } catch (err) {
      alert("Creation failed. Please check your connection.");
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center z-[200] p-4 md:p-10">
      <div className="max-w-6xl w-full bg-[#0a0a0a] border border-white/10 rounded-[3rem] overflow-hidden flex flex-col lg:flex-row shadow-2xl h-full lg:h-[90vh] max-h-[1000px]">

        {/* Progress Overlay */}
        {isGenerating && (
          <div className="absolute inset-0 z-[300] bg-black/80 backdrop-blur-xl flex flex-col items-center justify-center p-20 text-center animate-in fade-in">
            <div className="w-32 h-32 relative mb-12">
               <div className="absolute inset-0 border-4 border-white/5 rounded-full" />
               <div className="absolute inset-0 border-4 border-white rounded-full border-t-transparent animate-spin" style={{ animationDuration: '3s' }} />
               <Sparkles className="absolute inset-0 m-auto text-white animate-pulse" size={32} />
            </div>
            <h2 className="text-5xl font-display font-black tracking-tighter mb-4 uppercase">{uploadStatus.text}</h2>
            <div className="w-full max-w-md h-1 bg-white/10 rounded-full overflow-hidden mb-4">
               <div className="h-full bg-white transition-all duration-500" style={{ width: `${uploadStatus.percent}%` }} />
            </div>
            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30">{uploadStatus.percent}% Encoded</p>
          </div>
        )}

        {/* Preview Side */}
        <div className="lg:w-2/5 p-8 bg-white/[0.02] flex flex-col items-center justify-center text-center border-b lg:border-b-0 lg:border-r border-white/5 relative shrink-0">
          <button type="button" onClick={onCancel} className="absolute top-6 left-6 p-3 bg-white/5 rounded-2xl text-white/40">
            <X size={20} />
          </button>

          <div className="relative group mb-8">
            <img src={coverImage} alt="Album Cover" className="w-56 h-56 lg:w-72 lg:h-72 rounded-[2rem] object-cover shadow-2xl mb-6 ring-1 ring-white/10 transition-transform group-hover:scale-105" />
            <label className="absolute inset-0 flex items-center justify-center bg-black/60 opacity-0 group-hover:opacity-100 transition-all cursor-pointer rounded-[2rem] backdrop-blur-sm">
              <div className="flex flex-col items-center gap-2">
                <ImageIcon className="text-white" size={28} />
                <span className="text-[9px] font-bold uppercase tracking-widest">Artwork</span>
              </div>
              {/* Fix: Added explicit cast to Blob for the first parameter of URL.createObjectURL to avoid 'unknown' type errors */}
              <input type="file" className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) setCoverImage(URL.createObjectURL(f as Blob)); }} />
            </label>
          </div>

          <h3 className="text-3xl font-display font-bold mb-2 tracking-tighter truncate w-full px-4">{title || "Album Title"}</h3>
          <p className="text-white/40 font-medium tracking-wide truncate w-full px-4 mb-8">{artist || "Artist Identity"}</p>

          <div className="flex flex-wrap justify-center gap-4">
             <label className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full cursor-pointer border border-white/5 transition-all group">
                <ImageIcon size={12} className="text-white/30 group-hover:text-white" />
                <span className="text-[8px] font-black uppercase tracking-widest text-white/40 group-hover:text-white">Slideshow ({slideshow.length})</span>
                {/* Fix: Added explicit cast to File[] for Array.from results to avoid 'unknown' mapping errors in URL.createObjectURL */}
