             </label>
             <label className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full cursor-pointer border border-white/5 transition-all group">
                <User size={12} className="text-white/30 group-hover:text-white" />
                <span className="text-[8px] font-black uppercase tracking-widest text-white/40 group-hover:text-white">Artist Profile</span>
                {/* Fix: Added explicit cast to Blob to resolve type inference issues with file inputs */}
                <input type="file" className="hidden" accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if (f) setArtistImage(URL.createObjectURL(f as Blob)); }} />
             </label>
          </div>
        </div>

        {/* Form Side */}
        <form onSubmit={handleSubmit} className="flex-1 p-8 lg:p-16 overflow-y-auto custom-scrollbar">
          <div className="mb-12">
            <h2 className="text-4xl font-display font-black tracking-tight mb-2 uppercase">Deploy Microsite</h2>
            <p className="text-white/30 text-xs font-bold uppercase tracking-[0.2em]">All projects are saved to the cloud automatically.</p>
          </div>

          <div className="space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Project Name</label>
                <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Hyperlink" className="w-full bg-white/[0.03] border border-white/5 rounded-3xl px-8 py-5 text-white font-bold focus:outline-none transition-all" required />
              </div>
              <div className="space-y-4">
                <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Artist Name</label>
                <input type="text" value={artist} onChange={(e) => setArtist(e.target.value)} placeholder="The Source" className="w-full bg-white/[0.03] border border-white/5 rounded-3xl px-8 py-5 text-white font-bold focus:outline-none transition-all" />
              </div>
            </div>

            <div className="space-y-4">
              <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">About</label>
              <textarea value={artistBio} onChange={(e) => setArtistBio(e.target.value)} placeholder="Microsite liner notes..." className="w-full bg-white/[0.03] border border-white/5 rounded-[2rem] px-8 py-6 text-white font-medium text-sm focus:outline-none h-32 resize-none transition-all" />
            </div>

            <div className="space-y-4">
              <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white/20">Audio Distribution</label>
              <div className="relative group">
                <input type="file" multiple accept="audio/*" onChange={handleFolderSelect} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                <div className="w-full py-16 border-2 border-dashed border-white/5 rounded-[3rem] flex flex-col items-center justify-center gap-6 group-hover:bg-white/[0.02] transition-all">
