            <button type="submit" disabled={isGenerating || !title || tracks.length === 0} className="w-full py-8 bg-white text-black font-black uppercase tracking-[0.3em] text-xs rounded-full transition-all hover:scale-[1.02] shadow-3xl disabled:opacity-30">
