const googleProvider = new GoogleAuthProvider();

export const loginWithGoogle = () => {
  if (!auth) return Promise.reject("Firebase Auth not initialized");
  return signInWithPopup(auth, googleProvider);
};

export const logout = () => {
  if (!auth) return Promise.resolve();
  return signOut(auth);
};

export const onAuthUpdate = (callback: (user: FirebaseUser | null) => void) => {
  if (!auth) {
    callback(null);
    return () => {};
  }
  return onAuthStateChanged(auth, callback);
};

async function uploadToStorage(path: string, blob: Blob | File, onProgress?: (percent: number) => void): Promise<string> {
  if (!storage) throw new Error("Firebase Storage not initialized");
  const storageRef = ref(storage, path);
  const uploadTask = uploadBytesResumable(storageRef, blob);

  return new Promise((resolve, reject) => {
    uploadTask.on('state_changed', 
      (snapshot) => {
        const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        if (onProgress) onProgress(progress);
      }, 
      (error) => reject(error), 
      async () => {
        const url = await getDownloadURL(uploadTask.snapshot.ref);
        resolve(url);
      }
    );
  });
}

async function dataUrlToBlob(url: string): Promise<Blob> {
  const res = await fetch(url);
  return await res.blob();
}

export const publishToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  if (!db || !storage) throw new Error("Firebase services unavailable");
  const userId = auth?.currentUser?.uid || 'anonymous';

  onProgress?.("Initiating Cloud Sync", 5);

  // 1. Upload Cover Artwork
  let cloudCover = album.coverImage;
  if (album.coverImage.startsWith('blob:')) {
    onProgress?.("Uploading Artwork", 10);
    const blob = await dataUrlToBlob(album.coverImage);
    cloudCover = await uploadToStorage(`albums/${album.id}/cover.png`, blob);
  }

  // 2. Upload Artist Image
  let cloudArtistImg = album.artistImage;
  if (album.artistImage && album.artistImage.startsWith('blob:')) {
    const blob = await dataUrlToBlob(album.artistImage);
    cloudArtistImg = await uploadToStorage(`albums/${album.id}/artist.png`, blob);
  }

  // 3. Upload Tracks
  const cloudTracks: Track[] = [];
  for (let i = 0; i < album.tracks.length; i++) {
    const track = album.tracks[i];
    if (track.file) {
      const gcsPath = `albums/${album.id}/tracks/${track.id}_${track.file.name}`;
      try {
        const cloudUrl = await uploadToStorage(gcsPath, track.file, (p) => {
          const base = 20 + (i / album.tracks.length) * 70;
          const current = (p / album.tracks.length) * 0.7;
          onProgress?.(`Uploading Track ${i+1}/${album.tracks.length}`, Math.round(base + current));
        });
        cloudTracks.push({ ...track, url: cloudUrl, file: undefined as any });
      } catch (err) {
        console.error(`Upload failed for ${track.title}`, err);
        cloudTracks.push(track);
      }
    } else {
      cloudTracks.push(track);
    }
  }

  onProgress?.("Finalizing Deployment", 95);
  const cloudAlbum = { 
    ...album, 
    ownerId: userId, 
    tracks: cloudTracks, 
    coverImage: cloudCover,
    artistImage: cloudArtistImg,
    isPublic: true 
  };

  await setDoc(doc(db, "projects", album.id), cloudAlbum);
  onProgress?.("Deployment Successful", 100);

  return `${window.location.origin}${window.location.pathname}?id=${album.id}`;
};

export const saveAlbumToCloud = publishToCloud;

export const fetchAllPublicAlbums = async (): Promise<Album[]> => {
  if (!db) return [];
  try {
    const q = query(collection(db, "projects"), orderBy("createdAt", "desc"), limit(50));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => doc.data() as Album);
  } catch (e) {
    console.error("Cloud fetch failed:", e);
    return [];
  }
};

export const fetchProjectFromCloud = async (id: string): Promise<Album | null> => {
  if (!db) return null;
  try {
    const docSnap = await getDoc(doc(db, "projects", id));
    return docSnap.exists() ? docSnap.data() as Album : null;
  } catch (error) {
    console.error("Fetch project failed:", error);
    return null;
  }
};

export const deleteCloudAlbum = async (albumId: string) => {
  if (!db) return;
  try {
    await deleteDoc(doc(db, "projects", albumId));
  } catch (e) {
    console.error("Delete failed:", e);
  }
};

export const subscribeToComments = (albumId: string, trackId: string | null, callback: (comments: Comment[]) => void) => {
  if (!db) return () => {};
  const q = query(
    collection(db, "projects", albumId, "comments"), 
    where("trackId", "==", trackId || "album"),
    orderBy("timestamp", "desc"),
