async function uploadToStorage(path: string, blob: Blob | File, onProgress?: (percent: number) => void): Promise<string> {
  if (!storage) {
    initializeFirebase();
    if (!storage) throw new Error("Storage service unavailable");
  }
  const storageRef = ref(storage, path);
  const uploadTask = uploadBytesResumable(storageRef, blob);

  return new Promise((resolve, reject) => {
    uploadTask.on('state_changed', 
      (snapshot) => {
        const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        if (onProgress) onProgress(progress);
      }, 
      (error) => reject(error), 
      async () => {
        const url = await getDownloadURL(uploadTask.snapshot.ref);
        resolve(url);
      }
    );
  });
}

async function dataUrlToBlob(url: string): Promise<Blob> {
  const res = await fetch(url);
  return await res.blob();
}

export const publishToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  if (!db || !storage) {
    initializeFirebase();
    if (!db || !storage) throw new Error("Cloud backend not initialized");
  }
  const userId = auth?.currentUser?.uid || 'anonymous';

  onProgress?.("Establishing Link...", 5);

  // 1. Upload Cover Artwork
  let cloudCover = album.coverImage;
  if (album.coverImage.startsWith('blob:')) {
    onProgress?.("Uploading Graphics", 10);
    const blob = await dataUrlToBlob(album.coverImage);
    cloudCover = await uploadToStorage(`albums/${album.id}/cover.png`, blob);
  }

  // 2. Upload Artist Image
  let cloudArtistImg = album.artistImage;
  if (album.artistImage && album.artistImage.startsWith('blob:')) {
    const blob = await dataUrlToBlob(album.artistImage);
    cloudArtistImg = await uploadToStorage(`albums/${album.id}/artist.png`, blob);
  }

  // 3. Upload Tracks
  const cloudTracks: Track[] = [];
  for (let i = 0; i < album.tracks.length; i++) {
    const track = album.tracks[i];
    if (track.file) {
      const gcsPath = `albums/${album.id}/tracks/${track.id}_${track.file.name}`;
      try {
        const cloudUrl = await uploadToStorage(gcsPath, track.file, (p) => {
          const base = 20 + (i / album.tracks.length) * 70;
          const current = (p / album.tracks.length) * 0.7;
          onProgress?.(`Transferring Track ${i+1}/${album.tracks.length}`, Math.round(base + current));
        });
        cloudTracks.push({ ...track, url: cloudUrl, file: undefined as any });
      } catch (err) {
        console.error(`Upload failed for ${track.title}`, err);
        cloudTracks.push(track);
      }
    } else {
      cloudTracks.push(track);
    }
  }

  onProgress?.("Verifying Deployment", 95);
  const cloudAlbum = { 
    ...album, 
    ownerId: userId, 
    tracks: cloudTracks, 
    coverImage: cloudCover,
    artistImage: cloudArtistImg,
    isPublic: true 
  };

  await setDoc(doc(db, "projects", album.id), cloudAlbum);
  onProgress?.("Online", 100);

  return `${window.location.origin}${window.location.pathname}?id=${album.id}`;
};

