import { Album, Comment } from '../types';

const DB_NAME = 'VibeStreamStorage';
const STORE_NAME = 'albums';
const COMMENT_STORE = 'comments';
const VERSION = 2;

const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, VERSION);
    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains(COMMENT_STORE)) {
        const cStore = db.createObjectStore(COMMENT_STORE, { keyPath: 'id', autoIncrement: true });
        cStore.createIndex('albumId', 'albumId', { unique: false });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const saveAlbumToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  onProgress?.("Encoding Local Archive...", 30);
  const db = await openDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  const store = tx.objectStore(STORE_NAME);

  onProgress?.("Storing Media Bits...", 70);
  return new Promise((resolve, reject) => {
    const request = store.put(album);
    request.onsuccess = () => {
      onProgress?.("Vault Secured", 100);
      resolve(album.id);
    };
    request.onerror = () => reject(request.error);
  });
};

export const publishToCloud = saveAlbumToCloud;

export const fetchAllPublicAlbums = async (): Promise<Album[]> => {
  try {
    const db = await openDB();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    return new Promise((resolve, reject) => {
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result.sort((a: any, b: any) => b.createdAt - a.createdAt));
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    return [];
  }
};

export const fetchProjectFromCloud = async (id: string): Promise<Album | null> => {
  const db = await openDB();
  const tx = db.transaction(STORE_NAME, 'readonly');
  const store = tx.objectStore(STORE_NAME);
  return new Promise((resolve, reject) => {
    const request = store.get(id);
    request.onsuccess = () => resolve(request.result || null);
    request.onerror = () => reject(request.error);
  });
};

export const deleteCloudAlbum = async (id: string): Promise<void> => {
  const db = await openDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  const store = tx.objectStore(STORE_NAME);
  return new Promise((resolve, reject) => {
    const request = store.delete(id);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
};

// Simplified local comment logic
export const subscribeToComments = (albumId: string, trackId: string | null, callback: (comments: Comment[]) => void) => {
  const sync = async () => {
    const db = await openDB();
    const tx = db.transaction(COMMENT_STORE, 'readonly');
    const store = tx.objectStore(COMMENT_STORE);
    const request = store.getAll();
    request.onsuccess = () => {
      const all = request.result as Comment[];
      const filtered = all.filter(c => c.id.startsWith(albumId) && (trackId ? c.trackId === trackId : c.trackId === 'album'));
      callback(filtered.sort((a, b) => b.timestamp - a.timestamp));
    };
  };
  sync();
  const interval = setInterval(sync, 2000);
  return () => clearInterval(interval);
};

export const postComment = async (albumId: string, comment: Omit<Comment, 'id'>) => {
  const db = await openDB();
  const tx = db.transaction(COMMENT_STORE, 'readwrite');
  const store = tx.objectStore(COMMENT_STORE);
  const id = `${albumId}_${Date.now()}_${Math.random()}`;
  return new Promise((resolve, reject) => {
    const request = store.add({ ...comment, id });
    request.onsuccess = () => resolve(id);
    request.onerror = () => reject(request.error);
  });
};

