const dataUrlToBlob = async (url: string): Promise<Blob> => {
  const res = await fetch(url);
  return await res.blob();
};

const uploadFile = async (path: string, blobOrFile: Blob | File, onProgress?: (p: number) => void): Promise<string> => {
  if (!ensureInitialized()) throw new Error("Cloud services initialization failed");
  if (!storage) throw new Error("Storage service unavailable");

  const storageRef = ref(storage, path);
  const uploadTask = uploadBytesResumable(storageRef, blobOrFile);

  return new Promise((resolve, reject) => {
    uploadTask.on('state_changed', 
      (snapshot) => {
        const p = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        if (onProgress) onProgress(p);
      },
      (error) => {
        console.error("Upload task failed:", error);
        reject(error);
      },
      async () => {
        const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
        resolve(downloadURL);
      }
    );
  });
};

export const publishToCloud = async (album: Album, onProgress?: (status: string, percent: number) => void): Promise<string> => {
  if (!ensureInitialized()) throw new Error("Cloud services initialization failed");
  if (!db || !storage) throw new Error("Cloud environment offline");

  onProgress?.("Initiating Cloud Uplink...", 5);

  // 1. Upload Cover Image
  let finalCover = album.coverImage;
  if (album.coverImage.startsWith('blob:')) {
    onProgress?.("Uploading Artwork...", 10);
    const blob = await dataUrlToBlob(album.coverImage);
    finalCover = await uploadFile(`albums/${album.id}/cover.png`, blob);
  }

  // 2. Upload Artist Image
  let finalArtistImg = album.artistImage;
  if (album.artistImage && album.artistImage.startsWith('blob:')) {
    const blob = await dataUrlToBlob(album.artistImage);
    finalArtistImg = await uploadFile(`albums/${album.id}/artist.png`, blob);
  }

  // 3. Upload Tracks
  const finalTracks: Track[] = [];
  for (let i = 0; i < album.tracks.length; i++) {
    const track = album.tracks[i];
    const trackProgressBase = 20 + (i / album.tracks.length) * 70;

    if (track.file) {
      onProgress?.(`Transferring Track ${i + 1}/${album.tracks.length}`, Math.round(trackProgressBase));
      const gcsPath = `albums/${album.id}/tracks/${track.id}_${track.file.name}`;
      const url = await uploadFile(gcsPath, track.file);
      finalTracks.push({ ...track, url, file: undefined });
    } else {
      finalTracks.push(track);
    }
  }

  onProgress?.("Indexing Project...", 95);
  const cloudAlbum = {
    ...album,
    coverImage: finalCover,
    artistImage: finalArtistImg,
    tracks: finalTracks,
    isPublic: true
  };

  await setDoc(doc(db, "albums", album.id), cloudAlbum);
  onProgress?.("Deployment Successful", 100);

  return `${window.location.origin}${window.location.pathname}?id=${album.id}`;
};

