};

let app: FirebaseApp;
let db: Firestore;
let storage: FirebaseStorage;

const ensureInitialized = () => {
  if (db && storage) return true;

  try {
    if (!getApps().length) {
      app = initializeApp(firebaseConfig);
    } else {
      app = getApp();
    }

    // Attempt service retrieval
    db = getFirestore(app);
    storage = getStorage(app);

    return true;
  } catch (error: any) {
    console.error("Cloud Services Initialization Error:", error.message || error);
    return false;
  }
};

// Immediate initialization attempt on module load
