  if (!ensureInitialized()) return false;
  try {
    // Basic connectivity check: list documents from a collection with a limit of 1
    const q = query(collection(db, "albums"), limit(1));
    await getDocs(q);
    return true;
  } catch (e) {
    console.warn("Cloud connection check failed (database might be empty or restricted):", e);
